{"command": "cd /workspace/src && cat > core.c <<'EOF'
#include "core.h"

/* ================================================================= */
/* Arena allocator */
typedef struct ArenaChunk {
  struct ArenaChunk *pNext;
  size_t n;
  size_t used;
  char z[1];
} ArenaChunk;
#define ARENA_CHUNK 4096

void arenaInit(Arena *p){ p->pFirst = p->pLast = 0; p->used = 0; }
void arenaReset(Arena *p){
  ArenaChunk *c = p->pFirst;
  while( c ){ ArenaChunk *n = c->pNext; free(c); c = n; }
  arenaInit(p);
}
void *arenaAlloc(Arena *p, size_t n){
  ArenaChunk *c;
  n = (n+7)&~(size_t)7;
  if( p->pLast && p->pLast->used + n <= p->pLast->n ){
    void *r = p->pLast->z + p->pLast->used;
    p->pLast->used += n;
    return r;
  }
  if( n+sizeof(ArenaChunk) < ARENA_CHUNK ){
    c = (ArenaChunk*)malloc(ARENA_CHUNK);
    c->n = ARENA_CHUNK - sizeof(ArenaChunk);
  }else{
    c = (ArenaChunk*)malloc(sizeof(ArenaChunk)+n);
    c->n = n;
  }
  c->used = 0;
  c->pNext = 0;
  if( p->pLast ) p->pLast->pNext = c; else p->pFirst = c;
  p->pLast = c;
  c->used = n;
  return c->z;
}
char *arenaStrdup(Arena *p, const char *z){
  size_t n = strlen(z)+1;
  char *r = arenaAlloc(p, n);
  memcpy(r, z, n);
  return r;
}
char *arenaStrndup(Arena *p, const char *z, int n){
  char *r = arenaAlloc(p, n+1);
  memcpy(r, z, n);
  r[n] = 0;
  return r;
}
void *arenaRealloc(Arena *p, void *old, size_t oldn, size_t newn){
  void *r = arenaAlloc(p, newn);
  if( old ){ memcpy(r, old, oldn<newn?oldn:newn); }
  return r;
}

/* ================================================================= */
/* misc helpers */
char *strDup(const char *z){ 
  if( z==0 ) return 0;
  { size_t n = strlen(z)+1; char *r = malloc(n); memcpy(r,z,n); return r; }
}
char *strPrintf(const char *fmt, ...){
  char buf[256];
  va_list ap;
  int n;
  char *z;
  va_start(ap, fmt);
  n = vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  if( n < 0 ) n = 0;
  if( (size_t)n < sizeof(buf) ){
    return strDup(buf);
  }else{
    z = malloc(n+1);
    va_start(ap, fmt);
    vsnprintf(z, n+1, fmt, ap);
    va_end(ap);
    return z;
  }
}
char *strAppend(char *z, const char *add){
  size_t n, m;
  char *r;
  if( z==0 ) return strDup(add);
  n = strlen(z); m = strlen(add);
  r = realloc(z, n+m+1);
  memcpy(r+n, add, m+1);
  return r;
}
int strEq(const char *a, const char *b){
  if( a==0 || b==0 ) return a==b;
  return strcmp(a,b)==0;
}
int strEqN(const char *a, const char *b, int n){
  if( a==0 || b==0 ) return a==b;
  return strncmp(a,b,n)==0;
}
char *strUpper(const char *z){
  char *r = strDup(z);
  int i;
  for(i=0; r[i]; i++) r[i] = toupper((unsigned char)r[i]);
  return r;
}
int isNumericText(const char *z){
  int i = 0;
  int seenDigit = 0;
  if( z==0 || z[0]==0 ) return 0;
  while( z[i]==' ' || z[i]=='\t' || z[i]=='\n' || z[i]=='\r' || z[i]=='\f' ) i++;
  if( z[i]=='+' || z[i]=='-' ) i++;
  while( isdigit((unsigned char)z[i]) ){ i++; seenDigit=1; }
  if( z[i]=='.' ){
    i++;
    while( isdigit((unsigned char)z[i]) ){ i++; seenDigit=1; }
  }
  if( !seenDigit ) return 0;
  if( z[i]=='e' || z[i]=='E' ){
    i++;
