        intpart[ndig+(-nfrac)] = 0;
        strcpy(fracpart, "0");
      }else{
        memcpy(intpart, digits, e2+1);
        intpart[e2+1] = 0;
        memcpy(fracpart, digits+e2+1, nfrac);
        fracpart[nfrac] = 0;
      }
      sprintf(out, "%s%s.%s", neg?"-":"", intpart, fracpart);
    }else{
      /* exponential notation */
      char digits2[40];
      strcpy(digits2, digits);
      sprintf(out, "%s%s.0e%s%02d", neg?"-":"", digits2, e2<0?"-":"+", e2<0?-e2:e2);
