 {"TRIGGER",TK_TRIGGER},{"UNBOUNDED",TK_UNBOUNDED},{"UNION",TK_UNION},
 {"UNIQUE",TK_UNIQUE},{"UPDATE",TK_UPDATE},{"USING",TK_USING},
 {"VACUUM",TK_VACUUM},{"VALUES",TK_VALUES},{"VIEW",TK_VIEW},
 {"VIRTUAL",TK_VIRTUAL},{"WHEN",TK_WHEN},{"WHERE",TK_WHERE},{"WINDOW",TK_WINDOW},
 {"WITH",TK_WITH},{"WITHOUT",TK_WITHOUT},
};
#define NKW ((int)(sizeof(aKw)/sizeof(aKw[0])))

static const char *zIn = 0;
static int iLine = 1;

void lexInit(const char *z){ zIn = z; iLine = 1; }

static int isIdChar(int c){
  return isalnum(c) || c=='_' || c=='$' || (c&0x80)!=0;
}
int tokIs(const Token *t, int type){ return t->type==type; }
const char *tokName(const Token *t){
  static char buf[64];
  switch( t->type ){
    case TK_EOF: return "EOF";
    default:
      snprintf(buf, sizeof(buf), "%.*s", t->n, t->z);
      return buf;
  }
}

int lexNext(Token *t){
  int c;
  const char *z = zIn;
  const char *start;
  int line = iLine;
  if( z==0 || *z==0 ){ t->type = TK_EOF; t->z = zIn; t->n = 0; t->pos = 0; t->line = line; return t->type; }
  t->line = line;
  c = (unsigned char)z[0];
  switch( c ){
    case ' ': case '\t': case '\r': case '\n': case '\f': case '\v': {
      start = z;
      while( (c=(unsigned char)z[0])==' '||c=='\t'||c=='\r'||c=='\n'||c=='\f'||c=='\v' ){
        if( c=='\n' ) iLine++;
        z++;
      }
      t->type = TK_SPACE; t->z = start; t->n = (int)(z-start);
      break;
    }
    case '-': {
      if( z[1]=='-' ){
        start = z;
        while( (c=(unsigned char)z[0])!=0 && c!='\n' ) z++;
        if( c=='\n' ) z++;
        t->type = TK_COMMENT; t->z = start; t->n = (int)(z-start);
        break;
      }
      if( z[1]=='>' ){
        if( z[2]=='>' ){ z += 3; t->type = TK_DOUBLEARROW; }
        else { z += 2; t->type = TK_ARROW; }
        break;
      }
      z++;
      t->type = TK_MINUS;
      break;
    }
    case '+': z++; t->type = TK_PLUS; break;
    case '*': z++; t->type = TK_STAR; break;
    case '/': {
      if( z[1]=='*' ){
        start = z;
        z += 2;
        while( (c=(unsigned char)z[0])!=0 ){
          if( c=='*' && z[1]=='/' ){ z += 2; break; }
          if( c=='\n' ) iLine++;
          z++;
        }
        t->type = TK_COMMENT; t->z = start; t->n = (int)(z-start);
        break;
      }
      z++;
      t->type = TK_SLASH;
      break;
    }
    case '%': z++; t->type = TK_PERCENT; break;
    case '=': {
      if( z[1]=='=' ){ z += 2; t->type = TK_EQ; }
      else { z++; t->type = TK_EQ; }
      break;
    }
    case '!': {
      if( z[1]=='=' ){ z += 2; t->type = TK_NE; }
      else { z++; t->type = TK_BANG; }
      break;
    }
    case '|': {
      if( z[1]=='|' ){ z += 2; t->type = TK_CONCAT; }
      else { z++; t->type = TK_PIPE; }
      break;
    }
    case '&': z++; t->type = TK_AMP; break;
    case '<': {
      if( z[1]=='=' ){ z += 2; t->type = TK_LE; }
      else if( z[1]=='>' ){ z += 2; t->type = TK_NE; }
      else if( z[1]=='<' ){ z += 2; t->type = TK_LSHIFT; }
      else { z++; t->type = TK_LT; }
      break;
    }
    case '>': {
      if( z[1]=='=' ){ z += 2; t->type = TK_GE; }
      else if( z[1]=='>' ){ z += 2; t->type = TK_RSHIFT; }
      else { z++; t->type = TK_GT; }
      break;
    }
    case '~': z++; t->type = TK_TILDE; break;
    case ';': z++; t->type = TK_SEMI; break;
    case '(': z++; t->type = TK_LP; break;
    case ')': z++; t->type = TK_RP; break;
    case ',': z++; t->type = TK_COMMA; break;
    case '.': {
      if( isdigit((unsigned char)z[1]) ){ goto number; }
      z++;
      t->type = TK_DOT;
      break;
    }
    case '\'': case '"': case '`': {
      int q = c;
      start = z;
      z++;
      while( (c=(unsigned char)z[0])!=0 ){
        if( c==q ){
          if( z[1]==q ){ z += 2; continue; }
          break;
        }
        if( c=='\n' ) iLine++;
        z++;
      }
      if( c==0 ){
        t->type = TK_ILLEGAL;
      }else{
        z++;
        t->type = (q=='\'' ? TK_STRING : TK_ID_Q);
      }
      t->z = start;
      t->n = (int)(z-start);
      break;
    }
    case '[': {
      start = z;
      z++;
      while( (c=(unsigned char)z[0])!=0 && c!=']' ){
        if( c=='\n' ) iLine++;
        z++;
      }
      if( c==']' ) z++;
      t->type = TK_ID_Q;
      t->z = start; t->n = (int)(z-start);
      break;
    }
    case '0': case '1': case '2': case '3': case '4':
    case '5': case '6': case '7': case '8': case '9':
    number: {
      start = z;
      if( c=='0' && (z[1]=='x' || z[1]=='X') && isxdigit((unsigned char)z[2]) ){
        z += 2;
        while( isxdigit((unsigned char)z[0]) ) z++;
        t->type = TK_INTEGER;
      }else{
        int isFloat = 0;
        while( isdigit((unsigned char)z[0]) ) z++;
        if( z[0]=='.' && isdigit((unsigned char)z[1]) ){
          isFloat = 1; z++;
          while( isdigit((unsigned char)z[0]) ) z++;
        }
        if( (z[0]=='e'||z[0]=='E') &&
            (isdigit((unsigned char)z[1]) ||
             ((z[1]=='+'||z[1]=='-') && isdigit((unsigned char)z[2]))) ){
          isFloat = 1;
          z += 2;
          while( isdigit((unsigned char)z[0]) ) z++;
        }
        t->type = isFloat ? TK_FLOAT : TK_INTEGER;
      }
      if( z[0]=='e' || z[0]=='E' ){ /* 1e5 not supported? keep as integer */ }
      if( isIdChar((unsigned char)z[0]) ){
        while( isIdChar((unsigned char)z[0]) ) z++;
        t->type = TK_ILLEGAL;
      }
      t->z = start; t->n = (int)(z-start);
      break;
    }
    case '?': z++; t->type = TK_QUESTION; break;
    case ':': {
      if( z[1]==':' ){ z += 2; t->type = TK_ILLEGAL; break; }
      z++;
      while( isIdChar((unsigned char)z[0]) ) z++;
      t->type = TK_VARIABLE; break;
    }
    case '@': case '$': {
      z++;
      if( isIdChar((unsigned char)z[0]) ){ while( isIdChar((unsigned char)z[0]) ) z++; }
      t->type = TK_VARIABLE; break;
    }
    case 'x': case 'X': {
      if( z[1]=='\'' && isxdigit((unsigned char)z[2]) ){
        start = z;
        z += 2;
        while( isxdigit((unsigned char)z[0]) ) z++;
        if( z[0]=='\'' ) z++;
        t->type = TK_BLOB;
        t->z = start; t->n = (int)(z-start);
        break;
      }
      /* fall through as identifier */
    }
    default: {
      if( isalpha(c) || c=='_' || (c&0x80)!=0 ){
        start = z;
        while( isIdChar((unsigned char)z[0]) ) z++;
        t->z = start;
        t->n = (int)(z-start);
        /* keyword lookup */
        {
          int i;
          char buf[64];
          int n = t->n;
          if( n > (int)sizeof(buf)-1 ) n = (int)sizeof(buf)-1;
          for(i=0;i<n;i++) buf[i] = toupper((unsigned char)start[i]);
          buf[n] = 0;
          t->type = TK_ID;
          {
            int lo = 0, hi = NKW-1;
            while( lo<=hi ){
              int mid = (lo+hi)/2;
              int rc = strcmp(buf, aKw[mid].z);
              if( rc==0 ){ t->type = aKw[mid].type; break; }
              if( rc<0 ) hi = mid-1; else lo = mid+1;
            }
          }
        }
        break;
      }
      z++;
      t->type = TK_ILLEGAL;
      break;
    }
  }
  t->pos = (int)(zIn - (z - t->n));
  return t->type;
}
EOF
gcc -c -O1 -o /tmp/lex.o lex.c -Wall 2>&1 | head; echo rc=$?"}

