    Expr *pWhere;
  } ci;
  /* create view */
  struct {
    char *zTab, *zDb, *zName;
    int ifNotExists, isTemp;
    ExprList *pCols;
    Select *pSelect;
  } cv;
  /* create trigger */
  struct {
    char *zName, *zTab, *zDb;
    int ifNotExists, isTemp;
    int when;      /* 0 before, 1 after, 2 instead of */
    int event;     /* 1 insert, 2 delete, 3 update */
    int each;
    Expr *pWhen;
    struct Stmt **apStmt;
    int nStmt;
    char *zBody;
  } ctr;
  /* drop */
  struct {
    int what;   /* 0 table, 1 index, 2 view, 3 trigger */
    char *zName, *zDb;
    int ifExists;
  } drop;
  /* alter */
  struct {
    char *zTab, *zDb, *zNew, *zOld, *zType;
    struct ColDef col;
    int op;    /* 0 rename table, 1 add column, 2 rename column, 3 drop column */
  } alt;
  /* pragma */
  struct {
    char *zName, *zDb;
    ExprList *pArgs;
    int isSet;
    Value v;
    Expr *pValue;
  } prg;
  /* misc */
  int txnOp;   /* 0 begin, 1 commit, 2 rollback, 3 savepoint, 4 release */
  char *zName;
  int txnMode;
  int isExplain, explainMode;
  int vacuumAnalyze;
  int hasIfNotExists;
  struct With *pWith;
};

