{"command": "cd /workspace/src && cat > parse.c <<'EOF'
#include "core.h"
#include "lex.h"
#include "parse.h"

typedef struct Parse {
  Arena *pA;
  Token tok;
  Token tokNext;
  int haveNext;
  const char *zSql;
  Error err;
  int nErr;
  int parseDepth;
  int nVar;
  int nParen;
} Parse;

static void pxAdvance(Parse *p);
static void pxGet(Parse *p);

static void pxErr(Parse *p, const char *fmt, ...){
  va_list ap;
  if( p->nErr ) return;
  p->nErr++;
  p->err.hasPos = 1;
  p->err.pos = p->tok.pos;
  va_start(ap, fmt);
  vsnprintf(p->err.msg, ERRBUF, fmt, ap);
  va_end(ap);
}
static void pxErrAt(Parse *p, int pos, const char *fmt, ...){
  va_list ap;
  if( p->nErr ) return;
  p->nErr++;
  p->err.hasPos = 1;
  p->err.pos = pos;
  va_start(ap, fmt);
  vsnprintf(p->err.msg, ERRBUF, fmt, ap);
  va_end(ap);
}
static void pxSyntaxError(Parse *p){
  if( p->nErr ) return;
  if( p->tok.type==TK_EOF ){
    pxErrAt(p, p->tok.pos, "incomplete input");
  }else{
    pxErrAt(p, p->tok.pos, "near \"%s\": syntax error", tokName(&p->tok));
  }
}
static int pxIs(Parse *p, int type){
  return p->tok.type==type;
}
static int pxAccept(Parse *p, int type){
  if( pxIs(p, type) ){ pxGet(p); return 1; }
  return 0;
}
static int pxExpect(Parse *p, int type){
  if( pxIs(p, type) ){ pxGet(p); return 1; }
  pxSyntaxError(p);
  return 0;
}

static Expr *pxExpr(Parse *p);
static Select *pxSelect(Parse *p);
static ExprList *pxExprList0(Parse *p, int allowStar, int withNames);
static Window *pxWindow(Parse *p);

/* ------------------------------------------------------------------ */
static Token *pxPeekTok(Parse *p){
  if( !p->haveNext ){ p->tokNext = p->tok; pxAdvance(p); p->tokNext = p->tok; p->tok = p->tokNext; }
  return &p->tok;
}

static Expr *pxNewExpr(Parse *p, int op){
  Expr *e = arenaAlloc(p->pA, sizeof(Expr));
  memset(e, 0, sizeof(Expr));
  e->op = op;
  valInit(&e->v);
  return e;
}
static ExprList *pxNewList(Parse *p){
  ExprList *l = arenaAlloc(p->pA, sizeof(ExprList));
  memset(l, 0, sizeof(*l));
  return l;
}
static void pxListAppend(Parse *p, ExprList *l, Expr *e, const char *zName, int sortOrder){
  if( l->nExpr>=l->nCap ){
    int nc = l->nCap ? l->nCap*2 : 4;
    Expr **ap = arenaAlloc(p->pA, nc*sizeof(Expr*));
    char **az = arenaAlloc(p->pA, nc*sizeof(char*));
    int *ai = arenaAlloc(p->pA, nc*sizeof(int));
    if( l->nCap ){ memcpy(ap, l->apExpr, l->nExpr*sizeof(Expr*));
                  memcpy(az, l->azName, l->nExpr*sizeof(char*));
                  memcpy(ai, l->aiSortOrder, l->nExpr*sizeof(int)); }
    l->apExpr = ap; l->azName = az; l->aiSortOrder = ai; l->nCap = nc;
  }
  l->apExpr[l->nExpr] = e;
  l->azName[l->nExpr] = zName ? arenaStrdup(p->pA, zName) : 0;
  l->aiSortOrder[l->nExpr] = sortOrder;
  l->nExpr++;
}
static SrcList *pxNewSrcList(Parse *p){
  SrcList *s = arenaAlloc(p->pA, sizeof(SrcList));
  memset(s,0,sizeof(*s));
  return s;
}
static SrcItem *pxSrcAppend(Parse *p, SrcList *s){
  if( s->nSrc>=s->nCap ){
    int nc = s->nCap ? s->nCap*2 : 4;
    SrcItem *a = arenaAlloc(p->pA, nc*sizeof(SrcItem));
    if( s->nCap ) memcpy(a, s->a, s->nSrc*sizeof(SrcItem));
    memset(a+s->nCap, 0, (nc-s->nCap)*sizeof(SrcItem));
    s->a = a; s->nCap = nc;
  }
  memset(&s->a[s->nSrc], 0, sizeof(SrcItem));
  s->a[s->nSrc].joinType = JT_INNER;
  return &s->a[s->nSrc++];
}

static char *pxIdText(Parse *p){
  /* convert current identifier token (possibly quoted) to text */
  int n = p->tok.n;
  const char *z = p->tok.z;
  if( n>=2 ){
    char c0 = z[0], c1 = z[n-1];
    if( (c0=='"' && c1=='"') || (c0=='`' && c1=='`') || (c0=='[' && c1==']') ){
      return arenaStrndup(p->pA, z+1, n-2);
    }
    if( c0=='\'' && c1=='\'' ){
      /* strings as identifiers: strip quotes and un-double */
      char *r = arenaAlloc(p->pA, n);
      int i, j = 0;
      for(i=1;i<n-1;i++){
        if( z[i]=='\'' && z[i+1]=='\'' ){ r[j++]='\''; i++; }
        else r[j++] = z[i];
      }
      r[j] = 0;
      return r;
    }
  }
  return arenaStrndup(p->pA, z, n);
}

/* parse an identifier: either a keyword used as identifier or TK_ID */
static int pxIsIdOrKw(Parse *p){
  int t = p->tok.type;
  if( t==TK_ID || t==TK_ID_Q ) return 1;
  if( t>=TK_ABORT && t<=TK_KW_LAST ) return 1;
  return 0;
}
static int pxAcceptId(Parse *p){
  if( pxIsIdOrKw(p) ){ pxGet(p); return 1; }
  return 0;
}

/* ------------------------------------------------------------------ */
/* primary expressions */
static Expr *pxIdExpr(Parse *p, const char *zName, int start){
  Expr *e;
  /* check for special keywords used as values */
  if( pxIs(p, TK_NULL) ){ pxGet(p); e = pxNewExpr(p, TKX_NULL); e->start=start; e->end=p->tok.pos; return e; }
  if( pxIs(p, TK_TRUE) ){ pxGet(p); e = pxNewExpr(p, TKX_INT); valSetInt(p->pA,&e->v,1); return e; }
  if( pxIs(p, TK_FALSE) ){ pxGet(p); e = pxNewExpr(p, TKX_INT); valSetInt(p->pA,&e->v,0); return e; }
  (void)zName;
  return 0;
}

static Expr *pxPrimary(Parse *p){
  Expr *e;
  int start = p->tok.pos;
  switch( p->tok.type ){
    case TK_INTEGER: {
      const char *z = p->tok.z;
      int n = p->tok.n;
      e = pxNewExpr(p, TKX_INT);
      if( z[0]=='0' && (z[1]=='x'||z[1]=='X') ){
        i64 v = 0;
        int i;
        for(i=2;i<n;i++){
          char c = z[i];
          int d = isdigit((unsigned char)c) ? c-'0' : (tolower(c)-'a'+10);
          v = v*16 + d;
        }
        valSetInt(p->pA, &e->v, v);
      }else{
        char *tmp = arenaStrndup(p->pA, z, n);
        valSetInt(p->pA, &e->v, strtoll(tmp,0,10));
      }
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_FLOAT: {
      char *tmp = arenaStrndup(p->pA, p->tok.z, p->tok.n);
      e = pxNewExpr(p, TKX_REAL);
      valSetReal(p->pA, &e->v, strtod(tmp,0));
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_STRING: {
      const char *z = p->tok.z;
      int n = p->tok.n;
      char *r = arenaAlloc(p->pA, n);
      int i, j = 0;
      for(i=1;i<n-1;i++){
        if( z[i]=='\'' && z[i+1]=='\'' ){ r[j++]='\''; i++; }
        else r[j++] = z[i];
      }
      e = pxNewExpr(p, TKX_TEXT);
      valSetTextN(p->pA, &e->v, r, j);
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_BLOB: {
      const char *z = p->tok.z;
      int n = p->tok.n;
      char *r = arenaAlloc(p->pA, (n-3)/2+1);
      int i, j = 0;
      for(i=2;i<n-1;i+=2){
        int hi = isdigit((unsigned char)z[i]) ? z[i]-'0' : (tolower(z[i])-'a'+10);
        int lo = isdigit((unsigned char)z[i+1]) ? z[i+1]-'0' : (tolower(z[i+1])-'a'+10);
        r[j++] = (char)((hi<<4)|lo);
      }
      e = pxNewExpr(p, TKX_BLOB);
      valSetBlob(p->pA, &e->v, r, j);
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_LP: {
      Select *s;
      Expr *x;
      int qStart = p->tok.pos;
      pxGet(p);
      s = pxSelect(p);
      if( pxIs(p, TK_SELECT) || pxIs(p, TK_VALUES) ){
        e = pxNewExpr(p, TKX_SELECT);
        e->pSelect = s;
        pxExpect(p, TK_RP);
        e->start = qStart; e->end = p->tok.pos;
        return e;
      }
      /* parenthesized expression */
      x = s ? 0 : pxExpr(p);
      if( x==0 ) x = pxExpr(p);
      if( !pxAccept(p, TK_RP) ){ pxSyntaxError(p); return x; }
      x->start = qStart;
      return x;
    }
    case TK_VARIABLE: {
      char *z = pxIdText(p);
      e = pxNewExpr(p, TKX_VARIABLE);
      e->zTok = arenaStrndup(p->pA, p->tok.z, p->tok.n);
      (void)z;
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_QUESTION: case TK_COLON: case TK_AT: case TK_DOLLAR: {
      e = pxNewExpr(p, TKX_VARIABLE);
      if( pxIs(p, TK_QUESTION) ){
        e->zTok = strPrintf("%d", ++p->nVar);
      }else{
        e->zTok = arenaStrndup(p->pA, p->tok.z, p->tok.n);
      }
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_ID_Q: case TK_ID: case TK_ROWID:
    case TK_ABORT: case TK_ACTION: case TK_AFTER: case TK_ANALYZE: case TK_ASC:
    case TK_ATTACH: case TK_BEFORE: case TK_BEGIN: case TK_BY: case TK_CASCADE:
    case TK_CHECK: case TK_COLLATE: case TK_COLUMNKW: case TK_COMMIT:
    case TK_CONFLICT: case TK_CONSTRAINT: case TK_CREATE: case TK_CROSS:
    case TK_CURRENT_DATE: case TK_CURRENT_TIME: case TK_CURRENT_TIMESTAMP:
    case TK_DATABASE: case TK_DEFAULT: case TK_DEFERRABLE: case TK_DEFERRED:
    case TK_DESC: case TK_DETACH: case TK_DISTINCT: case TK_DO: case TK_DROP:
    case TK_EACH: case TK_ELSE: case TK_END: case TK_ESCAPE: case TK_EXCEPT:
    case TK_EXCLUDE: case TK_EXCLUSIVE: case TK_FAIL: case TK_FILTER:
    case TK_FIRST: case TK_FOLLOWING: case TK_FOR: case TK_FOREIGN:
    case TK_FULL: case TK_GROUP: case TK_GROUPS: case TK_HAVING: case TK_IF:
    case TK_IGNORE: case TK_IMMEDIATE: case TK_INDEX: case TK_INDEXED:
    case TK_INITIALLY: case TK_INNER: case TK_INSTEAD: case TK_INTERSECT:
    case TK_INTO: case TK_ISNULL: case TK_JOIN: case TK_KEY: case TK_LAST:
    case TK_LEFT: case TK_LIMIT: case TK_MATERIALIZED: case TK_NATURAL:
    case TK_NO: case TK_NOTHING: case TK_NOTNULL: case TK_NULLS: case TK_OF:
    case TK_OFFSET: case TK_ON: case TK_ORDER: case TK_OTHERS: case TK_OUTER:
    case TK_OVER: case TK_PARTITION: case TK_PLAN: case TK_PRAGMA:
    case TK_PRECEDING: case TK_PRIMARY: case TK_QUERY: case TK_RAISE:
    case TK_RANGE: case TK_RECURSIVE: case TK_REFERENCES: case TK_REINDEX:
    case TK_RELEASE: case TK_RENAME: case TK_REPLACE: case TK_RESTRICT:
    case TK_RETURNING: case TK_RIGHT: case TK_ROLLBACK: case TK_ROW:
    case TK_ROWS: case TK_SAVEPOINT: case TK_SET: case TK_TABLE: case TK_TEMP:
    case TK_TEMPORARY: case TK_THEN: case TK_TIES: case TK_TO:
    case TK_TRANSACTION: case TK_TRIGGER: case TK_UNBOUNDED: case TK_UNION:
    case TK_UNIQUE: case TK_UPDATE: case TK_USING: case TK_VACUUM:
    case TK_VALUES: case TK_VIEW: case TK_VIRTUAL: case TK_WHEN: case TK_WHERE:
    case TK_WINDOW: case TK_WITH: case TK_WITHOUT: case TK_MATCH: {
      /* identifier */
      char *zName = pxIdText(p);
      int t = p->tok.type;
      pxGet(p);
      if( t==TK_CURRENT_DATE || t==TK_CURRENT_TIME || t==TK_CURRENT_TIMESTAMP ){
        e = pxNewExpr(p, t==TK_CURRENT_DATE?TKX_CURRENT_DATE:(t==TK_CURRENT_TIME?TKX_CURRENT_TIME:TKX_CURRENT_TIMESTAMP));
        e->start = start; e->end = p->tok.pos;
        return e;
      }
      if( t==TK_ROWID ){
        e = pxNewExpr(p, TKX_ROWID);
        e->zTok = arenaStrdup(p->pA, "rowid");
        e->start = start; e->end = p->tok.pos;
        return e;
      }
      if( pxIs(p, TK_LP) ){
        /* function call */
        ExprList *args;
        int fStart = start;
        int dstart = p->tok.pos;
        pxGet(p);
        if( pxIs(p, TK_STAR) ){
          pxGet(p);
          args = pxNewList(p);
          e = pxNewExpr(p, TKX_FUNCTION);
          e->zTok = zName;
          e->flags |= EF_Distinct;
          e->pList = args;
          args->azName = arenaAlloc(p->pA, sizeof(char*));
          args->apExpr = arenaAlloc(p->pA, sizeof(Expr*));
          args->aiSortOrder = arenaAlloc(p->pA, sizeof(int));
          args->nExpr = 1;
          args->apExpr[0] = pxNewExpr(p, TKX_STAR);
          args->azName[0] = 0;
          args->aiSortOrder[0] = 0;
          pxExpect(p, TK_RP);
        }else{
          args = pxExprList0(p, 1, 0);
          if( args==0 ) args = pxNewList(p);
          if( !pxExpect(p, TK_RP) ) return 0;
          e = pxNewExpr(p, TKX_FUNCTION);
          e->zTok = zName;
          e->pList = args;
        }
        /* window clause */
        if( pxIs(p, TK_OVER) ){
          pxGet(p);
          if( pxIs(p, TK_LP) ){
            e->flags |= EF_Window;
            e->pRight = (Expr*)pxWindow(p);
          }else{
            e->flags |= EF_Window;
            e->zTok2 = arenaStrdup(p->pA, "named");
            /* named window reference: store name in pList? use zTok2 */
            {
              ExprList *l = pxNewList(p);
              Expr *nm = pxNewExpr(p, TKX_TEXT);
              valSetText(p->pA, &nm->v, zName);
              nm->zTok = zName;
              l->nExpr = 1;
              l->apExpr = arenaAlloc(p->pA, sizeof(Expr*));
              l->azName = arenaAlloc(p->pA, sizeof(char*));
              l->aiSortOrder = arenaAlloc(p->pA, sizeof(int));
              l->apExpr[0] = nm;
              l->azName[0] = 0;
              l->aiSortOrder[0] = 0;
              e->pList = l;
            }
            /* keep window name in v.z */
            e->flags |= EF_Partial;
          }
        }
        if( pxIs(p, TK_FILTER) ){
          pxGet(p);
          pxExpect(p, TK_LP);
          pxExpect(p, TK_WHERE);
          e->pRight = (Expr*)pxExpr(p);
          pxExpect(p, TK_RP);
        }
        e->start = fStart; e->end = p->tok.pos;
        (void)dstart;
        return e;
      }
      if( pxIs(p, TK_DOT) ){
        /* qualified name */
        char *zTab = zName;
        char *zCol;
        pxGet(p);
        if( pxIs(p, TK_STAR) ){
          pxGet(p);
          e = pxNewExpr(p, TKX_STAR_TABLE);
          e->zTok = zTab;
          e->start = start; e->end = p->tok.pos;
          return e;
        }
        if( pxIsIdOrKw(p) ){
          zCol = pxIdText(p);
          pxGet(p);
        }else{
          zCol = arenaStrdup(p->pA, "");
          pxSyntaxError(p);
          return 0;
        }
        if( pxIs(p, TK_DOT) ){
          /* db.table.column - ignore db */
          zTab = zCol;
          pxGet(p);
          if( pxIsIdOrKw(p) ){ zCol = pxIdText(p); pxGet(p); }
          else { zCol = arenaStrdup(p->pA,""); pxSyntaxError(p); return 0; }
        }
        e = pxNewExpr(p, TKX_COLUMN);
        e->zTok = zCol;
        e->zTok2 = zTab;
        e->start = start; e->end = p->tok.pos;
        return e;
      }
      if( t==TK_NULL ){
        e = pxNewExpr(p, TKX_NULL);
        e->start = start; e->end = p->tok.pos;
        return e;
      }
      e = pxNewExpr(p, TKX_COLUMN);
      e->zTok = zName;
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_CAST: {
      char *zType;
      int n = 0;
      const char *zStart = p->tok.z;
      pxGet(p);
      if( !pxExpect(p, TK_LP) ) return 0;
      /* collect type tokens until ')' */
      {
        char buf[128];
        buf[0] = 0;
        while( pxIsIdOrKw(p) || pxIs(p, TK_LP) || pxIs(p, TK_RP) || pxIs(p, TK_COMMA) ){
          if( pxIs(p, TK_LP) ){ n += snprintf(buf+n, sizeof(buf)-n, "("); pxGet(p); continue; }
          if( pxIs(p, TK_RP) ) break;
          if( pxIs(p, TK_COMMA) ){ n += snprintf(buf+n, sizeof(buf)-n, ","); pxGet(p); continue; }
          {
            char *z = pxIdText(p);
            n += snprintf(buf+n, sizeof(buf)-n, "%s", z);
            pxGet(p);
            if( pxIs(p, TK_LP) ){
              int k = 0;
              buf[n++] = '(';
              pxGet(p);
              while( (pxIs(p, TK_INTEGER)||pxIs(p, TK_COMMA)||pxIs(p, TK_ID)) && k<10 ){ 
                if( pxIs(p, TK_COMMA) ) buf[n++] = ',';
                else { char *zt = arenaStrndup(p->pA,p->tok.z,p->tok.n); n += snprintf(buf+n, sizeof(buf)-n, "%s", zt); }
                pxGet(p);
                k++;
              }
              buf[n++] = ')';
            }
          }
        }
        zType = arenaStrdup(p->pA, buf);
      }
      if( !pxExpect(p, TK_RP) ) return 0;
      e = pxNewExpr(p, TKX_CAST);
      e->pLeft = pxExpr(p);
      e->zTok = zType;
      e->start = start; e->end = p->tok.pos;
      (void)zStart;
      return e;
    }
    case TK_EXISTS: {
      pxGet(p);
      if( !pxExpect(p, TK_LP) ) return 0;
      e = pxNewExpr(p, TKX_EXISTS);
      e->pSelect = pxSelect(p);
      if( !pxExpect(p, TK_RP) ) return 0;
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_SELECT: case TK_VALUES: {
      e = pxNewExpr(p, TKX_SELECT);
      e->pSelect = pxSelect(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_RAISE: {
      pxGet(p);
      if( !pxExpect(p, TK_LP) ) return 0;
      e = pxNewExpr(p, TKX_RAISE);
      if( pxAcceptId(p) ){
        if( pxIs(p, TK_COMMA) ){
          pxGet(p);
          e->pLeft = pxExpr(p);
        }
      }
      pxExpect(p, TK_RP);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    default:
      return 0;
  }
}

static Window *pxWindow(Parse *p){
  Window *w = arenaAlloc(p->pA, sizeof(Window));
  memset(w, 0, sizeof(*w));
  pxExpect(p, TK_LP);
  if( pxIs(p, TK_RP) ){ pxGet(p); return w; }
  for(;;){
    if( pxIs(p, TK_PARTITION) ){
      pxGet(p);
      w->pPartition = pxExprList0(p, 0, 0);
      if( !w->pPartition ) w->pPartition = pxNewList(p);
      if( !pxAccept(p, TK_COMMA) ) break;
      continue;
    }
    if( pxIs(p, TK_ORDER) ){
      pxGet(p);
      pxExpect(p, TK_BY);
      w->pOrderBy = pxExprList0(p, 0, 1);
      if( !w->pOrderBy ) w->pOrderBy = pxNewList(p);
      if( !pxAccept(p, TK_COMMA) ) break;
      continue;
    }
    break;
  }
  /* frame spec */
  if( pxIs(p, TK_ROWS) || pxIs(p, TK_RANGE) || pxIs(p, TK_GROUPS) ){
    if( pxIs(p, TK_ROWS) ) w->rowsMode = 0;
    else if( pxIs(p, TK_RANGE) ) w->rowsMode = 1;
    else w->rowsMode = 2;
    pxGet(p);
    if( pxIs(p, TK_UNBOUNDED) ){ w->eStart = TK_UNBOUNDED; pxGet(p); if( pxIs(p, TK_PRECEDING) ){ pxGet(p); } }
    else if( pxIs(p, TK_CURRENT) ){ /* no */ }
    else if( pxIs(p, TK_CURRENT_ROW) ){ w->eStart = 0; }
    else {
      w->eStart = 1;
      w->pBase = pxExpr(p);
      if( pxIs(p, TK_PRECEDING) ){ pxGet(p); w->eStart = -1; }
      else if( pxIs(p, TK_FOLLOWING) ){ pxGet(p); w->eStart = 1; }
      else if( pxIs(p, TK_CURRENT_ROW) ){ pxGet(p); w->eStart = 0; }
    }
    if( pxIs(p, TK_AND) || pxIs(p, TK_TO) ){
      pxGet(p);
      if( pxIs(p, TK_UNBOUNDED) ){ w->eEnd = TK_UNBOUNDED; pxGet(p); if( pxIs(p, TK_FOLLOWING) ) pxGet(p); }
      else if( pxIs(p, TK_CURRENT_ROW) ){ w->eEnd = 0; pxGet(p); }
      else {
        w->pEnd = pxExpr(p);
        if( pxIs(p, TK_PRECEDING) ){ pxGet(p); w->eEnd = -1; }
        else if( pxIs(p, TK_FOLLOWING) ){ pxGet(p); w->eEnd = 1; }
        else if( pxIs(p, TK_CURRENT_ROW) ){ pxGet(p); w->eEnd = 0; }
      }
    }
    if( pxIs(p, TK_EXCLUDE) ){
      pxGet(p);
      if( pxAcceptId(p) ) w->eExclude = 1;
      else pxSyntaxError(p);
    }
  }
  pxExpect(p, TK_RP);
  return w;
}
