#include "core.h"
#include "lex.h"
#include "parse.h"

struct Parse {
  Arena *pA;
  Token tok;
  Token tokNext;
  int haveNext;
  const char *zSql;
  Error err;
  int nErr;
  int nVar;
  int depth;
  int iLine;
  int startLine;
  int endLine;
};

static void pxGet(Parse *p);
static void skipSpace(Token *t){ while( t->type==TK_SPACE || t->type==TK_COMMENT ) lexNext(t); }
static void pxGet(Parse *p){
  if( p->haveNext ){ p->tok = p->tokNext; p->haveNext = 0; }
  else { lexNext(&p->tok); skipSpace(&p->tok); }
  p->iLine = p->tok.line;
}
static Token *pxPeek(Parse *p){
  if( !p->haveNext ){
    lexNext(&p->tokNext);
    skipSpace(&p->tokNext);
    p->haveNext = 1;
  }
  return &p->tokNext;
}
static int pxIs(Parse *p, int t){ return p->tok.type==t; }
static int pxAccept(Parse *p, int t){ if( pxIs(p,t) ){ pxGet(p); return 1; } return 0; }
static int pxExpect(Parse *p, int t){ if( pxAccept(p,t) ) return 1; pxSyntaxError(p); return 0; }
static void pxErr(Parse *p, const char *fmt, ...){
  va_list ap;
  if( p->nErr ) return;
  p->nErr++;
  p->err.hasPos = 1;
  p->err.pos = p->tok.pos;
  va_start(ap, fmt); vsnprintf(p->err.msg, ERRBUF, fmt, ap); va_end(ap);
}
static void pxErrAt(Parse *p, int pos, const char *fmt, ...){
  va_list ap;
  if( p->nErr ) return;
  p->nErr++;
  p->err.hasPos = 1;
  p->err.pos = pos;
  va_start(ap, fmt); vsnprintf(p->err.msg, ERRBUF, fmt, ap); va_end(ap);
}
static void pxSyntaxError(Parse *p){
  if( p->nErr ) return;
  if( p->tok.type==TK_EOF ) pxErrAt(p, p->tok.pos, "incomplete input");
  else pxErrAt(p, p->tok.pos, "near \"%s\": syntax error", tokName(&p->tok));
}
static int pxIsId(Parse *p){ return pxIs(p,TK_ID)||pxIs(p,TK_ID_Q)||pxIs(p,TK_STRING); }
