static Expr *pxUnary(Parse *p){
  int start = p->tok.pos;
  int t = p->tok.type;
  Expr *e, *x;
  switch( t ){
    case TK_MINUS: case TK_PLUS: case TK_TILDE:
      pxGet(p);
      if( p->depth++ > 1000 ){ pxErrAt(p,start,"Expression tree is too large"); }
      x = pxUnary(p);
      p->depth--;
      if( x==0 ){ pxSyntaxError(p); return 0; }
      e = pxNewExpr(p, t==TK_MINUS?TKX_NEG:(t==TK_PLUS?TKX_UMPL:TKX_BITNOT));
      e->pLeft = x;
      e->start = start; e->end = x->end;
      if( t==TK_PLUS ){
        if( x->op==TKX_INT || x->op==TKX_REAL || x->op==TKX_NULL ) return x;
        e->op = TKX_UMPL;
      }
      /* constant fold */
      if( x->op==TKX_INT ){
        if( t==TK_MINUS ) valSetInt(p->pA,&e->v,-x->v.i);
        else if( t==TK_TILDE ) valSetInt(p->pA,&e->v,~x->v.i);
        else valSetInt(p->pA,&e->v,x->v.i);
        e->op = TKX_INT;
        return e;
      }
      if( x->op==TKX_REAL ){
        if( t==TK_MINUS ){ valSetReal(p->pA,&e->v,-x->v.r); e->op=TKX_REAL; return e; }
        if( t==TK_PLUS ){ valSetReal(p->pA,&e->v,x->v.r); e->op=TKX_REAL; return e; }
      }
      return e;
    case TK_NOT: {
      pxGet(p);
      p->depth++;
      x = pxExprPrec(p, 3);
      p->depth--;
      if( x==0 ){ pxSyntaxError(p); return 0; }
      e = pxNewExpr(p, TKX_NOT);
      e->pLeft = x;
      e->start = start; e->end = x->end;
      return e;
    }
    default:
      return pxPrimary(p);
  }
}

static Expr *pxBetween(Parse *p, Expr *lhs, int negate, int start){
  Expr *e, *lo, *hi;
  pxGet(p);   /* BETWEEN */
  lo = pxExprPrec(p, 6);
  if( lo==0 ){ pxSyntaxError(p); return 0; }
  if( !pxExpect(p, TK_AND) ) return 0;
  hi = pxExprPrec(p, 6);
  if( hi==0 ){ pxSyntaxError(p); return 0; }
  e = pxNewExpr(p, negate?TKX_NOTBETWEEN:TKX_BETWEEN);
  e->pLeft = lhs;
  e->pList = pxNewList(p);
  pxListAppend(p, e->pList, lo, 0, 0);
  pxListAppend(p, e->pList, hi, 0, 0);
  e->start = start; e->end = p->tok.pos;
  return e;
}

static Expr *pxInOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e;
  pxGet(p);  /* IN */
  e = pxNewExpr(p, negate?TKX_NOTIN:TKX_IN);
  e->pLeft = lhs;
  e->start = start;
  if( pxIs(p, TK_LP) ){
    /* ( exprlist ) or ( select ) */
    pxGet(p);
    if( pxIs(p, TK_SELECT) || pxIs(p, TK_VALUES) ){
      e->pSelect = pxSelect(p);
      if( !pxExpect(p, TK_RP) ) return 0;
      e->end = p->tok.pos;
      return e;
    }
    e->pList = pxExprList0(p, 0, 0);
    if( e->pList==0 ) e->pList = pxNewList(p);
    if( !pxExpect(p, TK_RP) ) return 0;
    e->end = p->tok.pos;
    return e;
  }else{
    /* table name or subquery name */
    if( pxIsIdOrKw(p) ){
      e->zTok = pxIdText(p);
      pxGet(p);
    }else{
      pxSyntaxError(p);
      return 0;
    }
    e->end = p->tok.pos;
    return e;
  }
}

static Expr *pxIsOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e, *rhs;
  pxGet(p);   /* IS */
  if( negate && pxIs(p, TK_NOT) ){ pxGet(p); }
  if( pxIs(p, TK_NULL) ){ pxGet(p); e = pxNewExpr(p, negate?TKX_NOTNULL:TKX_ISNULL); e->pLeft = lhs; e->start=start; e->end=p->tok.pos; return e; }
  rhs = pxExprPrec(p, 4);
  if( rhs==0 ){ pxSyntaxError(p); return 0; }
  e = pxNewExpr(p, negate?TKX_ISNOT:TKX_IS);
  e->pLeft = lhs;
  e->pRight = rhs;
  e->start = start; e->end = p->tok.pos;
  return e;
}

static Expr *pxPost(Parse *p, Expr *lhs, int start){
  for(;;){
    int t = p->tok.type;
    int negate = 0;
    if( t==TK_IS ){ return pxIsOp(p, lhs, 0, start); }
    if( t==TK_BETWEEN ){ return pxBetween(p, lhs, 0, start); }
    if( t==TK_IN ){ return pxInOp(p, lhs, 0, start); }
    if( t==TK_LIKE || t==TK_GLOB || t==TK_REGEXP || t==TK_MATCH ){
      Expr *e;
      int k = t;
      pxGet(p);
      if( pxIs(p, TK_NOT) ){ pxGet(p); }
      e = pxNewExpr(p, k==TK_LIKE?TKX_LIKE:(k==TK_GLOB?TKX_GLOB:(k==TK_REGEXP?TKX_REGEXP:TKX_MATCH)));
      e->pLeft = lhs;
      e->pList = pxNewList(p);
      pxListAppend(p, e->pList, pxExprPrec(p, 7), 0, 0);
      if( pxIs(p, TK_ESCAPE) ){
        pxGet(p);
        pxListAppend(p, e->pList, pxExprPrec(p, 7), 0, 0);
      }
      e->start = start; e->end = p->tok.pos;
      lhs = e;
      continue;
    }
    if( t==TK_COLLATE ){
      pxGet(p);
      if( pxIsIdOrKw(p) ){
        lhs->zTok2 = pxIdText(p);
        pxGet(p);
        lhs->flags |= 0x100;
      }else{
        pxSyntaxError(p);
        return 0;
      }
      continue;
    }
    break;
  }
  return lhs;
}

static Expr *pxExprPrec(Parse *p, int minPrec){
  Expr *lhs;
  int start;
  if( p->depth++ > 900 ){ pxErrAt(p, p->tok.pos, "Expression tree is too large"); }
  lhs = pxUnary(p);
  if( lhs==0 ){ p->depth--; return 0; }
  start = lhs->start;
  lhs = pxPost(p, lhs, start);
  if( lhs==0 ){ p->depth--; return 0; }
  for(;;){
    int t = p->tok.type;
    int prec;
    Expr *e, *rhs;
    if( t==TK_NOT ){
      Token *nxt = pxPeek(p);
      if( nxt->type==TK_IS ){ prec = 4; }
      else if( nxt->type==TK_BETWEEN ){ prec = 6; }
      else if( nxt->type==TK_IN ){ prec = 7; }
      else if( nxt->type==TK_LIKE || nxt->type==TK_GLOB || nxt->type==TK_REGEXP || nxt->type==TK_MATCH ){ prec = 7; }
      else { p->depth--; return lhs; }
      pxGet(p);   /* NOT */
      lhs = pxPostNot(p, lhs, start, prec);
      continue;
    }
    prec = opPrec(t);
    if( prec<0 || prec<minPrec ){ p->depth--; return lhs; }
    if( t==TK_IS ) { p->depth--; return pxIsOp(p, lhs, 0, start); }
    if( t==TK_BETWEEN ){ p->depth--; return pxBetween(p, lhs, 0, start); }
    if( t==TK_IN ){ p->depth--; return pxInOp(p, lhs, 0, start); }
    if( t==TK_LIKE||t==TK_GLOB||t==TK_REGEXP||t==TK_MATCH ){ p->depth--; return pxPost(p,lhs,start); }
    if( prec<minPrec ){ p->depth--; return lhs; }
    pxGet(p);
    rhs = pxExprPrec(p, prec+1);
    if( rhs==0 ){ p->depth--; pxSyntaxError(p); return 0; }
    e = pxNewExpr(p, binOp(t));
    e->pLeft = lhs;
    e->pRight = rhs;
    e->start = start;
    e->end = p->tok.pos;
    lhs = e;
  }
}

static Expr *pxExpr(Parse *p){
  return pxExprPrec(p, 1);
}
