}

static Expr *pxUnary(Parse *p){
  int start = p->tok.pos;
  int t = p->tok.type;
  Expr *x, *e;
  if( t==TK_MINUS || t==TK_TILDE ){
    pxGet(p);
    if( p->depth++ > 900 ){ pxErrAt(p, start, "Expression tree is too large"); p->depth--; return 0; }
    x = pxUnary(p);
    p->depth--;
    if( x==0 ){ pxSyntaxError(p); return 0; }
    if( t==TK_TILDE ){
      e = pxNewExpr(p, TKX_BITNOT);
      e->pLeft = x;
      e->start = start; e->end = x->end;
      return e;
    }
    if( x->op==TKX_INT ){ valSetInt(p->pA, &x->v, -x->v.i); return x; }
    if( x->op==TKX_REAL ){ valSetReal(p->pA, &x->v, -x->v.r); return x; }
    e = pxNewExpr(p, TKX_NEG);
    e->pLeft = x;
    e->start = start; e->end = x->end;
    return e;
  }
  if( t==TK_PLUS ){
    pxGet(p);
    x = pxUnary(p);
    return x;
  }
  if( t==TK_NOT ){
    pxGet(p);
    if( p->depth++ > 900 ){ pxErrAt(p, start, "Expression tree is too large"); p->depth--; return 0; }
    x = pxExprPrec(p, 3);
    p->depth--;
    if( x==0 ){ pxSyntaxError(p); return 0; }
    e = pxNewExpr(p, TKX_NOT);
    e->pLeft = x;
    e->start = start; e->end = x->end;
    return e;
  }
  return pxPrimary(p);
}

static Expr *pxIsOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e, *rhs;
  pxGet(p);
  if( negate && pxIs(p, TK_NOT) ) pxGet(p);
  if( pxIs(p, TK_NULL) ){
    pxGet(p);
    e = pxNewExpr(p, negate?TKX_NOTNULL:TKX_ISNULL);
    e->pLeft = lhs;
    e->start = start; e->end = p->tok.pos;
    return e;
  }
  rhs = pxExprPrec(p, 4);
  if( rhs==0 ){ pxSyntaxError(p); return 0; }
  e = pxNewExpr(p, negate?TKX_ISNOT:TKX_IS);
  e->pLeft = lhs;
  e->pRight = rhs;
  e->start = start; e->end = p->tok.pos;
  return e;
}
static Expr *pxBetweenOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e, *lo, *hi;
  pxGet(p);
  lo = pxExprPrec(p, 6);
  if( lo==0 ){ pxSyntaxError(p); return 0; }
  if( !pxExpect(p, TK_AND) ) return 0;
  hi = pxExprPrec(p, 6);
  if( hi==0 ){ pxSyntaxError(p); return 0; }
  e = pxNewExpr(p, negate?TKX_NOTBETWEEN:TKX_BETWEEN);
  e->pLeft = lhs;
  e->pList = pxNewList(p);
  pxListAppend(p, e->pList, lo, 0, 0);
  pxListAppend(p, e->pList, hi, 0, 0);
  e->start = start; e->end = p->tok.pos;
  return e;
}
static Expr *pxInOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e;
  pxGet(p);
  e = pxNewExpr(p, negate?TKX_NOTIN:TKX_IN);
  e->pLeft = lhs;
  e->start = start;
  if( pxIs(p, TK_LP) ){
    pxGet(p);
    if( pxIs(p, TK_SELECT) || pxIs(p, TK_VALUES) ){
      e->pSelect = pxSelect(p);
      if( !pxExpect(p, TK_RP) ) return 0;
      e->end = p->tok.pos;
      return e;
    }
    e->pList = pxExprList0(p, 0, 0);
    if( e->pList==0 ) e->pList = pxNewList(p);
    if( !pxExpect(p, TK_RP) ) return 0;
    e->end = p->tok.pos;
    return e;
  }else{
    if( pxIsIdOrKw(p) ){ e->zTok = pxIdText(p); pxGet(p); }
    else { pxSyntaxError(p); return 0; }
    e->end = p->tok.pos;
    return e;
  }
}
static Expr *pxLikeOp(Parse *p, Expr *lhs, int negate, int kind, int start){
  Expr *e;
  pxGet(p);
  e = pxNewExpr(p, kind==TK_LIKE?TKX_LIKE:(kind==TK_GLOB?TKX_GLOB:(kind==TK_REGEXP?TKX_REGEXP:TKX_MATCH)));
  if( negate ) e->flags |= 0x200;
  e->pLeft = lhs;
  e->pList = pxNewList(p);
  {
    Expr *pat = pxExprPrec(p, 7);
    if( pat==0 ){ pxSyntaxError(p); return 0; }
    pxListAppend(p, e->pList, pat, 0, 0);
  }
  if( pxIs(p, TK_ESCAPE) ){
    pxGet(p);
    pxListAppend(p, e->pList, pxExprPrec(p, 7), 0, 0);
  }
  e->start = start; e->end = p->tok.pos;
  return e;
}

static Expr *pxExprPrec(Parse *p, int minPrec){
  Expr *lhs;
  int start;
  if( p->depth++ > 900 ){ pxErrAt(p, p->tok.pos, "Expression tree is too large"); p->depth--; return 0; }
  lhs = pxUnary(p);
  if( lhs==0 ){ p->depth--; return 0; }
  start = lhs->start;
  for(;;){
    int t = p->tok.type;
    int prec;
    Expr *e, *rhs;
    if( t==TK_IS ){ if( 4<minPrec ) break; lhs = pxIsOp(p, lhs, 0, start); continue; }
    if( t==TK_BETWEEN ){ if( 6<minPrec ) break; lhs = pxBetweenOp(p, lhs, 0, start); continue; }
    if( t==TK_IN ){ if( 7<minPrec ) break; lhs = pxInOp(p, lhs, 0, start); continue; }
    if( t==TK_LIKE || t==TK_GLOB || t==TK_REGEXP || t==TK_MATCH ){
      if( 7<minPrec ) break;
      lhs = pxLikeOp(p, lhs, 0, t, start);
      continue;
    }
    if( t==TK_COLLATE ){
      if( 9<minPrec ) break;
      pxGet(p);
      if( pxIsIdOrKw(p) ){
        lhs->zTok2 = pxIdText(p);
        pxGet(p);
        lhs->flags |= 0x100;
      }else{
        pxSyntaxError(p);
        p->depth--;
        return 0;
      }
      continue;
    }
    if( t==TK_ISNULL || t==TK_NOTNULL ){
      if( 4<minPrec ) break;
      pxGet(p);
      e = pxNewExpr(p, t==TK_ISNULL?TKX_ISNULL:TKX_NOTNULL);
      e->pLeft = lhs;
      e->start = start; e->end = p->tok.pos;
      lhs = e;
      continue;
    }
    if( t==TK_NOT ){
      Token *nxt = pxPeek(p);
      if( nxt->type==TK_IS ){ if( 4<minPrec ) break; pxGet(p); lhs = pxIsOp(p, lhs, 1, start); continue; }
      if( nxt->type==TK_BETWEEN ){ if( 6<minPrec ) break; pxGet(p); lhs = pxBetweenOp(p, lhs, 1, start); continue; }
      if( nxt->type==TK_IN ){ if( 7<minPrec ) break; pxGet(p); lhs = pxInOp(p, lhs, 1, start); continue; }
      if( nxt->type==TK_LIKE || nxt->type==TK_GLOB || nxt->type==TK_REGEXP || nxt->type==TK_MATCH ){
        if( 7<minPrec ) break;
        {
          int k = nxt->type;
          pxGet(p);
          lhs = pxLikeOp(p, lhs, 1, k, start);
        }
        continue;
      }
      break;
    }
    prec = binPrec(t);
    if( prec<0 || prec<minPrec ) break;
    pxGet(p);
    rhs = pxExprPrec(p, prec+1);
    if( rhs==0 ){ p->depth--; pxSyntaxError(p); return 0; }
    e = pxNewExpr(p, binOpFor(t));
    e->pLeft = lhs;
    e->pRight = rhs;
    e->start = start;
    e->end = p->tok.pos;
    lhs = e;
  }
  p->depth--;
  return lhs;
}
static Expr *pxExpr(Parse *p){ return pxExprPrec(p, 1); }

static ExprList *pxExprList0(Parse *p, int allowStar, int withNames){
  ExprList *l;
  Expr *e;
  if( !pxIsIdOrKw(p) && !pxIs(p, TK_STAR) && !pxIs(p, TK_INTEGER) && !pxIs(p, TK_FLOAT) &&
      !pxIs(p, TK_STRING) && !pxIs(p, TK_BLOB) && !pxIs(p, TK_LP) && !pxIs(p, TK_MINUS) &&
      !pxIs(p, TK_PLUS) && !pxIs(p, TK_TILDE) && !pxIs(p, TK_NOT) && !pxIs(p, TK_QUESTION) &&
      !pxIs(p, TK_COLON) && !pxIs(p, TK_AT) && !pxIs(p, TK_DOLLAR) && !pxIs(p, TK_CAST) &&
      !pxIs(p, TK_EXISTS) && !pxIs(p, TK_SELECT) && !pxIs(p, TK_VALUES) && !pxIs(p, TK_NULL) &&
      !pxIs(p, TK_ROWID) && !pxIs(p, TK_TRUE) && !pxIs(p, TK_FALSE) &&
      !pxIs(p, TK_CURRENT_DATE) && !pxIs(p, TK_CURRENT_TIME) && !pxIs(p, TK_CURRENT_TIMESTAMP) &&
      !pxIs(p, TK_CASE) && !pxIs(p, TK_RAISE) ) return 0;
  l = pxNewList(p);
  for(;;){
    char *zName = 0;
    int so = 0;
    if( pxIs(p, TK_STAR) && allowStar ){
      e = pxNewExpr(p, TKX_STAR);
      pxGet(p);
    }else{
      e = pxExpr(p);
      if( e==0 ) return l;
    }
    if( withNames || 1 ){
      if( pxIs(p, TK_AS) ){
        pxGet(p);
        if( pxIsIdOrKw(p) ){ zName = pxIdText(p); pxGet(p); }
        else { zName = arenaStrdup(p->pA,""); pxSyntaxError(p); return l; }
      }else if( pxIsIdOrKw(p) ){
        zName = pxIdText(p);
        pxGet(p);
      }else if( pxIs(p, TK_STRING) ){
        zName = pxIdText(p);
        pxGet(p);
      }
    }
    if( withNames && (pxIs(p, TK_ASC)||pxIs(p, TK_DESC)) ){
      so = pxIs(p, TK_ASC) ? 0 : 1;
      pxGet(p);
      if( pxIs(p, TK_NULLS) ){
        pxGet(p);
        if( pxAcceptId(p) ){}
        else pxSyntaxError(p);
      }
    }
    pxListAppend(p, l, e, zName, so);
    if( !pxAccept(p, TK_COMMA) ) break;
  }
  return l;
}
