function.arguments:
{"command": "cd /workspace/src && cat > parse.c <<'CPPEOF'
#include "core.h"
#include "lex.h"
#include "parse.h"

struct Parse {
  Arena *pA;
  Token tok;
  Token tokNext;
  int haveNext;
  const char *zSql;
  Error err;
  int nErr;
  int nVar;
  int depth;
  int iLine;
  int startLine;
};

/* ============ token helpers ============ */
static void skipSpace(Token *t){ while( t->type==TK_SPACE || t->type==TK_COMMENT ) lexNext(t); }
static void pxGet(Parse *p){
  if( p->haveNext ){ p->tok = p->tokNext; p->haveNext = 0; }
  else { lexNext(&p->tok); skipSpace(&p->tok); }
  p->iLine = p->tok.line;
}
static Token *pxPeek(Parse *p){
  if( !p->haveNext ){
    lexNext(&p->tokNext);
    skipSpace(&p->tokNext);
    p->haveNext = 1;
  }
  return &p->tokNext;
}
static int pxIs(Parse *p, int t){ return p->tok.type==t; }
static int pxAccept(Parse *p, int t){ if( pxIs(p,t) ){ pxGet(p); return 1; } return 0; }
static int pxExpect(Parse *p, int t){ if( pxAccept(p,t) ) return 1; pxSyntaxError(p); return 0; }
static void pxErrAt(Parse *p, int pos, const char *fmt, ...){
  va_list ap;
  if( p->nErr ) return;
  p->nErr++;
  p->err.hasPos = 1;
  p->err.pos = pos;
  va_start(ap, fmt); vsnprintf(p->err.msg, ERRBUF, fmt, ap); va_end(ap);
}
static void pxSyntaxError(Parse *p){
  if( p->nErr ) return;
  if( p->tok.type==TK_EOF ) pxErrAt(p, p->tok.pos, "incomplete input");
  else pxErrAt(p, p->tok.pos, "near \"%s\": syntax error", tokName(&p->tok));
}
static int pxIsId(Parse *p){ return pxIs(p,TK_ID)||pxIs(p,TK_ID_Q)||pxIs(p,TK_STRING); }
static int kwIsId(int t){
  switch( t ){
    case TK_ABORT: case TK_ACTION: case TK_AFTER: case TK_ANALYZE:
    case TK_BEFORE: case TK_BY: case TK_CASCADE: case TK_CHECK: case TK_COLUMNKW:
    case TK_COMMIT: case TK_CONFLICT: case TK_CONSTRAINT: case TK_CREATE:
    case TK_DATABASE: case TK_DEFAULT: case TK_DEFERRABLE: case TK_DEFERRED:
    case TK_DETACH: case TK_EACH: case TK_EXCLUSIVE: case TK_FAIL: case TK_FOR:
    case TK_FOREIGN: case TK_IGNORE: case TK_IMMEDIATE: case TK_INDEX:
    case TK_INITIALLY: case TK_INSTEAD: case TK_INTO: case TK_KEY:
    case TK_MATERIALIZED: case TK_NO: case TK_OF: case TK_PLAN: case TK_QUERY:
    case TK_RAISE: case TK_REINDEX: case TK_RENAME: case TK_REPLACE:
    case TK_RESTRICT: case TK_ROLLBACK: case TK_ROW: case TK_SAVEPOINT:
    case TK_TEMP: case TK_TEMPORARY: case TK_TRANSACTION: case TK_TRIGGER:
    case TK_VACUUM: case TK_VIEW: case TK_VIRTUAL:
      return 1;
    default: return 0;
  }
}
static int pxIsIdOrKw(Parse *p){
  return pxIsId(p) || (p->tok.type>=TK_KW_FIRST && p->tok.type<=TK_KW_LAST && kwIsId(p->tok.type));
}
static int pxIsAnyId(Parse *p){
  return pxIsId(p) || (p->tok.type>=TK_KW_FIRST && p->tok.type<=TK_KW_LAST);
}
static char *pxIdText(Parse *p){
  return pxIdTextTok(&p->tok, p->pA);
}
static char *pxIdTextTok(Token *t, Arena *pA){
  int n = t->n;
  const char *z = t->z;
  if( n>=2 ){
    char c0 = z[0], c1 = z[n-1];
    if( (c0=='"' && c1=='"') || (c0=='`' && c1=='`') || (c0=='[' && c1==']') )
      return arenaStrndup(pA, z+1, n-2);
    if( c0=='\'' && c1=='\'' ){
      char *r = arenaAlloc(pA, n);
      int i, j = 0;
      for(i=1;i<n-1;i++){
        if( z[i]=='\'' && z[i+1]=='\'' ){ r[j++]='\''; i++; }
        else r[j++] = z[i];
      }
      r[j] = 0;
      return r;
    }
  }
  return arenaStrndup(pA, z, n);
}
static int isKwText(Parse *p, const char *z){
  if( !pxIsIdOrKw(p) ) return 0;
  return p->tok.n==(int)strlen(z) && strncasecmp(p->tok.z, z, p->tok.n)==0;
}

/* ============ node constructors ============ */
static Expr *pxNewExpr(Parse *p, int op){
  Expr *e = arenaAlloc(p->pA, sizeof(Expr));
  memset(e, 0, sizeof(Expr));
  e->op = op;
  valInit(&e->v);
  return e;
}
static ExprList *pxNewList(Parse *p){
  ExprList *l = arenaAlloc(p->pA, sizeof(ExprList));
  memset(l, 0, sizeof(*l));
  return l;
}
static void pxListAppend(Parse *p, ExprList *l, Expr *e, const char *zName, int so){
  if( l->nExpr>=l->nCap ){
    int nc = l->nCap ? l->nCap*2 : 4;
    Expr **ap = arenaAlloc(p->pA, nc*sizeof(Expr*));
    char **az = arenaAlloc(p->pA, nc*sizeof(char*));
    int *ai = arenaAlloc(p->pA, nc*sizeof(int));
    if( l->nCap ){
      memcpy(ap, l->apExpr, l->nExpr*sizeof(Expr*));
      memcpy(az, l->azName, l->nExpr*sizeof(char*));
      memcpy(ai, l->aiSortOrder, l->nExpr*sizeof(int));
    }
    l->apExpr = ap; l->azName = az; l->aiSortOrder = ai; l->nCap = nc;
  }
  l->apExpr[l->nExpr] = e;
  l->azName[l->nExpr] = zName ? arenaStrdup(p->pA, zName) : 0;
  l->aiSortOrder[l->nExpr] = so;
  l->nExpr++;
}
static SrcList *pxNewSrcList(Parse *p){
  SrcList *s = arenaAlloc(p->pA, sizeof(SrcList));
  memset(s,0,sizeof(*s));
  return s;
}
static SrcItem *pxSrcAppend(Parse *p, SrcList *s){
  if( s->nSrc>=s->nCap ){
    int nc = s->nCap ? s->nCap*2 : 4;
    SrcItem *a = arenaAlloc(p->pA, nc*sizeof(SrcItem));
    if( s->nCap ) memcpy(a, s->a, s->nSrc*sizeof(SrcItem));
    memset(a+s->nCap, 0, (nc-s->nCap)*sizeof(SrcItem));
    s->a = a; s->nCap = nc;
  }
  memset(&s->a[s->nSrc], 0, sizeof(SrcItem));
  s->a[s->nSrc].joinType = JT_INNER;
  return &s->a[s->nSrc++];
}

/* ============ expression parsing ============ */
static Expr *pxExprPrec(Parse *p, int minPrec);
static Expr *pxPrimary(Parse *p);
static Expr *pxUnary(Parse *p);
static ExprList *pxExprList0(Parse *p, int allowStar, int withNames);
static Select *pxSelect(Parse *p);
static Window *pxWindow(Parse *p);

static int isCurrentRow(Parse *p){
  if( pxIs(p, TK_ROW) && p->tok.n==7 &&
      (memcmp(p->tok.z,"current",7)==0 || memcmp(p->tok.z,"CURRENT",7)==0 ||
       memcmp(p->tok.z,"Current",7)==0) ) return 1;
  return 0;
}

static int binOpFor(int t){
  switch( t ){
    case TK_PLUS: return TKX_ADD;
    case TK_MINUS: return TKX_SUB;
    case TK_STAR: return TKX_MUL;
    case TK_SLASH: return TKX_DIV;
    case TK_PERCENT: return TKX_MOD;
    case TK_LT: return TKX_LT;
    case TK_LE: return TKX_LE;
    case TK_GT: return TKX_GT;
    case TK_GE: return TKX_GE;
    case TK_EQ: return TKX_EQ;
    case TK_NE: return TKX_NE;
    case TK_AND: return TKX_AND;
    case TK_OR: return TKX_OR;
    case TK_CONCAT: return TKX_CONCAT;
    case TK_AMP: return TKX_BITAND;
    case TK_PIPE: return TKX_BITOR;
    case TK_LSHIFT: return TKX_LSHIFT;
    case TK_RSHIFT: return TKX_RSHIFT;
  }
  return 0;
}
static int binPrec(int t){
  switch( t ){
    case TK_OR: return 1;
    case TK_AND: return 2;
    case TK_EQ: case TK_NE: return 4;
    case TK_LT: case TK_LE: case TK_GT: case TK_GE: return 5;
    case TK_AMP: case TK_PIPE: case TK_LSHIFT: case TK_RSHIFT: return 6;
    case TK_PLUS: case TK_MINUS: return 7;
    case TK_STAR: case TK_SLASH: case TK_PERCENT: return 8;
    case TK_CONCAT: return 9;
  }
  return -1;
}

static Expr *pxPrimary(Parse *p){
  Expr *e;
  int start = p->tok.pos;
  switch( p->tok.type ){
    case TK_INTEGER: {
      const char *z = p->tok.z;
      int n = p->tok.n;
      e = pxNewExpr(p, TKX_INT);
      if( z[0]=='0' && n>2 && (z[1]=='x'||z[1]=='X') ){
        i64 v = 0;
        int i;
        for(i=2;i<n;i++){
          char c = z[i];
          int d = isdigit((unsigned char)c) ? c-'0' : (tolower(c)-'a'+10);
          v = v*16 + d;
        }
        valSetInt(p->pA, &e->v, v);
      }else{
        char *tmp = arenaStrndup(p->pA, z, n);
        valSetInt(p->pA, &e->v, strtoll(tmp,0,10));
      }
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_FLOAT: {
      char *tmp = arenaStrndup(p->pA, p->tok.z, p->tok.n);
      e = pxNewExpr(p, TKX_REAL);
      valSetReal(p->pA, &e->v, strtod(tmp,0));
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_STRING: {
      const char *z = p->tok.z;
      int n = p->tok.n;
      char *r = arenaAlloc(p->pA, n);
      int i, j = 0;
      for(i=1;i<n-1;i++){
        if( z[i]=='\'' && z[i+1]=='\'' ){ r[j++]='\''; i++; }
        else r[j++] = z[i];
      }
      e = pxNewExpr(p, TKX_TEXT);
      valSetTextN(p->pA, &e->v, r, j);
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_BLOB: {
      const char *z = p->tok.z;
      int n = p->tok.n;
      char *r = arenaAlloc(p->pA, (n-3)/2+1);
      int i, j = 0;
      for(i=2;i<n-1;i+=2){
        int hi = isdigit((unsigned char)z[i]) ? z[i]-'0' : (tolower(z[i])-'a'+10);
        int lo = isdigit((unsigned char)z[i+1]) ? z[i+1]-'0' : (tolower(z[i+1])-'a'+10);
        r[j++] = (char)((hi<<4)|lo);
      }
      e = pxNewExpr(p, TKX_BLOB);
      valSetBlob(p->pA, &e->v, r, j);
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_LP: {
      Expr *x;
      int qStart = p->tok.pos;
      pxGet(p);
      if( pxIs(p, TK_SELECT) || pxIs(p, TK_VALUES) ){
        e = pxNewExpr(p, TKX_SELECT);
        e->pSelect = pxSelect(p);
        if( !pxExpect(p, TK_RP) ) return 0;
        e->start = qStart; e->end = p->tok.pos;
        return e;
      }
      x = pxExpr(p);
      if( !pxExpect(p, TK_RP) ) return 0;
      x->start = qStart;
      x->end = p->tok.pos;
      return x;
    }
    case TK_QUESTION: {
      e = pxNewExpr(p, TKX_VARIABLE);
      e->zTok = strPrintf("%d", ++p->nVar);
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_COLON: case TK_AT: case TK_DOLLAR: {
      e = pxNewExpr(p, TKX_VARIABLE);
      e->zTok = arenaStrndup(p->pA, p->tok.z, p->tok.n);
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_CAST: {
      char *zType;
      int n = 0;
      char buf[128];
      pxGet(p);
      if( !pxExpect(p, TK_LP) ) return 0;
      buf[0] = 0;
      while( pxIsAnyId(p) || pxIs(p, TK_LP) || pxIs(p, TK_COMMA) ){
        if( pxIs(p, TK_LP) ){ n += snprintf(buf+n, (int)sizeof(buf)-n, "("); pxGet(p); continue; }
        if( pxIs(p, TK_COMMA) ){ n += snprintf(buf+n, (int)sizeof(buf)-n, ","); pxGet(p); continue; }
        {
          char *z = pxIdText(p);
          n += snprintf(buf+n, (int)sizeof(buf)-n, "%s", z);
          pxGet(p);
          if( pxIs(p, TK_LP) ){
            buf[n++] = '(';
            pxGet(p);
            while( pxIs(p, TK_INTEGER)||pxIs(p, TK_COMMA)||pxIsAnyId(p) ){
              if( pxIs(p, TK_COMMA) ) buf[n++] = ',';
              else { char *zt = arenaStrndup(p->pA,p->tok.z,p->tok.n); n += snprintf(buf+n,(int)sizeof(buf)-n,"%s",zt); }
              pxGet(p);
            }
            if( pxIs(p, TK_RP) ) buf[n++] = ')';
          }
        }
      }
      zType = arenaStrdup(p->pA, buf);
      if( !pxExpect(p, TK_RP) ) return 0;
      e = pxNewExpr(p, TKX_CAST);
      e->pLeft = pxExpr(p);
      e->zTok = zType;
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_EXISTS: {
      pxGet(p);
      if( !pxExpect(p, TK_LP) ) return 0;
      e = pxNewExpr(p, TKX_EXISTS);
      e->pSelect = pxSelect(p);
      if( !pxExpect(p, TK_RP) ) return 0;
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_SELECT: case TK_VALUES: {
      e = pxNewExpr(p, TKX_SELECT);
      e->pSelect = pxSelect(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_ROWID: {
      pxGet(p);
      e = pxNewExpr(p, TKX_ROWID);
      e->zTok = arenaStrdup(p->pA, "rowid");
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_NULL: {
      pxGet(p);
      e = pxNewExpr(p, TKX_NULL);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_TRUE: case TK_FALSE: {
      e = pxNewExpr(p, TKX_INT);
      valSetInt(p->pA, &e->v, p->tok.type==TK_TRUE ? 1 : 0);
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_CURRENT_DATE: case TK_CURRENT_TIME: case TK_CURRENT_TIMESTAMP: {
      e = pxNewExpr(p, p->tok.type==TK_CURRENT_DATE?TKX_CURRENT_DATE:
                       (p->tok.type==TK_CURRENT_TIME?TKX_CURRENT_TIME:TKX_CURRENT_TIMESTAMP));
      pxGet(p);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    case TK_RAISE: {
      pxGet(p);
      if( !pxExpect(p, TK_LP) ) return 0;
      e = pxNewExpr(p, TKX_RAISE);
      if( pxIsAnyId(p) ){
        pxGet(p);
        if( pxIs(p, TK_COMMA) ){
          pxGet(p);
          e->pLeft = pxExpr(p);
        }
      }
      pxExpect(p, TK_RP);
      e->start = start; e->end = p->tok.pos;
      return e;
    }
    default: {
      char *zName;
      int t;
      if( !pxIsIdOrKw(p) ) return 0;
      zName = pxIdText(p);
      t = p->tok.type;
      pxGet(p);
      if( pxIs(p, TK_LP) ){
        ExprList *args;
        pxGet(p);
        if( pxIs(p, TK_STAR) ){
          pxGet(p);
          args = pxNewList(p);
          args->azName = arenaAlloc(p->pA, sizeof(char*));
          args->apExpr = arenaAlloc(p->pA, sizeof(Expr*));
          args->aiSortOrder = arenaAlloc(p->pA, sizeof(int));
          args->nExpr = 1;
          args->apExpr[0] = pxNewExpr(p, TKX_STAR);
          args->azName[0] = 0;
          args->aiSortOrder[0] = 0;
          e = pxNewExpr(p, TKX_FUNCTION);
          e->zTok = zName;
          e->pList = args;
          e->flags |= EF_Distinct;
          if( !pxExpect(p, TK_RP) ) return 0;
        }else{
          args = pxExprList0(p, 1, 0);
          if( args==0 ) args = pxNewList(p);
          if( !pxExpect(p, TK_RP) ) return 0;
          e = pxNewExpr(p, TKX_FUNCTION);
          e->zTok = zName;
          e->pList = args;
        }
        if( pxIs(p, TK_OVER) ){
          pxGet(p);
          e->flags |= EF_Window;
          if( pxIs(p, TK_LP) ){
            e->pRight = (Expr*)pxWindow(p);
          }else{
            e->flags |= EF_Partial;
            if( pxIsIdOrKw(p) ){ e->zTok2 = pxIdText(p); pxGet(p); }
            else { pxSyntaxError(p); return 0; }
          }
        }
        if( pxIs(p, TK_FILTER) ){
          pxGet(p);
          pxExpect(p, TK_LP);
          pxExpect(p, TK_WHERE);
          e->pRight = (Expr*)pxExpr(p);
          pxExpect(p, TK_RP);
        }
        e->start = start; e->end = p->tok.pos;
        return e;
      }
      if( pxIs(p, TK_DOT) ){
        char *zTab = zName;
        char *zCol;
        pxGet(p);
        if( pxIs(p, TK_STAR) ){
          pxGet(p);
          e = pxNewExpr(p, TKX_STAR_TABLE);
          e->zTok = zTab;
          e->start = start; e->end = p->tok.pos;
          return e;
        }
        if( pxIsIdOrKw(p) ){ zCol = pxIdText(p); pxGet(p); }
        else { zCol = arenaStrdup(p->pA, ""); pxSyntaxError(p); return 0; }
        if( pxIs(p, TK_DOT) ){
          zTab = zCol;
          pxGet(p);
          if( pxIsIdOrKw(p) ){ zCol = pxIdText(p); pxGet(p); }
          else { zCol = arenaStrdup(p->pA,""); pxSyntaxError(p); return 0; }
        }
        e = pxNewExpr(p, TKX_COLUMN);
        e->zTok = zCol;
        e->zTok2 = zTab;
        e->start = start; e->end = p->tok.pos;
        return e;
      }
      e = pxNewExpr(p, TKX_COLUMN);
      e->zTok = zName;
      e->start = start; e->end = p->tok.pos;
      return e;
    }
  }
}

static Expr *pxUnary(Parse *p){
  int start = p->tok.pos;
  int t = p->tok.type;
  Expr *x, *e;
  if( t==TK_MINUS || t==TK_TILDE ){
    pxGet(p);
    if( p->depth++ > 900 ){ pxErrAt(p, start, "Expression tree is too large"); p->depth--; return 0; }
    x = pxUnary(p);
    p->depth--;
    if( x==0 ){ pxSyntaxError(p); return 0; }
    if( t==TK_TILDE ){
      e = pxNewExpr(p, TKX_BITNOT);
      e->pLeft = x;
      e->start = start; e->end = x->end;
      return e;
    }
    if( x->op==TKX_INT ){ valSetInt(p->pA, &x->v, -x->v.i); return x; }
    if( x->op==TKX_REAL ){ valSetReal(p->pA, &x->v, -x->v.r); return x; }
    e = pxNewExpr(p, TKX_NEG);
    e->pLeft = x;
    e->start = start; e->end = x->end;
    return e;
  }
  if( t==TK_PLUS ){
    pxGet(p);
    x = pxUnary(p);
    return x;
  }
  if( t==TK_NOT ){
    pxGet(p);
    if( p->depth++ > 900 ){ pxErrAt(p, start, "Expression tree is too large"); p->depth--; return 0; }
    x = pxExprPrec(p, 3);
    p->depth--;
    if( x==0 ){ pxSyntaxError(p); return 0; }
    e = pxNewExpr(p, TKX_NOT);
    e->pLeft = x;
    e->start = start; e->end = x->end;
    return e;
  }
  return pxPrimary(p);
}

static Expr *pxIsOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e, *rhs;
  pxGet(p);
  if( negate && pxIs(p, TK_NOT) ) pxGet(p);
  if( pxIs(p, TK_NULL) ){
    pxGet(p);
    e = pxNewExpr(p, negate?TKX_NOTNULL:TKX_ISNULL);
    e->pLeft = lhs;
    e->start = start; e->end = p->tok.pos;
    return e;
  }
  rhs = pxExprPrec(p, 4);
  if( rhs==0 ){ pxSyntaxError(p); return 0; }
  e = pxNewExpr(p, negate?TKX_ISNOT:TKX_IS);
  e->pLeft = lhs;
  e->pRight = rhs;
  e->start = start; e->end = p->tok.pos;
  return e;
}
static Expr *pxBetweenOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e, *lo, *hi;
  pxGet(p);
  lo = pxExprPrec(p, 6);
  if( lo==0 ){ pxSyntaxError(p); return 0; }
  if( !pxExpect(p, TK_AND) ) return 0;
  hi = pxExprPrec(p, 6);
  if( hi==0 ){ pxSyntaxError(p); return 0; }
  e = pxNewExpr(p, negate?TKX_NOTBETWEEN:TKX_BETWEEN);
  e->pLeft = lhs;
  e->pList = pxNewList(p);
  pxListAppend(p, e->pList, lo, 0, 0);
  pxListAppend(p, e->pList, hi, 0, 0);
  e->start = start; e->end = p->tok.pos;
  return e;
}
static Expr *pxInOp(Parse *p, Expr *lhs, int negate, int start){
  Expr *e;
  pxGet(p);
  e = pxNewExpr(p, negate?TKX_NOTIN:TKX_IN);
  e->pLeft = lhs;
  e->start = start;
  if( pxIs(p, TK_LP) ){
    pxGet(p);
    if( pxIs(p, TK_SELECT) || pxIs(p, TK_VALUES) ){
      e->pSelect = pxSelect(p);
      if( !pxExpect(p, TK_RP) ) return 0;
      e->end = p->tok.pos;
      return e;
    }
    e->pList = pxExprList0(p, 0, 0);
    if( e->pList==0 ) e->pList = pxNewList(p);
    if( !pxExpect(p, TK_RP) ) return 0;
    e->end = p->tok.pos;
    return e;
  }else{
    if( pxIsIdOrKw(p) ){ e->zTok = pxIdText(p); pxGet(p); }
    else { pxSyntaxError(p); return 0; }
    e->end = p->tok.pos;
    return e;
  }
}
static Expr *pxLikeOp(Parse *p, Expr *lhs, int negate, int kind, int start){
  Expr *e;
  pxGet(p);
  e = pxNewExpr(p, kind==TK_LIKE?TKX_LIKE:(kind==TK_GLOB?TKX_GLOB:(kind==TK_REGEXP?TKX_REGEXP:TKX_MATCH)));
  if( negate ) e->flags |= 0x200;
  e->pLeft = lhs;
  e->pList = pxNewList(p);
  {
    Expr *pat = pxExprPrec(p, 7);
    if( pat==0 ){ pxSyntaxError(p); return 0; }
    pxListAppend(p, e->pList, pat, 0, 0);
  }
  if( pxIs(p, TK_ESCAPE) ){
    pxGet(p);
    pxListAppend(p, e->pList, pxExprPrec(p, 7), 0, 0);
  }
  e->start = start; e->end = p->tok.pos;
  return e;
}

static Expr *pxExprPrec(Parse *p, int minPrec){
  Expr *lhs;
  int start;
  if( p->depth++ > 900 ){ pxErrAt(p, p->tok.pos, "Expression tree is too large"); p->depth--; return 0; }
  lhs = pxUnary(p);
  if( lhs==0 ){ p->depth--; return 0; }
  start = lhs->start;
  for(;;){
    int t = p->tok.type;
    int prec;
    Expr *e, *rhs;
    if( t==TK_IS ){ if( 4<minPrec ) break; lhs = pxIsOp(p, lhs, 0, start); continue; }
    if( t==TK_BETWEEN ){ if( 6<minPrec ) break; lhs = pxBetweenOp(p, lhs, 0, start); continue; }
    if( t==TK_IN ){ if( 7<minPrec ) break; lhs = pxInOp(p, lhs, 0, start); continue; }
    if( t==TK_LIKE || t==TK_GLOB || t==TK_REGEXP || t==TK_MATCH ){
      if( 7<minPrec ) break;
      lhs = pxLikeOp(p, lhs, 0, t, start);
      continue;
    }
    if( t==TK_COLLATE ){
      if( 9<minPrec ) break;
      pxGet(p);
      if( pxIsIdOrKw(p) ){
        lhs->zTok2 = pxIdText(p);
        pxGet(p);
        lhs->flags |= 0x100;
      }else{
        pxSyntaxError(p);
        p->depth--;
        return 0;
      }
      continue;
    }
    if( t==TK_ISNULL || t==TK_NOTNULL ){
      if( 4<minPrec ) break;
      pxGet(p);
      e = pxNewExpr(p, t==TK_ISNULL?TKX_ISNULL:TKX_NOTNULL);
      e->pLeft = lhs;
      e->start = start; e->end = p->tok.pos;
      lhs = e;
      continue;
    }
    if( t==TK_NOT ){
      Token *nxt = pxPeek(p);
      if( nxt->type==TK_IS ){ if( 4<minPrec ) break; pxGet(p); lhs = pxIsOp(p, lhs, 1, start); continue; }
      if( nxt->type==TK_BETWEEN ){ if( 6<minPrec ) break; pxGet(p); lhs = pxBetweenOp(p, lhs, 1, start); continue; }
      if( nxt->type==TK_IN ){ if( 7<minPrec ) break; pxGet(p); lhs = pxInOp(p, lhs, 1, start); continue; }
      if( nxt->type==TK_LIKE || nxt->type==TK_GLOB || nxt->type==TK_REGEXP || nxt->type==TK_MATCH ){
        if( 7<minPrec ) break;
        {
          int k = nxt->type;
          pxGet(p);
          lhs = pxLikeOp(p, lhs, 1, k, start);
        }
        continue;
      }
      break;
    }
    prec = binPrec(t);
    if( prec<0 || prec<minPrec ) break;
    pxGet(p);
    rhs = pxExprPrec(p, prec+1);
    if( rhs==0 ){ p->depth--; pxSyntaxError(p); return 0; }
    e = pxNewExpr(p, binOpFor(t));
    e->pLeft = lhs;
    e->pRight = rhs;
    e->start = start;
    e->end = p->tok.pos;
    lhs = e;
  }
  p->depth--;
  return lhs;
}
static Expr *pxExpr(Parse *p){ return pxExprPrec(p, 1); }

static ExprList *pxExprList0(Parse *p, int allowStar, int withNames){
  ExprList *l;
  Expr *e;
  if( !pxIsIdOrKw(p) && !pxIs(p, TK_STAR) && !pxIs(p, TK_INTEGER) && !pxIs(p, TK_FLOAT) &&
      !pxIs(p, TK_STRING) && !pxIs(p, TK_BLOB) && !pxIs(p, TK_LP) && !pxIs(p, TK_MINUS) &&
      !pxIs(p, TK_PLUS) && !pxIs(p, TK_TILDE) && !pxIs(p, TK_NOT) && !pxIs(p, TK_QUESTION) &&
      !pxIs(p, TK_COLON) && !pxIs(p, TK_AT) && !pxIs(p, TK_DOLLAR) && !pxIs(p, TK_CAST) &&
      !pxIs(p, TK_EXISTS) && !pxIs(p, TK_SELECT) && !pxIs(p, TK_VALUES) && !pxIs(p, TK_NULL) &&
      !pxIs(p, TK_ROWID) && !pxIs(p, TK_TRUE) && !pxIs(p, TK_FALSE) &&
      !pxIs(p, TK_CURRENT_DATE) && !pxIs(p, TK_CURRENT_TIME) && !pxIs(p, TK_CURRENT_TIMESTAMP) &&
      !pxIs(p, TK_CASE) && !pxIs(p, TK_RAISE) ) return 0;
  l = pxNewList(p);
  for(;;){
    char *zName = 0;
    int so = 0;
    if( pxIs(p, TK_STAR) && allowStar ){
      e = pxNewExpr(p, TKX_STAR);
      pxGet(p);
    }else{
      e = pxExpr(p);
      if( e==0 ) return l;
    }
    if( withNames || 1 ){
      if( pxIs(p, TK_AS) ){
        pxGet(p);
        if( pxIsIdOrKw(p) ){ zName = pxIdText(p); pxGet(p); }
        else { zName = arenaStrdup(p->pA,""); pxSyntaxError(p); return l; }
      }else if( pxIsIdOrKw(p) ){
        zName = pxIdText(p);
        pxGet(p);
      }else if( pxIs(p, TK_STRING) ){
        zName = pxIdText(p);
        pxGet(p);
      }
    }
    if( withNames && (pxIs(p, TK_ASC)||pxIs(p, TK_DESC)) ){
      so = pxIs(p, TK_ASC) ? 0 : 1;
      pxGet(p);
      if( pxIs(p, TK_NULLS) ){
        pxGet(p);
        if( pxAcceptId(p) ){}
        else pxSyntaxError(p);
      }
    }
    pxListAppend(p, l, e, zName, so);
    if( !pxAccept(p, TK_COMMA) ) break;
  }
  return l;
}
