/* ============ window definitions ============ */
static Window *pxWindow(Parse *p){
  Window *w = arenaAlloc(p->pA, sizeof(Window));
  memset(w, 0, sizeof(*w));
  pxExpect(p, TK_LP);
  if( pxIs(p, TK_RP) ){ pxGet(p); return w; }
  for(;;){
    if( pxIs(p, TK_PARTITION) ){
      pxGet(p);
      w->pPartition = pxExprList0(p, 0, 0);
      if( w->pPartition==0 ) w->pPartition = pxNewList(p);
      if( !pxAccept(p, TK_COMMA) ) break;
      continue;
    }
    if( pxIs(p, TK_ORDER) ){
      pxGet(p);
      pxExpect(p, TK_BY);
      w->pOrderBy = pxExprList0(p, 0, 1);
      if( w->pOrderBy==0 ) w->pOrderBy = pxNewList(p);
      if( !pxAccept(p, TK_COMMA) ) break;
      continue;
    }
    break;
  }
  if( pxIs(p, TK_ROWS) || pxIs(p, TK_RANGE) || pxIs(p, TK_GROUPS) ){
    w->rowsMode = pxIs(p, TK_ROWS)?0:(pxIs(p,TK_RANGE)?1:2);
    pxGet(p);
    if( pxIs(p, TK_UNBOUNDED) ){
      pxGet(p);
      if( pxIs(p, TK_PRECEDING) ) pxGet(p);
      w->eStart = -2;
    }else if( isCurrentRow(p) ){
      pxGet(p);
      w->eStart = 0;
    }else{
      w->pBase = pxExpr(p);
      if( pxIs(p, TK_PRECEDING) ){ pxGet(p); w->eStart = -1; }
      else if( pxIs(p, TK_FOLLOWING) ){ pxGet(p); w->eStart = 1; }
      else if( isCurrentRow(p) ){ pxGet(p); w->eStart = 0; }
      else { pxSyntaxError(p); return w; }
    }
    if( pxIs(p, TK_AND) || pxIs(p, TK_TO) ){
      pxGet(p);
      if( pxIs(p, TK_UNBOUNDED) ){
        pxGet(p);
        if( pxIs(p, TK_FOLLOWING) ) pxGet(p);
        w->eEnd = 2;
      }else if( isCurrentRow(p) ){
        pxGet(p);
        w->eEnd = 0;
      }else{
        w->pEnd = pxExpr(p);
        if( pxIs(p, TK_PRECEDING) ){ pxGet(p); w->eEnd = -1; }
        else if( pxIs(p, TK_FOLLOWING) ){ pxGet(p); w->eEnd = 1; }
        else if( isCurrentRow(p) ){ pxGet(p); w->eEnd = 0; }
        else { pxSyntaxError(p); return w; }
      }
    }
    if( pxIs(p, TK_EXCLUDE) ){
      pxGet(p);
      if( pxIsIdOrKw(p) ){ pxGet(p); w->eExclude = 1; }
      else pxSyntaxError(p);
    }
  }
  pxExpect(p, TK_RP);
  return w;
}

/* ============ select parsing ============ */
static With *pxWith(Parse *p){
  With *w = arenaAlloc(p->pA, sizeof(With));
  memset(w, 0, sizeof(*w));
  w->apCte = arenaAlloc(p->pA, 8*sizeof(Cte*));
  if( pxIs(p, TK_RECURSIVE) ){ w->recursive = 1; pxGet(p); }
  do{
    Cte *c = arenaAlloc(p->pA, sizeof(Cte));
    memset(c, 0, sizeof(*c));
    if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return w; }
    c->zName = pxIdText(p);
    pxGet(p);
    if( pxIs(p, TK_LP) ){
      pxGet(p);
      c->pCols = pxExprList0(p, 0, 0);
      if( c->pCols==0 ) c->pCols = pxNewList(p);
      pxExpect(p, TK_RP);
    }
    if( pxIs(p, TK_MATERIALIZED) || pxIs(p, TK_NOT) ){
      if( pxIs(p, TK_NOT) ){ pxGet(p); }
      pxGet(p);
    }
    pxExpect(p, TK_AS);
    if( pxIs(p, TK_MATERIALIZED) ){ pxGet(p); }
    pxExpect(p, TK_LP);
    c->pSelect = pxSelect(p);
    pxExpect(p, TK_RP);
    w->apCte[w->nCte++] = c;
  }while( pxAccept(p, TK_COMMA) );
  return w;
}

static ExprList *pxResultList(Parse *p){
  ExprList *l = pxNewList(p);
  for(;;){
    char *zName = 0;
    Expr *e;
    if( pxIs(p, TK_STAR) ){
      e = pxNewExpr(p, TKX_STAR);
      pxGet(p);
    }else if( pxIsIdOrKw(p) && pxPeek(p)->type==TK_DOT && pxPeek(p)->n==1 && pxPeek(p)->z[0]=='.' ){
      /* qualified star handled in pxExpr */
      e = pxExpr(p);
      if( e==0 ) break;
    }else{
      e = pxExpr(p);
      if( e==0 ) break;
    }
    if( pxIs(p, TK_AS) ){
      pxGet(p);
      if( pxIsIdOrKw(p) ){ zName = pxIdText(p); pxGet(p); }
      else if( pxIs(p, TK_STRING) ){ zName = pxIdText(p); pxGet(p); }
      else { zName = arenaStrdup(p->pA,""); pxSyntaxError(p); return l; }
    }else if( pxIsIdOrKw(p) || pxIs(p, TK_STRING) ){
      zName = pxIdText(p);
      pxGet(p);
    }
    pxListAppend(p, l, e, zName, 0);
    if( !pxAccept(p, TK_COMMA) ) break;
  }
  return l;
}

static SrcList *pxSrcList(Parse *p){
  SrcList *s = pxNewSrcList(p);
  for(;;){
    SrcItem *it;
    int jt = JT_INNER;
    int nat = 0;
    if( s->nSrc>0 ){
      /* join operator */
      if( pxIs(p, TK_COMMA) ){
        pxGet(p);
        jt = JT_INNER|JT_CROSS;
      }else{
        if( pxIs(p, TK_CROSS) ){ pxGet(p); pxExpect(p, TK_JOIN); jt = JT_INNER|JT_CROSS; }
        else if( pxIs(p, TK_NATURAL) ){
          pxGet(p); nat = 1;
          if( pxIs(p, TK_LEFT) ){ pxGet(p); jt = JT_LEFT; if( pxIs(p, TK_OUTER) ) pxGet(p); }
          else if( pxIs(p, TK_RIGHT) ){ pxGet(p); jt = JT_RIGHT; if( pxIs(p, TK_OUTER) ) pxGet(p); }
          else if( pxIs(p, TK_FULL) ){ pxGet(p); jt = JT_FULL; if( pxIs(p, TK_OUTER) ) pxGet(p); }
          pxExpect(p, TK_JOIN);
          jt |= JT_NATURAL;
        }
        else if( pxIs(p, TK_LEFT) ){ pxGet(p); jt = JT_LEFT; if( pxIs(p, TK_OUTER) ) pxGet(p); pxExpect(p, TK_JOIN); }
        else if( pxIs(p, TK_RIGHT) ){ pxGet(p); jt = JT_RIGHT; if( pxIs(p, TK_OUTER) ) pxGet(p); pxExpect(p, TK_JOIN); }
        else if( pxIs(p, TK_FULL) ){ pxGet(p); jt = JT_FULL; if( pxIs(p, TK_OUTER) ) pxGet(p); pxExpect(p, TK_JOIN); }
        else if( pxIs(p, TK_INNER) ){ pxGet(p); pxExpect(p, TK_JOIN); jt = JT_INNER; }
        else if( pxIs(p, TK_JOIN) ){ pxGet(p); jt = JT_INNER; }
        else break;
      }
    }
    it = pxSrcAppend(p, s);
    it->joinType = jt;
    it->natural = nat;
    if( pxIs(p, TK_LP) ){
      /* subquery or nested src list */
      pxGet(p);
      if( pxIs(p, TK_SELECT) || pxIs(p, TK_VALUES) || pxIs(p, TK_WITH) ){
        it->pSelect = pxSelect(p);
        it->isSubquery = 1;
        pxExpect(p, TK_RP);
      }else{
        it->pSub = pxSrcList(p);
        pxExpect(p, TK_RP);
        it->isNested = 1;
      }
    }else{
      if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
      it->zTab = pxIdText(p);
      pxGet(p);
      if( pxIs(p, TK_DOT) ){
        pxGet(p);
        if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
        it->zDb = it->zTab;
        it->zTab = pxIdText(p);
        pxGet(p);
      }
      if( pxIs(p, TK_INDEXED) ){
        pxGet(p);
        if( pxIs(p, TK_BY) ){ pxGet(p); if( pxIsIdOrKw(p) ){ pxGet(p); } }
      }else if( pxIs(p, TK_NOT) ){
        Token *nx = pxPeek(p);
        if( nx->type==TK_INDEXED ){ pxGet(p); pxGet(p); }
      }
    }
    /* alias */
    if( pxIs(p, TK_AS) ){
      pxGet(p);
      if( pxIsIdOrKw(p) ){ it->zAlias = pxIdText(p); pxGet(p); }
      else if( pxIs(p, TK_STRING) ){ it->zAlias = pxIdText(p); pxGet(p); }
      else { it->zAlias = arenaStrdup(p->pA,""); pxSyntaxError(p); return s; }
    }else if( pxIsIdOrKw(p) || pxIs(p, TK_STRING) ){
      /* don't treat keywords that begin a following clause as alias */
      int t = p->tok.type;
      int ok = 0;
      if( pxIsIdOrKw(p) ) ok = 1;
      if( ok ){
        /* Avoid absorbing keywords that start a new clause.  Keywords are
        ** permissive here, matching SQLite's identifier fallback rules. */
        it->zAlias = pxIdText(p);
        pxGet(p);
        (void)t;
      }
    }
    /* join constraint */
    if( pxIs(p, TK_ON) ){
      pxGet(p);
      it->pOn = pxExpr(p);
    }else if( pxIs(p, TK_USING) ){
      pxGet(p);
      pxExpect(p, TK_LP);
      it->isUsing = 1;
      it->nUsing = 0;
      it->azUsing = arenaAlloc(p->pA, 8*sizeof(char*));
      do{
        if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
        it->azUsing[it->nUsing++] = pxIdText(p);
        pxGet(p);
      }while( pxAccept(p, TK_COMMA) );
      pxExpect(p, TK_RP);
    }
  }
  return s;
}

static Select *pxSelectCore(Parse *p, int *pCompound){
  Select *s = arenaAlloc(p->pA, sizeof(Select));
  memset(s, 0, sizeof(*s));
  if( pxIs(p, TK_SELECT) ){
    pxGet(p);
    if( pxIs(p, TK_DISTINCT) ){ s->isDistinct = 1; pxGet(p); }
    else if( pxIs(p, TK_ALL) ){ pxGet(p); }
    else if( pxIsIdOrKw(p) && isKwText(p,"ALL") ){ pxGet(p); }
    s->pEList = pxResultList(p);
    if( pxIs(p, TK_FROM) ){
      pxGet(p);
      s->pSrc = pxSrcList(p);
    }
    if( pxIs(p, TK_WHERE) ){
      pxGet(p);
      s->pWhere = pxExpr(p);
    }
    if( pxIs(p, TK_GROUP) ){
      pxGet(p);
      pxExpect(p, TK_BY);
      s->pGroupBy = pxExprList0(p, 0, 0);
      if( s->pGroupBy==0 ) s->pGroupBy = pxNewList(p);
      if( pxIs(p, TK_HAVING) ){
        pxGet(p);
        s->pHaving = pxExpr(p);
      }
    }
    if( pxIs(p, TK_WINDOW) ){
      pxGet(p);
      s->aWin = arenaAlloc(p->pA, 8*sizeof(struct WinDef));
      do{
        if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
        s->aWin[s->nWin].zName = pxIdText(p);
        pxGet(p);
        pxExpect(p, TK_AS);
        s->aWin[s->nWin].pWin = pxWindow(p);
        s->nWin++;
      }while( pxAccept(p, TK_COMMA) );
    }
  }else if( pxIs(p, TK_VALUES) ){
    pxGet(p);
    s->pEList = pxNewList(p);
    s->flags |= 0x1000;   /* values select */
    do{
      ExprList *row;
      pxExpect(p, TK_LP);
      row = pxExprList0(p, 0, 0);
      if( row==0 ) row = pxNewList(p);
      pxExpect(p, TK_RP);
      {
        Expr *e = pxNewExpr(p, TKX_VALUELIST);
        e->pList = row;
        pxListAppend(p, s->pEList, e, 0, 0);
      }
    }while( pxAccept(p, TK_COMMA) );
  }else{
    pxSyntaxError(p);
    return s;
  }
  /* compound operators */
  for(;;){
    int op = 0;
    if( pxIs(p, TK_UNION) ){
      pxGet(p);
      op = pxIs(p, TK_ALL) ? (pxGet(p), 2) : 1;
    }else if( pxIs(p, TK_EXCEPT) ){
      pxGet(p); op = 3;
    }else if( pxIs(p, TK_INTERSECT) ){
      pxGet(p); op = 4;
    }else break;
    *pCompound = 1;
    s->op = op;
    s->pNext = pxSelectCore(p, pCompound);
    s = s->pNext;
  }
  return s;
}

static Select *pxSelectTop(Parse *p){
  Select *s;
  With *w = 0;
  int compound = 0;
  if( pxIs(p, TK_WITH) ){
    pxGet(p);
    w = pxWith(p);
  }
  s = pxSelectCore(p, &compound);
  s->pWith = w;
  if( pxIs(p, TK_ORDER) ){
    pxGet(p);
    pxExpect(p, TK_BY);
    s->pOrderBy = pxExprList0(p, 0, 1);
    if( s->pOrderBy==0 ) s->pOrderBy = pxNewList(p);
  }
  if( pxIs(p, TK_LIMIT) ){
    pxGet(p);
    s->pLimit = pxExpr(p);
    if( pxIs(p, TK_OFFSET) ){
      pxGet(p);
      s->pOffset = pxExpr(p);
    }else if( pxIs(p, TK_COMMA) ){
      pxGet(p);
      s->pOffset = s->pLimit;
      s->pLimit = pxExpr(p);
    }
  }
  return s;
}
