      if( c->pCols==0 ) c->pCols = pxNewList(p);
      pxExpect(p, TK_RP);
    }
    if( pxIs(p, TK_MATERIALIZED) || pxIs(p, TK_NOT) ){
      if( pxIs(p, TK_NOT) ){ pxGet(p); }
      pxGet(p);
    }
    pxExpect(p, TK_AS);
    if( pxIs(p, TK_MATERIALIZED) ){ pxGet(p); }
    pxExpect(p, TK_LP);
    c->pSelect = pxSelect(p);
    pxExpect(p, TK_RP);
    w->apCte[w->nCte++] = c;
  }while( pxAccept(p, TK_COMMA) );
  return w;
}

static ExprList *pxResultList(Parse *p){
  ExprList *l = pxNewList(p);
  for(;;){
    char *zName = 0;
    Expr *e;
    if( pxIs(p, TK_STAR) ){
      e = pxNewExpr(p, TKX_STAR);
      pxGet(p);
    }else if( pxIsIdOrKw(p) && pxPeek(p)->type==TK_DOT && pxPeek(p)->n==1 && pxPeek(p)->z[0]=='.' ){
      /* qualified star handled in pxExpr */
      e = pxExpr(p);
