      else if( pxIs(p, TK_STRING) ){ zName = pxIdText(p); pxGet(p); }
      else { zName = arenaStrdup(p->pA,""); pxSyntaxError(p); return l; }
    }else if( pxIsIdOrKw(p) || pxIs(p, TK_STRING) ){
