{"command": "cd /workspace/src && cat >> parse.c <<'CPPEOF'

/* ============ statements ============ */
#define ST_SELECT 1
#define ST_INSERT 2
#define ST_UPDATE 3
#define ST_DELETE 4
#define ST_CREATE_TABLE 5
#define ST_CREATE_INDEX 6
#define ST_CREATE_VIEW 7
#define ST_CREATE_TRIGGER 8
#define ST_DROP 9
#define ST_ALTER 10
#define ST_PRAGMA 11
#define ST_TXN 12
#define ST_EXPLAIN 13
#define ST_VACUUM 14
#define ST_ANALYZE 15
#define ST_REINDEX 16
#define ST_ATTACH 17
#define ST_DETACH 18
#define ST_OTHER 19

static Stmt *pxNewStmt(Parse *p, int kind){
  Stmt *s = arenaAlloc(p->pA, sizeof(Stmt));
  memset(s, 0, sizeof(Stmt));
  s->kind = kind;
  s->startPos = p->startPos;
  return s;
}

/* parse a table name: [db.]name */
static void pxTableName(Parse *p, char **pzDb, char **pzName){
  if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return; }
  *pzName = pxIdText(p);
  pxGet(p);
  if( pxIs(p, TK_DOT) ){
    pxGet(p);
    *pzDb = *pzName;
    if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return; }
    *pzName = pxIdText(p);
    pxGet(p);
  }
}

static Expr *pxDefaultExpr(Parse *p){
  /* DEFAULT value: signed number, string, blob, NULL, CURRENT_* or (expr) */
  Expr *e;
  int neg = 0;
  if( pxIs(p, TK_LP) ){
    pxGet(p);
    e = pxExpr(p);
    pxExpect(p, TK_RP);
    return e;
  }
  if( pxIs(p, TK_MINUS) || pxIs(p, TK_PLUS) ){
    neg = pxIs(p, TK_MINUS);
    pxGet(p);
  }
  if( pxIs(p, TK_INTEGER) || pxIs(p, TK_FLOAT) || pxIs(p, TK_STRING) || pxIs(p, TK_BLOB) ||
      pxIs(p, TK_NULL) || pxIs(p, TK_CURRENT_DATE) || pxIs(p, TK_CURRENT_TIME) ||
      pxIs(p, TK_CURRENT_TIMESTAMP) || pxIs(p, TK_TRUE) || pxIs(p, TK_FALSE) ){
    e = pxPrimary(p);
    if( e && neg ){
      if( e->op==TKX_INT ) valSetInt(p->pA,&e->v,-e->v.i);
      else if( e->op==TKX_REAL ) valSetReal(p->pA,&e->v,-e->v.r);
    }
    return e;
  }
  return pxExpr(p);
}

static void pxColumnDef(Parse *p, Stmt *s){
  struct ColDef *c;
  if( s->nCol==0 ){
    s->aCol = arenaAlloc(p->pA, 8*sizeof(struct ColDef));
    s->nCol = 0;
  }else if( (s->nCol & 7)==0 ){
    s->aCol = arenaRealloc(p->pA, s->aCol, s->nCol*sizeof(struct ColDef), (s->nCol+8)*sizeof(struct ColDef));
  }
  c = &s->aCol[s->nCol];
  memset(c, 0, sizeof(*c));
  if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return; }
  c->zName = pxIdText(p);
  pxGet(p);
  /* type name */
  {
    char buf[128];
    int n = 0;
    buf[0] = 0;
    while( pxIsAnyId(p) || pxIs(p, TK_LP) || pxIs(p, TK_INTEGER) || pxIs(p, TK_COMMA) ){
      if( pxIs(p, TK_LP) ){
        int depth = 0;
        buf[n++] = '(';
        pxGet(p);
        depth = 1;
        while( depth>0 ){
          if( pxIs(p, TK_LP) ){ depth++; buf[n++]='('; pxGet(p); continue; }
          if( pxIs(p, TK_RP) ){ depth--; if(depth<=0){ buf[n++]=')'; pxGet(p); break; } buf[n++]=')'; pxGet(p); continue; }
          if( pxIs(p, TK_COMMA) ) buf[n++]=',';
          else if( pxIsIdOrKw(p) ){ char *z = pxIdText(p); n += snprintf(buf+n,(int)sizeof(buf)-n,"%s",z); }
          else if( pxIs(p, TK_INTEGER) ){ char *z = arenaStrndup(p->pA,p->tok.z,p->tok.n); n += snprintf(buf+n,(int)sizeof(buf)-n,"%s",z); }
          else break;
          pxGet(p);
        }
        continue;
      }
      if( pxIs(p, TK_COMMA) ) break;
      {
        char *z = pxIdText(p);
        if( n>0 ) n += snprintf(buf+n,(int)sizeof(buf)-n," ");
        n += snprintf(buf+n,(int)sizeof(buf)-n,"%s",z);
        pxGet(p);
      }
    }
    c->zType = n>0 ? arenaStrdup(p->pA, buf) : 0;
  }
  /* column constraints */
  for(;;){
    if( pxIs(p, TK_CONSTRAINT) ){
      pxGet(p);
      if( pxIsIdOrKw(p) ){ pxGet(p); } else pxSyntaxError(p);
      continue;
    }
    if( pxIs(p, TK_PRIMARY) ){
      pxGet(p);
      pxExpect(p, TK_KEY);
      c->pk = 1;
      if( pxIs(p, TK_ASC) || pxIs(p, TK_DESC) ){ if( pxIs(p,TK_DESC) ) c->pkDesc=1; pxGet(p); }
      if( pxIs(p, TK_ON) ){ pxGet(p); pxExpect(p, TK_CONFLICT); if( pxIsAnyId(p) ) pxGet(p); }
      if( isKwText(p,"AUTOINCREMENT") ){ pxGet(p); c->autoInc = 1; }
      continue;
    }
    if( pxIs(p, TK_NOT) ){
      Token *nx = pxPeek(p);
      if( nx->type==TK_NULL ){
        pxGet(p); pxGet(p);
        c->notNull = 1;
        continue;
      }
      if( nx->type==TK_DEFERRABLE ) break;
      break;
    }
    if( pxIs(p, TK_NULL) ){ pxGet(p); continue; }
    if( pxIs(p, TK_UNIQUE) ){ pxGet(p); c->unique = 1; continue; }
    if( pxIs(p, TK_CHECK) ){ pxGet(p); pxExpect(p, TK_LP); pxExpr(p); pxExpect(p, TK_RP); continue; }
    if( pxIs(p, TK_DEFAULT) ){
      pxGet(p);
      c->zDefault = pxDefaultExpr(p);
      continue;
    }
    if( pxIs(p, TK_COLLATE) ){
      pxGet(p);
      if( pxIsIdOrKw(p) ){ c->collate = 1; pxGet(p); } else pxSyntaxError(p);
      continue;
    }
    if( pxIs(p, TK_REFERENCES) ){
      pxGet(p);
      if( pxIsIdOrKw(p) ) pxGet(p); else pxSyntaxError(p);
      if( pxIs(p, TK_LP) ){ pxGet(p); pxExprList0(p,0,0); pxExpect(p, TK_RP); }
      while( pxIsIdOrKw(p) && (isKwText(p,"ON")||isKwText(p,"MATCH")||isKwText(p,"DEFERRABLE")||
                               isKwText(p,"NOT")||isKwText(p,"INITIALLY")) ) pxGet(p);
      continue;
    }
    if( pxIs(p, TK_GENERATED) ){
      pxGet(p);
      pxGet(p); /* ALWAYS or BY */
      if( pxIs(p, TK_AS) ){ pxGet(p); pxExpect(p,TK_LP); pxExpr(p); pxExpect(p,TK_RP); }
      if( pxIsIdOrKw(p) && (isKwText(p,"STORED")||isKwText(p,"VIRTUAL")) ) pxGet(p);
      c->isGenerated = 1;
      continue;
    }
    break;
  }
  s->nCol++;
}

static void pxTableConstraint(Parse *p, Stmt *s){
  struct TabCon *c;
  if( (s->nCon & 7)==0 ){
    s->aCon = arenaRealloc(p->pA, s->nCon?s->aCon:0, s->nCon*sizeof(struct TabCon), (s->nCon+8)*sizeof(struct TabCon));
  }
  c = &s->aCon[s->nCon];
  memset(c, 0, sizeof(*c));
  if( pxIs(p, TK_CONSTRAINT) ){
    pxGet(p);
    if( pxIsIdOrKw(p) ){ c->zName = pxIdText(p); pxGet(p); } else pxSyntaxError(p);
  }
  if( pxIs(p, TK_PRIMARY) ){
    pxGet(p);
    pxExpect(p, TK_KEY);
    pxExpect(p, TK_LP);
    c->type = 0;
    c->pList = pxExprList0(p, 0, 1);
    if( c->pList==0 ) c->pList = pxNewList(p);
    pxExpect(p, TK_RP);
    if( pxIs(p, TK_ON) ){ pxGet(p); pxExpect(p,TK_CONFLICT); if(pxIsAnyId(p)) pxGet(p); }
    if( isKwText(p,"AUTOINCREMENT") ) pxGet(p);
    if( pxIs(p, TK_WITHOUT) ){ pxGet(p); pxGet(p); }
  }else if( pxIs(p, TK_UNIQUE) ){
    pxGet(p);
    pxExpect(p, TK_LP);
    c->type = 1;
    c->pList = pxExprList0(p, 0, 1);
    if( c->pList==0 ) c->pList = pxNewList(p);
    pxExpect(p, TK_RP);
    if( pxIs(p, TK_ON) ){ pxGet(p); pxExpect(p,TK_CONFLICT); if(pxIsAnyId(p)) pxGet(p); }
  }else if( pxIs(p, TK_CHECK) ){
    pxGet(p);
    pxExpect(p, TK_LP);
    c->type = 2;
    c->pExpr = pxExpr(p);
    pxExpect(p, TK_RP);
  }else if( pxIs(p, TK_FOREIGN) ){
    pxGet(p);
    pxExpect(p, TK_KEY);
    pxExpect(p, TK_LP);
    c->type = 3;
    c->pList = pxExprList0(p, 0, 0);
    if( c->pList==0 ) c->pList = pxNewList(p);
    pxExpect(p, TK_RP);
    pxExpect(p, TK_REFERENCES);
    if( pxIsIdOrKw(p) ) pxGet(p); else pxSyntaxError(p);
    if( pxIs(p, TK_LP) ){ pxGet(p); pxExprList0(p,0,0); pxExpect(p, TK_RP); }
    while( pxIsIdOrKw(p) && (isKwText(p,"ON")||isKwText(p,"MATCH")||isKwText(p,"DEFERRABLE")||
                             isKwText(p,"NOT")||isKwText(p,"INITIALLY")) ) pxGet(p);
  }else{
    pxSyntaxError(p);
  }
  s->nCon++;
}

static Stmt *pxCreateTable(Parse *p, int isTemp){
  Stmt *s = pxNewStmt(p, ST_CREATE_TABLE);
  s->ct.isTemp = isTemp;
  pxExpect(p, TK_TABLE);
  if( pxIs(p, TK_IF) ){
    pxGet(p);
    pxExpect(p, TK_NOT);
    pxExpect(p, TK_EXISTS);
    s->ct.ifNotExists = 1;
  }
  pxTableName(p, &s->ct.zDb, &s->ct.zTab);
  if( pxIs(p, TK_AS) ){
    pxGet(p);
    s->ct.selectStmt = 1;
    s->ct.pAsSelect = pxSelect(p);
    return s;
  }
  pxExpect(p, TK_LP);
  do{
    if( pxIs(p, TK_PRIMARY) || pxIs(p, TK_UNIQUE) || pxIs(p, TK_CHECK) || pxIs(p, TK_FOREIGN) ||
        pxIs(p, TK_CONSTRAINT) ){
      pxTableConstraint(p, s);
    }else{
      pxColumnDef(p, s);
    }
  }while( pxAccept(p, TK_COMMA) );
  pxExpect(p, TK_RP);
  if( pxIs(p, TK_WITHOUT) ){
    pxGet(p);
    pxExpect(p, TK_ROW);
    s->ct.withoutRowid = 1;
  }
  if( pxIs(p, TK_STRICT) ){
    s->ct.isStrict = 1;
    pxGet(p);
  }
  return s;
}

static Stmt *pxCreateIndex(Parse *p, int isTemp){
  Stmt *s = pxNewStmt(p, ST_CREATE_INDEX);
  pxExpect(p, TK_INDEX);
  if( pxIs(p, TK_IF) ){
    pxGet(p);
    pxExpect(p, TK_NOT);
    pxExpect(p, TK_EXISTS);
    s->ci.ifNotExists = 1;
  }
  if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
  s->ci.zName = pxIdText(p);
  pxGet(p);
  if( pxIs(p, TK_DOT) ){
    pxGet(p);
    s->ci.zDb = s->ci.zName;
    s->ci.zName = pxIdText(p);
    pxGet(p);
  }
  pxExpect(p, TK_ON);
  if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
  s->ci.zTab = pxIdText(p);
  pxGet(p);
  pxExpect(p, TK_LP);
  s->ci.pCols = pxExprList0(p, 0, 1);
  if( s->ci.pCols==0 ) s->ci.pCols = pxNewList(p);
  pxExpect(p, TK_RP);
  if( pxIs(p, TK_WHERE) ){
    pxGet(p);
    s->ci.pWhere = pxExpr(p);
  }
  return s;
}
static Stmt *pxCreateView(Parse *p, int isTemp){
  Stmt *s = pxNewStmt(p, ST_CREATE_VIEW);
  s->cv.isTemp = isTemp;
  pxExpect(p, TK_VIEW);
  if( pxIs(p, TK_IF) ){
    pxGet(p);
    pxExpect(p, TK_NOT);
    pxExpect(p, TK_EXISTS);
    s->cv.ifNotExists = 1;
  }
  pxTableName(p, &s->cv.zDb, &s->cv.zName);
  if( pxIs(p, TK_LP) ){
    pxGet(p);
    s->cv.pCols = pxExprList0(p, 0, 0);
    if( s->cv.pCols==0 ) s->cv.pCols = pxNewList(p);
    pxExpect(p, TK_RP);
  }
  pxExpect(p, TK_AS);
  s->cv.pSelect = pxSelect(p);
  return s;
}
static Stmt *pxCreateTrigger(Parse *p, int isTemp){
  Stmt *s = pxNewStmt(p, ST_CREATE_TRIGGER);
  s->ctr.isTemp = isTemp;
  pxExpect(p, TK_TRIGGER);
  if( pxIs(p, TK_IF) ){
    pxGet(p);
    pxExpect(p, TK_NOT);
    pxExpect(p, TK_EXISTS);
    s->ctr.ifNotExists = 1;
  }
  pxTableName(p, &s->ctr.zDb, &s->ctr.zName);
  if( pxIs(p, TK_BEFORE) ){ s->ctr.when = 0; pxGet(p); }
  else if( pxIs(p, TK_AFTER) ){ s->ctr.when = 1; pxGet(p); }
  else if( pxIs(p, TK_INSTEAD) ){ s->ctr.when = 2; pxGet(p); pxExpect(p, TK_OF); }
  if( pxIs(p, TK_INSERT) ){ s->ctr.event = 1; pxGet(p); }
  else if( pxIs(p, TK_DELETE) ){ s->ctr.event = 2; pxGet(p); }
  else if( pxIs(p, TK_UPDATE) ){
    s->ctr.event = 3;
    pxGet(p);
    if( pxIs(p, TK_OF) ){
      pxGet(p);
      do{ if( pxIsIdOrKw(p) ) pxGet(p); else break; }while( pxAccept(p, TK_COMMA) );
    }
  }
  pxExpect(p, TK_ON);
  pxTableName(p, &s->ctr.zDb, &s->ctr.zTab);
  if( pxIs(p, TK_FOR) ){
    pxGet(p);
    pxExpect(p, TK_EACH);
    pxExpect(p, TK_ROW);
    s->ctr.each = 1;
  }
  if( pxIs(p, TK_WHEN) ){
    pxGet(p);
    s->ctr.pWhen = pxExpr(p);
  }
  pxExpect(p, TK_BEGIN);
  /* body: statements until END */
  {
    int cap = 4;
    s->ctr.apStmt = arenaAlloc(p->pA, cap*sizeof(Stmt*));
    s->ctr.nStmt = 0;
    while( !pxIs(p, TK_END) ){
      Stmt *b = pxStatement(p);
      if( b==0 ) return s;
      if( s->ctr.nStmt>=cap ){
        cap *= 2;
        s->ctr.apStmt = arenaRealloc(p->pA, s->ctr.apStmt, s->ctr.nStmt*sizeof(Stmt*), cap*sizeof(Stmt*));
      }
      s->ctr.apStmt[s->ctr.nStmt++] = b;
      if( p->nErr ) return s;
    }
    pxGet(p);  /* END */
  }
  return s;
}

static Stmt *pxStatement(Parse *p){
  Stmt *s;
  int isTemp = 0;
  int isExplain = 0;
  int explainPlan = 0;
  p->startPos = p->tok.pos;
  if( pxIs(p, TK_EXPLAIN) ){
    pxGet(p);
    isExplain = 1;
    if( pxIs(p, TK_QUERY) ){ pxGet(p); pxExpect(p, TK_PLAN); explainPlan = 1; }
  }
  if( pxIs(p, TK_SELECT) || pxIs(p, TK_VALUES) || pxIs(p, TK_WITH) ){
    s = pxNewStmt(p, ST_SELECT);
    s->pSelect = pxSelectTop(p);
  }else if( pxIs(p, TK_INSERT) || pxIs(p, TK_REPLACE) || (pxIsIdOrKw(p)&&isKwText(p,"REPLACE")) ){
    s = pxInsert(p);
  }else if( pxIs(p, TK_UPDATE) ){
    s = pxUpdate(p);
  }else if( pxIs(p, TK_DELETE) ){
    s = pxDelete(p);
  }else if( pxIs(p, TK_CREATE) ){
    pxGet(p);
    if( pxIs(p, TK_TEMP) || pxIs(p, TK_TEMPORARY) ){ isTemp = 1; pxGet(p); }
    if( pxIs(p, TK_TABLE) ){ s = pxCreateTable(p, isTemp); }
    else if( pxIs(p, TK_UNIQUE) ){ pxGet(p); s = pxCreateIndex(p, isTemp); s->ci.unique = 1; }
    else if( pxIs(p, TK_INDEX) ){ s = pxCreateIndex(p, isTemp); }
    else if( pxIs(p, TK_VIEW) ){ s = pxCreateView(p, isTemp); }
    else if( pxIs(p, TK_TRIGGER) ){ s = pxCreateTrigger(p, isTemp); }
    else if( pxIs(p, TK_VIRTUAL) ){
      pxGet(p);
      s = pxNewStmt(p, ST_OTHER);
      s->zName = arenaStrdup(p->pA,"virtual");
      pxExpect(p, TK_TABLE);
      if( pxIs(p, TK_IF) ){ pxGet(p); pxExpect(p,TK_NOT); pxExpect(p,TK_EXISTS); }
      if( pxIsIdOrKw(p) ) pxGet(p); else pxSyntaxError(p);
      while( !pxIs(p, TK_SEMI) && !pxIs(p, TK_EOF) ) pxGet(p);
    }
    else { pxSyntaxError(p); s = pxNewStmt(p, ST_OTHER); }
  }else if( pxIs(p, TK_DROP) ){
    s = pxDrop(p);
  }else if( pxIs(p, TK_PRAGMA) ){
    s = pxPragma(p);
  }else if( pxIs(p, TK_BEGIN) || pxIs(p, TK_COMMIT) || pxIs(p, TK_END) || pxIs(p, TK_ROLLBACK) ||
            pxIs(p, TK_SAVEPOINT) || (pxIsIdOrKw(p)&&isKwText(p,"RELEASE")) ){
    s = pxTxn(p);
  }else if( pxIs(p, TK_VACUUM) ){
    pxGet(p);
    s = pxNewStmt(p, ST_VACUUM);
    if( pxIsIdOrKw(p) ){ pxGet(p); if( pxIsIdOrKw(p) ) pxGet(p); }
  }else if( pxIs(p, TK_ANALYZE) ){
    pxGet(p);
    s = pxNewStmt(p, ST_ANALYZE);
    if( pxIsIdOrKw(p) ){ pxGet(p); if( pxIs(p, TK_DOT) ){ pxGet(p); if(pxIsIdOrKw(p)) pxGet(p); } }
  }else if( pxIs(p, TK_REINDEX) ){
    pxGet(p);
    s = pxNewStmt(p, ST_REINDEX);
    if( pxIsIdOrKw(p) ) pxGet(p);
  }else if( pxIs(p, TK_ATTACH) ){
    pxGet(p);
    s = pxNewStmt(p, ST_ATTACH);
    s->pSelect = 0;
    s->prg.pValue = pxExpr(p);
    pxExpect(p, TK_AS);
    if( pxIsIdOrKw(p) ){ s->zName = pxIdText(p); pxGet(p); } else pxSyntaxError(p);
  }else if( pxIs(p, TK_DETACH) ){
    pxGet(p);
    s = pxNewStmt(p, ST_DETACH);
    s->prg.pValue = pxExpr(p);
    pxExpect(p, TK_DATABASE);
  }else{
    pxSyntaxError(p);
    s = pxNewStmt(p, ST_OTHER);
  }
  s->isExplain = isExplain;
  s->explainMode = explainPlan;
  return s;
}

/* top level: parse one statement, consume the terminating ';' */
int parseOneStatement(const char *zBuf, int iOff, Arena *pA, Stmt **ppStmt, Error *pErr,
                      int *piEnd, int *piLine, int *piStart){
  Parse ps;
  Parse *p = &ps;
  Token t;
  int i;
  Stmt *s;
  memset(&ps, 0, sizeof(ps));
  ps.pA = pA;
  ps.zSql = zBuf + iOff;
  lexInit(zBuf + iOff);
  /* count lines before offset */
  {
    int line = 1;
    for(i=0;i<iOff;i++) if( zBuf[i]=='\n' ) line++;
    ps.startLine = line;
  }
  lexNext(&t);
  skipSpace(&t);
  ps.tok = t;
  ps.haveNext = 0;
  ps.iLine = t.line;
  if( t.type==TK_EOF ){
    *ppStmt = 0;
    *piEnd = iOff;
    if( piLine ) *piLine = ps.startLine;
    if( piStart ) *piStart = iOff;
    return 0;
  }
  s = pxStatement(p);
  if( s ){
    s->startPos = 0;
    s->endPos = p->tok.pos;
  }
  if( pxIs(p, TK_SEMI) ) pxGet(p);
  *ppStmt = s;
  *pErr = ps.err;
  *piEnd = iOff + p->tok.pos;
  if( piLine ) *piLine = ps.startLine;
  if( piStart ) *piStart = iOff;
  return 1;
}
