  pxTableName(p, &s->ins.zDb, &s->ins.zTab);
  if( pxIs(p, TK_LP) ){
    pxGet(p);
    s->ins.pCols = pxExprList0(p, 0, 0);
    if( s->ins.pCols==0 ) s->ins.pCols = pxNewList(p);
    pxExpect(p, TK_RP);
  }
  if( pxIs(p, TK_VALUES) ){
    int cap = 4;
    s->ins.apRowValues = arenaAlloc(p->pA, cap*sizeof(ExprList*));
    s->ins.nRow = 0;
    pxGet(p);
    do{
      ExprList *row;
      pxExpect(p, TK_LP);
      row = pxExprList0(p, 0, 0);
      if( row==0 ) row = pxNewList(p);
      pxExpect(p, TK_RP);
      if( s->ins.nRow>=cap ){
        cap *= 2;
        s->ins.apRowValues = arenaRealloc(p->pA, s->ins.apRowValues, s->ins.nRow*sizeof(ExprList*), cap*sizeof(ExprList*));
      }
      s->ins.apRowValues[s->ins.nRow++] = row;
    }while( pxAccept(p, TK_COMMA) );
  }else if( pxIs(p, TK_SELECT) || pxIs(p, TK_WITH) ){
    s->ins.pSelect = pxSelectTop(p);
  }else if( pxIs(p, TK_DEFAULT) ){
    pxGet(p);
    pxExpect(p, TK_VALUES);
    s->ins.defaultValues = 1;
  }else{
    pxSyntaxError(p);
  }
  if( pxIs(p, TK_ON) ){
    Upsert *u = arenaAlloc(p->pA, sizeof(Upsert));
    memset(u, 0, sizeof(*u));
    pxGet(p);
    pxExpect(p, TK_CONFLICT);
    if( pxIs(p, TK_LP) ){
      pxGet(p);
      u->pTarget = pxExprList0(p, 0, 0);
      if( u->pTarget==0 ) u->pTarget = pxNewList(p);
      pxExpect(p, TK_RP);
      if( pxIs(p, TK_WHERE) ){ pxGet(p); u->pWhere = pxExpr(p); }
    }
    pxExpect(p, TK_DO);
    if( pxIs(p, TK_NOTHING) ){ pxGet(p); u->isDoUpdate = 0; }
    else if( pxIs(p, TK_UPDATE) ){
      u->isDoUpdate = 1;
      pxGet(p);
      pxExpect(p, TK_SET);
      u->pSet = pxUpdateSet(p);
      if( pxIs(p, TK_WHERE) ){ pxGet(p); u->pWhere = pxExpr(p); }
    }else{ pxSyntaxError(p); }
    s->ins.pUpsert = u;
  }
  if( pxIs(p, TK_RETURNING) ){
    pxGet(p);
    s->ins.pReturning = pxResultList(p);
  }
  return s;
}

static ExprList *pxUpdateSet(Parse *p){
  ExprList *l = pxNewList(p);
  do{
    Expr *e;
    char *zCol;
    Expr *lhs;
    if( pxIsIdOrKw(p) && pxPeek(p)->type==TK_EQ ){
      zCol = pxIdText(p);
      pxGet(p);
      lhs = pxNewExpr(p, TKX_COLUMN);
      lhs->zTok = zCol;
      pxGet(p);
    }else if( pxIsIdOrKw(p) && pxPeek(p)->type==TK_DOT ){
      lhs = pxExpr(p);
      if( !pxExpect(p, TK_EQ) ) return l;
    }else{
      lhs = pxExpr(p);
      if( !pxExpect(p, TK_EQ) ) return l;
    }
    e = pxExpr(p);
    pxListAppend(p, l, e, lhs->zTok, 0);
  }while( pxAccept(p, TK_COMMA) );
  return l;
}

static Stmt *pxUpdate(Parse *p){
  Stmt *s;
  int conflict = 0;
  pxGet(p);
  if( pxIs(p, TK_OR) ){
    pxGet(p);
    if( pxIs(p, TK_ROLLBACK) ) conflict = 1;
    else if( pxIs(p, TK_ABORT) ) conflict = 2;
    else if( pxIs(p, TK_FAIL) ) conflict = 3;
    else if( pxIs(p, TK_IGNORE) ) conflict = 4;
    else if( pxIs(p, TK_REPLACE) ) conflict = 5;
    else pxSyntaxError(p);
    pxGet(p);
  }
  s = pxNewStmt(p, ST_UPDATE);
  s->upd.orConf = conflict;
  pxTableName(p, &s->upd.zDb, &s->upd.zTab);
  if( pxIs(p, TK_AS) ){ pxGet(p); if( pxIsIdOrKw(p) ) pxGet(p); else pxSyntaxError(p); }
  pxExpect(p, TK_SET);
  s->upd.pSet = pxUpdateSet(p);
  if( pxIs(p, TK_FROM) ){
    pxGet(p);
    s->upd.pFrom = pxSrcList(p);
  }
  if( pxIs(p, TK_WHERE) ){ pxGet(p); s->upd.pWhere = pxExpr(p); }
  if( pxIs(p, TK_RETURNING) ){ pxGet(p); s->upd.pReturning = pxResultList(p); }
  return s;
}
static Stmt *pxDelete(Parse *p){
  Stmt *s;
  int conflict = 0;
  pxGet(p);
  pxExpect(p, TK_FROM);
  s = pxNewStmt(p, ST_DELETE);
  pxTableName(p, &s->del.zDb, &s->del.zTab);
  if( pxIs(p, TK_AS) ){ pxGet(p); if( pxIsIdOrKw(p) ) pxGet(p); else pxSyntaxError(p); }
  if( pxIs(p, TK_WHERE) ){ pxGet(p); s->del.pWhere = pxExpr(p); }
  if( pxIs(p, TK_RETURNING) ){ pxGet(p); s->del.pReturning = pxResultList(p); }
  (void)conflict;
  return s;
}
static Stmt *pxDrop(Parse *p){
  Stmt *s;
  int what = 0;
  pxGet(p);
  if( pxIs(p, TK_TABLE) ) what = 0;
  else if( pxIs(p, TK_INDEX) ) what = 1;
  else if( pxIs(p, TK_VIEW) ) what = 2;
  else if( pxIs(p, TK_TRIGGER) ) what = 3;
  else { pxSyntaxError(p); what = 0; }
  pxGet(p);
  s = pxNewStmt(p, ST_DROP);
  s->drop.what = what;
  if( pxIs(p, TK_IF) ){
    pxGet(p);
    pxExpect(p, TK_NOT);
    pxExpect(p, TK_EXISTS);
    s->drop.ifExists = 1;
  }
  pxTableName(p, &s->drop.zDb, &s->drop.zName);
  return s;
}
static Stmt *pxPragma(Parse *p){
  Stmt *s = pxNewStmt(p, ST_PRAGMA);
  pxGet(p);
  if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
  s->prg.zName = pxIdText(p);
  pxGet(p);
  if( pxIs(p, TK_DOT) ){
    pxGet(p);
    s->prg.zDb = s->prg.zName;
    if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
    s->prg.zName = pxIdText(p);
    pxGet(p);
  }
  if( pxIs(p, TK_EQ) ){
    pxGet(p);
    s->prg.isSet = 1;
    s->prg.pValue = pxExpr(p);
  }else if( pxIs(p, TK_LP) ){
    pxGet(p);
    s->prg.pArgs = pxExprList0(p, 0, 0);
    if( s->prg.pArgs==0 ) s->prg.pArgs = pxNewList(p);
    pxExpect(p, TK_RP);
  }
  return s;
}
static Stmt *pxTxn(Parse *p){
  Stmt *s;
  if( pxIs(p, TK_BEGIN) ){
    pxGet(p);
    s = pxNewStmt(p, ST_TXN);
    s->txnOp = 0;
    if( pxIs(p, TK_DEFERRED) ){ s->txnMode = 1; pxGet(p); }
    else if( pxIs(p, TK_IMMEDIATE) ){ s->txnMode = 2; pxGet(p); }
    else if( pxIs(p, TK_EXCLUSIVE) ){ s->txnMode = 3; pxGet(p); }
    if( pxIs(p, TK_TRANSACTION) ) pxGet(p);
  }else if( pxIs(p, TK_COMMIT) || pxIs(p, TK_END) ){
    pxGet(p);
    s = pxNewStmt(p, ST_TXN);
    s->txnOp = 1;
    if( pxIs(p, TK_TRANSACTION) ) pxGet(p);
  }else if( pxIs(p, TK_ROLLBACK) ){
    pxGet(p);
    s = pxNewStmt(p, ST_TXN);
    s->txnOp = 2;
    if( pxIs(p, TK_TRANSACTION) ) pxGet(p);
    if( pxIs(p, TK_TO) ){
      pxGet(p);
      if( pxIs(p, TK_SAVEPOINT) ) pxGet(p);
      if( pxIsIdOrKw(p) ){ s->zName = pxIdText(p); pxGet(p); } else pxSyntaxError(p);
    }
  }else if( pxIs(p, TK_SAVEPOINT) ){
    pxGet(p);
    s = pxNewStmt(p, ST_TXN);
    s->txnOp = 3;
    if( pxIsIdOrKw(p) ){ s->zName = pxIdText(p); pxGet(p); } else pxSyntaxError(p);
  }else{
    /* RELEASE */
    pxGet(p);
    s = pxNewStmt(p, ST_TXN);
    s->txnOp = 4;
    if( pxIs(p, TK_SAVEPOINT) ) pxGet(p);
    if( pxIsIdOrw(p) ){ s->zName = pxIdText(p); pxGet(p); } else pxSyntaxError(p);
  }
  return s;
}
CPPEOF
echo done"}

