  char *zName;
  Select *pSelect;
  char *zSql;
  ExprList *pCols;
  struct View *pNext;
} View;

typedef struct Schema {
  char *zName;          /* "main", "temp", or attached name */
  Table *pTable;        /* list of tables */
  Index *pIndex;        /* list of indexes (not attached to tables) */
  Trigger *pTrigger;
