  Schema *pMain;
  Schema *pTemp;
  Schema *pAttached;
  int nAttached;
  int pageSize;
  int inTxn;
  int txnLevel;
  /* rollback snapshot */
  Schema *pSnapMain;
  Schema *pSnapTemp;
  int changes;           /* rows changed by last statement */
  int totalChanges;
  i64 lastRowid;
  int errCode;
  char zErr[512];
