cat > db.c <<'DBEOF'
#include "core.h"
#include "lex.h"
#include "parse.h"
#include "db.h"

/* ================================================================= */
/* schema helpers */
Schema *dbFindSchema(Db *p, const char *zName){
  Schema *s;
  if( zName==0 || zName[0]==0 || strEq(zName,"main") ) return p->pMain;
  if( strEq(zName,"temp") ) return p->pTemp;
  for(s=p->pAttached; s; s=s->pNext) if( strEq(s->zName,zName) ) return s;
  return 0;
}
Table *schemaFindTable(Schema *p, const char *zName){
  Table *t;
  if( p==0 || zName==0 ) return 0;
  for(t=p->pTable; t; t=t->pNextTable) if( strEq(t->zName,zName) ) return t;
  return 0;
}
Table *dbFindTable(Db *p, const char *zName, const char *zSchema, Schema **ppSchema){
  Schema *s = dbFindSchema(p, zSchema);
  Table *t;
  if( s ){ t = schemaFindTable(s, zName); if( t ){ if(ppSchema) *ppSchema = s; return t; } }
  if( zSchema && (strEq(zSchema,"temp")||strEq(zSchema,"main"))==0 ) return 0;
  t = schemaFindTable(p->pMain, zName);
  if( t ){ if(ppSchema) *ppSchema = p->pMain; return t; }
  t = schemaFindTable(p->pTemp, zName);
  if( t ){ if(ppSchema) *ppSchema = p->pTemp; return t; }
  return 0;
}
View *schemaFindView(Schema *p, const char *zName){
  View *v;
  if( p==0 || zName==0 ) return 0;
  for(v=p->pView; v; v=v->pNext) if( strEq(v->zName,zName) ) return v;
  return 0;
}
Trigger *schemaFindTrigger(Schema *p, const char *zName){
  Trigger *t;
  if( p==0 || zName==0 ) return 0;
  for(t=p->pTrigger; t; t=t->pNext) if( strEq(t->zName,zName) ) return t;
  return 0;
}
Index *schemaFindIndex(Schema *p, const char *zName){
  Table *t;
  Index *x;
  if( p==0 || zName==0 ) return 0;
  for(t=p->pTable; t; t=t->pNextTable){
    for(x=t->pIndex; x; x=x->pNext) if( strEq(x->zName,zName) ) return x;
  }
  return 0;
}
Index *tableFindIndex(Table *p, const char *zName){
  Index *x;
  if( p==0 || zName==0 ) return 0;
  for(x=p->pIndex; x; x=x->pNext) if( strEq(x->zName,zName) ) return x;
  return 0;
}
void tableAddIndex(Table *p, Index *x){
  x->pNext = p->pIndex;
  p->pIndex = x;
}
void tableRemoveIndex(Table *p, const char *zName){
  Index **px = &p->pIndex;
  while( *px ){
    if( strEq((*px)->zName, zName) ){
      Index *x = *px;
      *px = x->pNext;
      free(x);
      return;
    }
    px = &(*px)->pNext;
  }
}

/* ---- table free / dup ---- */
void indexFree(Index *x){
  int i;
  for(i=0;i<x->nCol;i++) free(x->aCol[i].zName);
  free(x->aCol);
  for(i=0;i<x->nKey;i++){
    int j;
    for(j=0;j<x->nCol;j++) valFree(x->apKeyVal[i]+j);
    free(x->apKeyVal[i]);
  }
  free(x->apKeyVal);
  free(x->aiKeyRowid);
  free(x->zName);
  free(x->zTbl);
  free(x->zSql);
  free(x->zPartial);
  free(x);
}
void tableFree(Table *t){
  Index *x, *nx;
  int i;
  if( t==0 ) return;
  for(x=t->pIndex; x; x=nx){ nx=x->pNext; indexFree(x); }
  for(i=0;i<t->nCol;i++){
    free(t->aCol[i].zName);
    free(t->aCol[i].zType);
  }
  free(t->aCol);
  for(i=0;i<t->nRow;i++){
    int j;
    for(j=0;j<t->nCol;j++) valFree(t->apRow[i]->aVal+j);
    free(t->apRow[i]->aVal);
    free(t->apRow[i]);
  }
  free(t->apRow);
  free(t->zName);
  free(t->zSql);
  free(t);
}
void schemaFree(Schema *p){
  Table *t, *nt;
  View *v, *nv;
  Trigger *tr, *ntr;
  if( p==0 ) return;
  for(t=p->pTable; t; t=nt){ nt=t->pNextTable; tableFree(t); }
  for(v=p->pView; v; v=nv){ nv=v->pNext; free(v->zName); free(v->zSql); free(v); }
  for(tr=p->pTrigger; tr; tr=ntr){ ntr=tr->pNext; free(tr->zName); free(tr->zTbl); free(tr->zSql); free(tr); }
  free(p->zName);
  free(p->zFile);
  free(p);
}
Table *tableDup(Table *t){
  Table *n = malloc(sizeof(Table));
  int i;
  memcpy(n, t, sizeof(Table));
  n->pNextTable = 0;
  n->pIndex = 0;
  n->nRowCap = t->nRow;
  n->apRow = malloc((t->nRow?t->nRow:1)*sizeof(Row*));
  for(i=0;i<t->nRow;i++){
    Row *r = malloc(sizeof(Row));
    r->rowid = t->apRow[i]->rowid;
    r->aVal = malloc(t->nCol*sizeof(Value));
    memcpy(r->aVal, t->apRow[i]->aVal, t->nCol*sizeof(Value));
    n->apRow[i] = r;
  }
  n->aCol = malloc((t->nCol?t->nCol:1)*sizeof(Column));
  memcpy(n->aCol, t->aCol, t->nCol*sizeof(Column));
  for(i=0;i<t->nCol;i++){
    n->aCol[i].zName = strDup(t->aCol[i].zName);
    n->aCol[i].zType = strDup(t->aCol[i].zType);
  }
  n->zName = strDup(t->zName);
  n->zSql = strDup(t->zSql);
  return n;
}
Schema *schemaDup(Schema *p){
  Schema *n = malloc(sizeof(Schema));
  Table *t, **pt;
  View *v, **pv;
  Trigger *tr, **ptr;
  memcpy(n, p, sizeof(Schema));
  n->pNext = 0;
  n->pTable = 0;
  pt = &n->pTable;
  for(t=p->pTable; t; t=t->pNextTable){ *pt = tableDup(t); pt = &(*pt)->pNextTable; }
  n->pView = 0; pv = &n->pView;
  for(v=p->pView; v; v=v->pNext){ View *nv = malloc(sizeof(View)); memcpy(nv,v,sizeof(View)); nv->pNext=0; nv->zName=strDup(v->zName); nv->zSql=strDup(v->zSql); *pv=nv; pv=&nv->pNext; }
  n->pTrigger = 0; ptr = &n->pTrigger;
  for(tr=p->pTrigger; tr; tr=tr->pNext){ Trigger *ntr = malloc(sizeof(Trigger)); memcpy(ntr,tr,sizeof(Trigger)); ntr->pNext=0; ntr->zName=strDup(tr->zName); ntr->zTbl=strDup(tr->zTbl); ntr->zSql=strDup(tr->zSql); *ptr=ntr; ptr=&ntr->pNext; }
  n->zName = strDup(p->zName);
  n->zFile = strDup(p->zFile);
  return n;
}
void dbSnapshot(Db *p){
  if( p->pSnapMain ) schemaFree(p->pSnapMain);
  if( p->pSnapTemp ) schemaFree(p->pSnapTemp);
  p->pSnapMain = p->pMain ? schemaDup(p->pMain) : 0;
  p->pSnapTemp = p->pTemp ? schemaDup(p->pTemp) : 0;
  p->inTxn = 1;
}
void dbRestoreSnapshot(Db *p){
  if( p->pSnapMain ){ schemaFree(p->pMain); p->pMain = p->pSnapMain; p->pSnapMain = 0; }
  if( p->pSnapTemp ){ schemaFree(p->pTemp); p->pTemp = p->pSnapTemp; p->pSnapTemp = 0; }
  p->inTxn = 0;
}

/* ---- rows ---- */
int colIndexOf(Table *p, const char *zName){
  int i;
  if( zName==0 ) return -1;
  for(i=0;i<p->nCol;i++) if( strEq(p->aCol[i].zName,zName) ) return i;
  return -1;
}
int tableFindKey(Table *p, i64 rowid){
  int lo = 0, hi = p->nRow-1;
  while( lo<=hi ){
    int mid = (lo+hi)/2;
    if( p->apRow[mid]->rowid==rowid ) return mid;
    if( p->apRow[mid]->rowid<rowid ) lo = mid+1; else hi = mid-1;
  }
  return -1;
}
i64 tableNextRowid(Table *p){
  if( p->nRow>0 ) return p->apRow[p->nRow-1]->rowid+1;
  return p->nextRowid>0 ? p->nextRowid : 1;
}
void tableInsertRow(Db *pDb, Table *t, i64 rowid, Value *aVal){
  int lo = 0, hi = t->nRow-1, pos;
  Row *r;
  Index *x;
  while( lo<=hi ){
    int mid = (lo+hi)/2;
    if( t->apRow[mid]->rowid<rowid ) lo = mid+1; else hi = mid-1;
  }
  pos = lo;
  if( t->nRow>=t->nRowCap ){
    int nc = t->nRowCap ? t->nRowCap*2 : 8;
    Row **a = malloc(nc*sizeof(Row*));
    if( t->nRow ) memcpy(a, t->apRow, t->nRow*sizeof(Row*));
    free(t->apRow);
    t->apRow = a; t->nRowCap = nc;
  }
  r = malloc(sizeof(Row));
  r->rowid = rowid;
  r->aVal = aVal;
  memmove(t->apRow+pos+1, t->apRow+pos, (t->nRow-pos)*sizeof(Row*));
  t->apRow[pos] = r;
  t->nRow++;
  if( rowid>=t->nextRowid ) t->nextRowid = rowid+1;
  if( pDb ) pDb->lastRowid = rowid;
  /* maintain index keys */
  for(x=t->pIndex; x; x=x->pNext){
    Arena *pA = (Arena*)0;
    /* allocate keys using a temporary arena */
    int j;
    Value *kv = malloc(x->nCol*sizeof(Value));
    int cap = x->nKey?x->nKey*2:8;
    Value **ap = malloc(cap*sizeof(Value*));
    i64 *ai = malloc(cap*sizeof(i64));
    if( x->nKey ){ memcpy(ap, x->apKeyVal, x->nKey*sizeof(Value*)); memcpy(ai, x->aiKeyRowid, x->nKey*sizeof(i64)); }
    free(x->apKeyVal); free(x->aiKeyRowid);
    x->apKeyVal = ap; x->aiKeyRowid = ai; x->nKeyCap = cap;
    for(j=0;j<x->nCol;j++){ valInit(kv+j); valCopy(pA, kv+j, aVal+x->aCol[j].iCol); }
    x->apKeyVal[x->nKey] = kv;
    x->aiKeyRowid[x->nKey] = rowid;
    x->nKey++;
  }
}
void tableDeleteRow(Table *t, int iRow){
  Index *x;
  int j, k;
  Row *r = t->apRow[iRow];
  for(x=t->pIndex; x; x=x->pNext){
    for(k=0;k<x->nKey;k++){
      if( x->aiKeyRowid[k]==r->rowid ){
        for(j=0;j<x->nCol;j++) valFree(x->apKeyVal[k]+j);
        free(x->apKeyVal[k]);
        memmove(x->apKeyVal+k, x->apKeyVal+k+1, (x->nKey-k-1)*sizeof(Value*));
        memmove(x->aiKeyRowid+k, x->aiKeyRowid+k+1, (x->nKey-k-1)*sizeof(i64));
        x->nKey--;
        break;
      }
    }
  }
  for(j=0;j<t->nCol;j++) valFree(r->aVal+j);
  free(r->aVal);
  free(r);
  memmove(t->apRow+iRow, t->apRow+iRow+1, (t->nRow-iRow-1)*sizeof(Row*));
  t->nRow--;
}
void buildIndexKeys(Db *pDb, Table *t, Index *x){
  int i, j;
  for(i=0;i<x->nKey;i++){
    for(j=0;j<x->nCol;j++) valFree(x->apKeyVal[i]+j);
    free(x->apKeyVal[i]);
  }
  x->nKey = 0;
  if( x->nKeyCap<t->nRow ){
    free(x->apKeyVal); free(x->aiKeyRowid);
    x->apKeyVal = malloc((t->nRow?t->nRow:1)*sizeof(Value*));
    x->aiKeyRowid = malloc((t->nRow?t->nRow:1)*sizeof(i64));
    x->nKeyCap = t->nRow;
  }
  for(i=0;i<t->nRow;i++){
    Value *kv = malloc(x->nCol*sizeof(Value));
    for(j=0;j<x->nCol;j++){ valInit(kv+j); valCopy(0, kv+j, t->apRow[i]->aVal+x->aCol[j].iCol); }
    x->apKeyVal[i] = kv;
    x->aiKeyRowid[i] = t->apRow[i]->rowid;
    x->nKey++;
  }
}
DBEOF
gcc -c -O1 -o db.o db.c -Wall -I. 2>&1|grep error|head; echo rc=$?"}

