        for(j=0;j<x->nCol;j++) valFree(x->apKeyVal[k]+j);
        free(x->apKeyVal[k]);
        memmove(x->apKeyVal+k, x->apKeyVal+k+1, (x->nKey-k-1)*sizeof(Value*));
        memmove(x->aiKeyRowid+k, x->aiKeyRowid+k+1, (x->nKey-k-1)*sizeof(i64));
        x->nKey--;
        break;
      }
    }
  }
  for(j=0;j<t->nCol;j++) valFree(r->aVal+j);
  free(r->aVal);
  free(r);
  memmove(t->apRow+iRow, t->apRow+iRow+1, (t->nRow-iRow-1)*sizeof(Row*));
  t->nRow--;
}
void buildIndexKeys(Db *pDb, Table *t, Index *x){
  int i, j;
  for(i=0;i<x->nKey;i++){
    for(j=0;j<x->nCol;j++) valFree(x->apKeyVal[i]+j);
    free(x->apKeyVal[i]);
  }
  x->nKey = 0;
  if( x->nKeyCap<t->nRow ){
    free(x->apKeyVal); free(x->aiKeyRowid);
    x->apKeyVal = malloc((t->nRow?t->nRow:1)*sizeof(Value*));
    x->aiKeyRowid = malloc((t->nRow?t->nRow:1)*sizeof(i64));
    x->nKeyCap = t->nRow;
  }
  for(i=0;i<t->nRow;i++){
    Value *kv = malloc(x->nCol*sizeof(Value));
    for(j=0;j<x->nCol;j++){ valInit(kv+j); valCopy(0, kv+j, t->apRow[i]->aVal+x->aCol[j].iCol); }
    x->apKeyVal[i] = kv;
    x->aiKeyRowid[i] = t->apRow[i]->rowid;
    x->nKey++;
  }
}
