typedef struct TreeItem {
  unsigned char *zPayload;   /* record bytes */
  int nPayload;
  i64 rowid;
  int isIndex;
} TreeItem;

typedef struct Bld {
  PgList *pPg;
  int pageSize;
  Arena *pA;
