/* write cells for one leaf page; returns page number */
static int writeLeaf(Bld *b, TreeItem *a, int n, int isSchema){
  int pg = pgAlloc(b->pPg);
  unsigned char *z = b->pPg->ap[pg-1];
  int usable = b->pageSize;
  int maxLocal, minLocal, minFrac;
  int hdrOff = isSchema ? 100 : 0;
  int nCells = n;
  int i;
  int nPtr = nCells*2;
  int contentEnd = b->pageSize;
  unsigned char *cells = arenaAlloc(b->pA, b->pageSize*2);
  int nCellsUsed = 0;
  int maxFree = 0;
  maxFrac = ((b->pageSize-12)*32)/255 - 23;
  minLocal = maxFrac;
  maxLocal = b->pageSize - 35;
  /* pack cells from the end of the page backwards */
  {
    unsigned char *cur = cells + b->pageSize*2;  /* temporary buffer, grows down */
    /* Use a second temp buffer for assembling */
  }
  for(i=n-1;i>=0;i--){
    int local, surplus;
    unsigned char *cell = arenaAlloc(b->pA, b->pageSize);
    int nCell = 0;
    u64 payload = (u64)a[i].nPayload;
    nCell = putVarint(cell, payload);
    if( !a[i].isIndex ) nCell += putVarint(cell+nCell, (u64)a[i].rowid);
    if( (int)payload <= maxLocal ){
      memcpy(cell+nCell, a[i].zPayload, a[i].nPayload);
      nCell += a[i].nPayload;
      local = a[i].nPayload;
    }else{
      int ovf;
      surplus = minLocal + (int)((payload - minLocal) % (b->pageSize - 4));
      local = surplus<=maxLocal ? surplus : minLocal;
      memcpy(cell+nCell, a[i].zPayload, local);
      nCell += local;
      /* first overflow page */
      ovf = pgAlloc(b->pPg);
      cell[nCell++] = (unsigned char)(ovf>>24);
      cell[nCell++] = (unsigned char)(ovf>>16);
      cell[nCell++] = (unsigned char)(ovf>>8);
      cell[nCell++] = (unsigned char)(ovf);
      /* write overflow chain */
      {
        int remaining = a[i].nPayload - local;
        int src = local;
        int cur2 = ovf;
        while( remaining>0 ){
          unsigned char *op = b->pPg->ap[cur2-1];
          int nch = remaining > (b->pageSize-4) ? (b->pageSize-4) : remaining;
          int nxt = 0;
          if( remaining-nch>0 ) nxt = pgAlloc(b->pPg);
          op[0] = (unsigned char)(nxt>>24); op[1]=(unsigned char)(nxt>>16);
          op[2] = (unsigned char)(nxt>>8);  op[3]=(unsigned char)(nxt);
          memcpy(op+4, a[i].zPayload+src, nch);
          src += nch;
          remaining -= nch;
          cur2 = nxt;
        }
      }
    }
    contentEnd -= nCell;
    if( contentEnd < hdrOff + 8 + nPtr + 4 ){ /* shouldn't happen */ }
    maxFree = contentEnd;
    arenaAlloc(b->pA, 0);
    (void)nCellsUsed;
    /* record cell pointer later */
    a[i].zPayload = (unsigned char*)(long)0;  /* reuse field to remember cell size */
    {
      /* store cell size in rowid slot hack: keep in separate arrays */
      a[i].nPayload = nCell;   /* now nPayload = total cell size */
    }
  }
  /* Now write the page: we need the cell bytes.  Rebuild by re-packing is
  ** complex; instead use a simpler two-pass approach below. */
  return pg;
}
