/* build a b-tree; returns root page number */
static int buildTree(Bld *b, TreeItem *a, int n, int isIndex, int isSchema){
  Arena *pA = &b->tmpA;
  int *idx, *cnt;
  int nLeaf;
  if( n==0 ){
    return writeLeafPage(b, a, 0, 0, isIndex, isSchema);
  }
  nLeaf = packLeaves(b, a, n, isIndex, isSchema, &idx, &cnt, pA);
  if( nLeaf==1 ){
    return writeLeafPage(b, a, idx[0], cnt[0], isIndex, isSchema);
  }else{
    int nChildren = nLeaf;
    int *aChild = arenaAlloc(pA, (nLeaf+1)*sizeof(int));
    i64 *aKey = arenaAlloc(pA, (nLeaf+1)*sizeof(i64));
    unsigned char **azKey = arenaAlloc(pA, (nLeaf+1)*sizeof(unsigned char*));
    int *anKey = arenaAlloc(pA, (nLeaf+1)*sizeof(int));
    int i;
    for(i=0;i<nLeaf;i++){
      aChild[i] = writeLeafPage(b, a, idx[i], cnt[i], isIndex, isSchema);
      if( isIndex ){
        azKey[i] = a[idx[i]+cnt[i]-1].zPayload;
        anKey[i] = a[idx[i]+cnt[i]-1].nPayload;
      }else{
        aKey[i] = a[idx[i]+cnt[i]-1].rowid;
      }
    }
    while( nChildren>1 ){
      int groupSize = (b->pageSize - (isSchema?100:0) - 12) / 12;
      int nGroups = (nChildren + groupSize - 1)/groupSize;
      int *nChild = arenaAlloc(pA, (nGroups+1)*sizeof(int));
      int g, k = 0;
      for(g=0;g<nGroups;g++){
        int c = groupSize;
        if( k+c > nChildren ) c = nChildren-k;
        nChild[g] = c;
        k += c;
      }
      nChild[nGroups] = 0;
      {
        int *ch2 = arenaAlloc(pA, (nGroups+1)*sizeof(int));
        i64 *ky2 = arenaAlloc(pA, (nGroups+1)*sizeof(i64));
        unsigned char **zk2 = arenaAlloc(pA, (nGroups+1)*sizeof(unsigned char*));
        int *nk2 = arenaAlloc(pA, (nGroups+1)*sizeof(int));
        int pos = 0;
        for(g=0;g<nGroups;g++){
          int c = nChild[g];
          ch2[g] = writeInteriorPage(b, aChild+pos, aKey+pos, azKey+pos, anKey+pos, c, isIndex, isSchema);
          if( isIndex ){
            zk2[g] = azKey[pos+c-1];
            nk2[g] = anKey[pos+c-1];
          }else{
            ky2[g] = aKey[pos+c-1];
          }
          pos += c;
        }
        ch2[nGroups] = ch2[nGroups-1];
        aChild = ch2; aKey = ky2; azKey = zk2; anKey = nk2;
        nChildren = nGroups;
      }
    }
    return aChild[0];
  }
}
