/* ================================================================= */
/* Write a schema to a database file */
typedef struct SObj {
  int kind;      /* 0 table, 1 index, 2 view, 3 trigger */
  Table *t;
  Index *x;
  View *v;
  Trigger *tr;
  i64 rowid;
  int root;
} SObj;

static int cmpObj(const void *a, const void *b){
  const SObj *x = a, *y = b;
  if( x->rowid < y->rowid ) return -1;
  if( x->rowid > y->rowid ) return 1;
  return 0;
}

static int writeSchemaFile(Db *pDb, Schema *pS, Error *pErr){
  Arena *pA = arenaNew();
  PgList pg;
  Bld b;
  SObj *ao;
  int nObj = 0;
  Table *t;
  View *v;
  Trigger *tr;
  Index *x;
  int i;
  int nTbl = 0, nIdx = 0;
  int pgSize = pS->pageSize ? pS->pageSize : pDb->pageSize;
  unsigned char *hdr;
  FILE *f;
  TreeItem *aItems;
  int nItems = 0;
  int schemaRoot;
  int maxPage;
  /* count objects */
  for(t=pS->pTable;t;t=t->pNextTable){ nObj++; }
  for(v=pS->pView;v;v=v->pNext){ nObj++; }
  for(tr=pS->pTrigger;tr;tr=tr->pNext){ nObj++; }
  for(t=pS->pTable;t;t=t->pNextTable){ for(x=t->pIndex;x;x=x->pNext){ nObj++; } }
  ao = malloc((nObj>0?nObj:1)*sizeof(SObj));
  nObj = 0;
  for(t=pS->pTable;t;t=t->pNextTable){ ao[nObj].kind=0; ao[nObj].t=t; ao[nObj].x=0; ao[nObj].v=0; ao[nObj].tr=0; ao[nObj].rowid=t->iSchema; ao[nObj].root=0; nObj++; }
  for(v=pS->pView;v;v=v->pNext){ ao[nObj].kind=2; ao[nObj].v=v; ao[nObj].t=0; ao[nObj].x=0; ao[nObj].tr=0; ao[nObj].rowid=v->iSchema; ao[nObj].root=0; nObj++; }
  for(tr=pS->pTrigger;tr;tr=tr->pNext){ ao[nObj].kind=3; ao[nObj].tr=tr; ao[nObj].t=0; ao[nObj].x=0; ao[nObj].v=0; ao[nObj].rowid=tr->iSchema; ao[nObj].root=0; nObj++; }
  for(t=pS->pTable;t;t=t->pNextTable){ for(x=t->pIndex;x;x=x->pNext){ ao[nObj].kind=1; ao[nObj].x=x; ao[nObj].t=t; ao[nObj].v=0; ao[nObj].tr=0; ao[nObj].rowid=x->iSchema; ao[nObj].root=0; nObj++; } }
  qsort(ao, nObj, sizeof(SObj), cmpObj);
  for(i=0;i<nObj;i++){ if( ao[i].kind==0 ) nTbl++; if( ao[i].kind==1 ) nIdx++; }
  pgInit(&pg, pgSize);
  bldInit(&b, &pg, pA);
  pgAlloc(&pg);            /* page 1 - schema root */
  for(i=0;i<nObj;i++){
    if( ao[i].kind==0 ) ao[i].root = pgAlloc(&pg);
    else if( ao[i].kind==1 ) ao[i].root = pgAlloc(&pg);
  }
  /* build object b-trees */
  aItems = arenaAlloc(pA, (nObj>0?nObj:1)*sizeof(TreeItem));
  nItems = 0;
  for(i=0;i<nObj;i++){
    SObj *o = &ao[i];
    if( o->kind==0 ){
      int j;
      TreeItem *ti = arenaAlloc(pA, (o->t->nRow>0?o->t->nRow:1)*sizeof(TreeItem));
      for(j=0;j<o->t->nRow;j++){
        Row *r = o->t->apRow[j];
        Value *av = arenaAlloc(pA, o->t->nCol*sizeof(Value));
        unsigned char *z;
        int n;
        int k;
        for(k=0;k<o->t->nCol;k++){
          valInit(av+k);
          if( k==o->t->iPk ){ valSetNull(av+k); }
          else valCopy(pA, av+k, r->aVal+k);
        }
        z = encodeRecord(av, o->t->nCol, &n);
        ti[j].zPayload = z;
        ti[j].nPayload = n;
        ti[j].rowid = r->rowid;
        ti[j].isIndex = 0;
      }
      buildTree(&b, ti, o->t->nRow, 0, 0);
    }else if( o->kind==1 ){
      int j;
      TreeItem *ti = arenaAlloc(pA, (o->x->nKey>0?o->x->nKey:1)*sizeof(TreeItem));
      for(j=0;j<o->x->nKey;j++){
        unsigned char *z;
        int n;
        Value *av = arenaAlloc(pA, (o->x->nCol+1)*sizeof(Value));
        int k;
        for(k=0;k<o->x->nCol;k++){ valInit(av+k); valCopy(pA, av+k, o->x->apKeyVal[j]+k); }
        valInit(av+o->x->nCol);
        valSetInt(pA, av+o->x->nCol, o->x->aiKeyRowid[j]);
        z = encodeRecord(av, o->x->nCol+1, &n);
        ti[j].zPayload = z;
        ti[j].nPayload = n;
        ti[j].rowid = 0;
        ti[j].isIndex = 1;
      }
      buildTree(&b, ti, o->x->nKey, 1, 0);
    }
  }
  /* build schema records */
  for(i=0;i<nObj;i++){
    SObj *o = &ao[i];
    const char *zType = o->kind==0?"table":(o->kind==1?"index":(o->kind==2?"view":"trigger"));
    const char *zName = o->kind==0?o->t->zName:(o->kind==1?o->x->zName:(o->kind==2?o->v->zName:o->tr->zName));
    const char *zTbl = o->kind==0?o->t->zName:(o->kind==1?o->x->zTbl:(o->kind==2?o->v->zName:o->tr->zTbl));
    const char *zSql = o->kind==0?o->t->zSql:(o->kind==1?o->x->zSql:(o->kind==2?o->v->zSql:o->tr->zSql));
    unsigned char *z;
    int n;
    z = mkSchemaRecord(pA, zType, zName, zTbl, o->root, zSql, &n);
    aItems[nItems].zPayload = z;
    aItems[nItems].nPayload = n;
    aItems[nItems].rowid = o->rowid;
    aItems[nItems].isIndex = 0;
    nItems++;
  }
  /* sort by rowid */
  {
    int k, m;
    for(k=1;k<nItems;k++){
      TreeItem tmp = aItems[k];
      m = k-1;
      while( m>=0 && aItems[m].rowid>tmp.rowid ){ aItems[m+1]=aItems[m]; m--; }
      aItems[m+1] = tmp;
    }
  }
  schemaRoot = buildTree(&b, aItems, nItems, 0, 1);
  if( schemaRoot!=1 ){
    /* copy root content to page 1 */
    memcpy(pg.ap[0], pg.ap[schemaRoot-1], pgSize);
    memset(pg.ap[schemaRoot-1], 0, pgSize);
  }
  /* write header */
  hdr = pg.ap[0];
  maxPage = pg.n;
  memcpy(hdr, "SQLite format 3\0", 16);
  {
    int ps = pgSize;
    if( ps==65536 ) ps = 1;
    hdr[16] = (unsigned char)((ps>>8)&0xff);
    hdr[17] = (unsigned char)(ps & 0xff);
  }
  hdr[18] = 1;
  hdr[19] = 1;
  hdr[20] = 0;
  hdr[21] = 64;
  hdr[22] = 32;
  hdr[23] = 32;
  {
    u64 u = (u64)nChange;
    hdr[24] = (unsigned char)((u>>24)&0xff);
    hdr[25] = (unsigned char)((u>>16)&0xff);
    hdr[26] = (unsigned char)((u>>8)&0xff);
    hdr[27] = (unsigned char)(u&0xff);
  }
  {
    u64 u = (u64)maxPage;
    hdr[28] = (unsigned char)((u>>24)&0xff);
    hdr[29] = (unsigned char)((u>>16)&0xff);
    hdr[30] = (unsigned char)((u>>8)&0xff);
    hdr[31] = (unsigned char)(u&0xff);
  }
  /* schema cookie */
  {
    u64 u = (u64)pS->schemaCookie;
    hdr[40] = (unsigned char)((u>>24)&0xff);
    hdr[41] = (unsigned char)((u>>16)&0xff);
    hdr[42] = (unsigned char)((u>>8)&0xff);
    hdr[43] = (unsigned char)(u&0xff);
  }
  hdr[44] = 0; hdr[45] = 0; hdr[46] = 0; hdr[47] = 4;
  hdr[56] = 0; hdr[57] = 0; hdr[58] = 0; hdr[59] = 1;   /* utf8 */
  {
    u64 u = (u64)pS->userVersion;
    hdr[60] = (unsigned char)((u>>24)&0xff);
    hdr[61] = (unsigned char)((u>>16)&0xff);
    hdr[62] = (unsigned char)((u>>8)&0xff);
    hdr[63] = (unsigned char)(u&0xff);
  }
  {
    u64 u = (u64)pS->applicationId;
    hdr[68] = (unsigned char)((u>>24)&0xff);
    hdr[69] = (unsigned char)((u>>16)&0xff);
    hdr[70] = (unsigned char)((u>>8)&0xff);
    hdr[71] = (unsigned char)(u&0xff);
  }
  hdr[92] = hdr[24]; hdr[93] = hdr[25]; hdr[94] = hdr[26]; hdr[95] = hdr[27];
  {
    u64 u = 3054000;
    hdr[96] = (unsigned char)((u>>24)&0xff);
    hdr[97] = (unsigned char)((u>>16)&0xff);
    hdr[98] = (unsigned char)((u>>8)&0xff);
    hdr[99] = (unsigned char)(u&0xff);
  }
  arenaDelete(b.tmpA);
  arenaDelete(pA);
  /* write to file */
  f = fopen(pS->zFile, "wb");
  if( f==0 ){
    errSet(pErr, "unable to open database file");
    pgFree(&pg);
    free(ao);
    return 1;
  }
  for(i=0;i<pg.n;i++) fwrite(pg.ap[i], 1, pgSize, f);
  fclose(f);
  pgFree(&pg);
  free(ao);
  pS->nPage = maxPage;
  return 0;
}

int dbWriteFile(Db *p, Error *pErr){
  Schema *s;
  int rc = 0;
  if( p->pMain && p->pMain->zFile && p->pMain->zFile[0] ){
    rc = writeSchemaFile(p, p->pMain, pErr);
    if( rc ) return rc;
  }
  for(s=p->pAttached; s; s=s->pNext){
    if( s->zFile && s->zFile[0] ){
      rc = writeSchemaFile(p, s, pErr);
      if( rc ) return rc;
    }
  }
  return 0;
}
