/* ================================================================= */
/* read a database file */
static unsigned char *readAllPages(const char *zFile, int *pPageSize, i64 *pNPage, Error *pErr){
  FILE *f;
  unsigned char hdr[100];
  int pageSize;
  long fsize;
  unsigned char *buf;
  f = fopen(zFile, "rb");
  if( f==0 ){ errSet(pErr,"unable to open database file"); return 0; }
  if( fread(hdr,1,100,f)!=100 ){ fclose(f); errSet(pErr,"unable to read database header"); return 0; }
  if( memcmp(hdr,"SQLite format 3\0",16)!=0 ){
    fclose(f);
    errSet(pErr,"file is not a database");
    return 0;
  }
  pageSize = (hdr[16]<<8)|hdr[17];
  if( pageSize==1 ) pageSize = 65536;
  if( pageSize<512 || (pageSize & (pageSize-1))!=0 ){
    fclose(f); errSet(pErr,"invalid page size"); return 0;
  }
  fseek(f,0,SEEK_END);
  fsize = ftell(f);
  fseek(f,0,SEEK_SET);
  buf = malloc(fsize+pageSize);
  if( fread(buf,1,fsize,f)!=(size_t)fsize ){ free(buf); fclose(f); errSet(pErr,"short read"); return 0; }
  memset(buf+fsize,0,pageSize);
  fclose(f);
  *pPageSize = pageSize;
  *pNPage = (fsize + pageSize - 1)/pageSize;
  return buf;
}

static void decodeRecord(Arena *pA, const unsigned char *z, int n, Value *aOut, int nOut){
  u64 hdrLen = 0;
  int off = 0;
  int i;
  u64 types[64];
  int nType = 0;
  u64 v;
  int k;
  if( n<1 ){ for(i=0;i<nOut;i++) valSetNull(aOut+i); return; }
  k = getVarint(z, &hdrLen);
  off = k;
  while( off<(int)hdrLen && nType<64 ){
    off += getVarint(z+off, &v);
    types[nType++] = v;
  }
  off = (int)hdrLen;
  for(i=0;i<nOut;i++){
    u64 t = (i<nType) ? types[i] : 0;
    if( t==0 ){ valSetNull(aOut+i); }
    else if( t>=1 && t<=6 ){
      i64 x = 0;
      int nb = t==1?1:(t==2?2:(t==3?3:(t==4?4:(t==5?6:8))));
      int j;
      int neg = 0;
      for(j=0;j<nb;j++){
        int b = (j<nb) ? (off+j<n ? z[off+j] : 0) : 0;
        x = (x<<8) | (b & 0xff);
      }
      /* sign extend */
      if( z[off] & 0x80 ) neg = 1;
      if( neg ){
        i64 mask = -1;
        int bits = nb*8;
        if( bits<64 ) x = x - (i64)1<<(bits);
      }
      off += nb;
      valSetInt(pA, aOut+i, x);
    }
    else if( t==7 ){
      u64 u = 0;
      int j;
      for(j=0;j<8;j++) u = (u<<8) | (z[off+j]&0xff);
      { double d; memcpy(&d,&u,8); valSetReal(pA, aOut+i, d); }
      off += 8;
    }
    else if( t==8 ){ valSetInt(pA, aOut+i, 0); }
    else if( t==9 ){ valSetInt(pA, aOut+i, 1); }
    else if( t>=12 && (t%2)==0 ){
      int len = (int)((t-12)/2);
      valSetBlob(pA, aOut+i, z+off, len);
      off += len;
    }
    else if( t>=13 ){
      int len = (int)((t-13)/2);
      valSetTextN(pA, aOut+i, z+off, len);
      off += len;
    }
    else valSetNull(aOut+i);
  }
}

typedef struct Walk {
  unsigned char **apPage;
  int nPage;
  int pageSize;
  Arena *pA;
  TreeItem *a;
  int n, cap;
} Walk;
static void walkAdd(Walk *w, TreeItem it){
  if( w->n>=w->cap ){
    w->cap = w->cap?w->cap*2:16;
    w->a = arenaRealloc(w->pA, w->a, w->n*sizeof(TreeItem), w->cap*sizeof(TreeItem));
  }
