#include "core.h"
#include "lex.h"
#include "parse.h"
#include "db.h"
#include "exec.h"
#include "func.h"

/* ---------------- string helpers ---------------- */
static int hexVal(int c){
  if( c>='0' && c<='9' ) return c-'0';
  if( c>='a' && c<='f' ) return c-'a'+10;
  if( c>='A' && c<='F' ) return c-'A'+10;
  return -1;
}
static void utf8CharLen(const unsigned char *z, int n, int *pLen, int *pVal){
  int c = z[0];
  if( c<0x80 ){ *pLen=1; *pVal=c; return; }
  if( (c&0xe0)==0xc0 && n>=2 ){ *pLen=2; *pVal=((c&0x1f)<<6)|(z[1]&0x3f); return; }
  if( (c&0xf0)==0xe0 && n>=3 ){ *pLen=3; *pVal=((c&0x0f)<<12)|((z[1]&0x3f)<<6)|(z[2]&0x3f); return; }
  if( (c&0xf8)==0xf0 && n>=4 ){ *pLen=4; *pVal=((c&0x07)<<18)|((z[1]&0x3f)<<12)|((z[2]&0x3f)<<6)|(z[3]&0x3f); return; }
  *pLen=1; *pVal=c;
}
static int utf8Count(const unsigned char *z, int n){
  int i = 0, cnt = 0;
  while( i<n ){
    int len, val;
    utf8CharLen(z+i, n-i, &len, &val);
    i += len;
    cnt++;
  }
  return cnt;
}
static int utf8Offset(const unsigned char *z, int n, int chars){
  int i = 0, cnt = 0;
  while( i<n && cnt<chars ){
    int len, val;
    utf8CharLen(z+i, n-i, &len, &val);
    i += len;
    cnt++;
  }
  return i;
}

/* ---------------- quote helper ---------------- */
char *quoteSql(Arena *pA, Value *p){
  int i, n = 0;
  char *z;
  if( p->type==VT_NULL ) return arenaStrdup(pA,"NULL");
  if( p->type==VT_INT ) return arenaStrdup(pA, strPrintf("%lld",p->i));
  if( p->type==VT_REAL ) return arenaStrdup(pA, realToText(pA,p->r));
  if( p->type==VT_BLOB ){
    char *r = arenaAlloc(pA, 2 + p->n*2 + 4);
    sprintf(r, "x'");
    for(i=0;i<p->n;i++) sprintf(r+2+i*2, "%02x", (unsigned char)p->z[i]);
    strcat(r, "'");
    return r;
  }
  z = arenaAlloc(pA, p->n*2+4);
  z[n++] = '\'';
  for(i=0;i<p->n;i++){
    z[n++] = p->z[i];
    if( p->z[i]=='\'' ) z[n++] = '\'';
  }
  z[n++] = '\'';
  z[n] = 0;
  return z;
}

/* ---------------- date/time ---------------- */
static double jdaysFromYMD(int Y, int M, int D){
  double jd;
  int A, B;
  if( M<=2 ){ Y -= 1; M += 12; }
  A = Y/100;
  B = 2 - A + (A/4);
  jd = floor(365.25*(Y+4716)) + floor(30.6001*(M+1)) + D + B - 1524.5;
  return jd;
