  i = (int)(p-z);
  /* simple validator */
  for(;;){
    p = jsonSkipWs(z,n,i);
    if( p-z>=n ) return depth==0;
    i = (int)(p-z);
    if( z[i]=='{' || z[i]=='[' ){ depth++; i++; continue; }
    if( z[i]=='}' || z[i]==']' ){ depth--; if(depth<0) return 0; i++; continue; }
    if( z[i]=='"' ){
      i++;
      while( i<n ){
        if( z[i]=='\\' ){ i+=2; continue; }
        if( z[i]=='"' ){ i++; break; }
        i++;
      }
      continue;
    }
    if( z[i]==':' ){ i++; continue; }
    if( z[i]==',' ){ i++; continue; }
    /* number / literal */
    if( isdigit((unsigned char)z[i]) || z[i]=='-' || z[i]=='+' || z[i]=='.' ){
      while( i<n && (isdigit((unsigned char)z[i])||z[i]=='-'||z[i]=='+'||z[i]=='.'||z[i]=='e'||z[i]=='E') ) i++;
      continue;
    }
    if( strncasecmp(z+i,"null",4)==0 ){ i+=4; continue; }
    if( strncasecmp(z+i,"true",4)==0 ){ i+=4; continue; }
    if( strncasecmp(z+i,"false",5)==0 ){ i+=5; continue; }
    return 0;
  }
}
const char *jsonTypeOf(const char *z, int n){
