      else amt = textToReal(z);
      if( neg ) amt = -amt;
      if( strncasecmp(z+ (z[0]=='+'||z[0]=='-'),"days",4)==0 ) jd += amt;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"hours",5)==0 ) jd += amt/24.0;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"minutes",7)==0 ) jd += amt/1440.0;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"seconds",7)==0 ) jd += amt/86400.0;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"months",6)==0 ){
