static int dtArgs(FuncCtx *p, Value *a, int n, double *pJd){
  int i;
  double jd = 0;
  int ok;
  if( n<1 || a[0].type==VT_NULL ) return 0;
  if( !parseDateTime(valText(p->pA,&a[0]), &jd, &ok) ) return 0;
  for(i=1;i<n;i++){
    if( a[i].type==VT_NULL ) continue;
    {
      const char *z = valText(p->pA,&a[i]);
      double amt;
      int neg = 0;
      if( strncasecmp(z,"start of month",14)==0 ){
        int Y,M,D;
        ymdFromJd(jd,&Y,&M,&D);
        jd = jdaysFromYMD(Y,M,1);
        continue;
      }
      if( strncasecmp(z,"start of year",13)==0 ){
        int Y,M,D;
        ymdFromJd(jd,&Y,&M,&D);
        jd = jdaysFromYMD(Y,1,1);
        continue;
      }
      if( strncasecmp(z,"start of day",12)==0 ){
        int Y,M,D;
        ymdFromJd(jd,&Y,&M,&D);
        jd = jdaysFromYMD(Y,M,D);
        continue;
      }
      if( strncasecmp(z,"weekday",7)==0 ){
        int target = atoi(z+7);
        int wd = ((int)floor(jd+0.5)+1)%7;
        int add = (target-wd+7)%7;
        if( add==0 ) add = 7;
        jd += add;
        continue;
      }
      if( strncasecmp(z,"localtime",9)==0 || strncasecmp(z,"utc",3)==0 ) continue;
      if( z[0]=='+' ){ neg = 0; amt = textToReal(z+1); }
      else if( z[0]=='-' ){ neg = 1; amt = textToReal(z+1); }
      else amt = textToReal(z);
      if( neg ) amt = -amt;
      if( strncasecmp(z+ (z[0]=='+'||z[0]=='-'),"days",4)==0 ) jd += amt;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"hours",5)==0 ) jd += amt/24.0;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"minutes",7)==0 ) jd += amt/1440.0;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"seconds",7)==0 ) jd += amt/86400.0;
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"months",6)==0 ){
        int Y,M,D;
        ymdFromJd(jd,&Y,&M,&D);
        M += (int)amt;
        Y += (M-1)/12;
        M = ((M-1)%12)+1;
        jd = jdaysFromYMD(Y,M,D);
      }
      else if( strncasecmp(z+(z[0]=='+'||z[0]=='-'),"years",5)==0 ){
        int Y,M,D;
        ymdFromJd(jd,&Y,&M,&D);
        Y += (int)amt;
        jd = jdaysFromYMD(Y,M,D);
      }
    }
  }
  *pJd = jd;
  return 1;
}
