static void f_printf(FuncCtx *p, Value *a, int n, Value *o){
  char buf[4096];
  int k = 0;
  int i = 1;
  const char *z;
  if( n<1 || a[0].type==VT_NULL ){ valSetNull(o); return; }
  z = valText(p->pA,&a[0]);
  for(; *z && k<(int)sizeof(buf)-16; z++){
