    z++;
    if( *z==0 ) break;
    if( *z=='%' ){ buf[k++]='%'; continue; }
    {
      char spec[32];
      int sp = 0;
      while( *z && strchr("-+ #0123456789.*l",*z) && sp<28 ){ spec[sp++]=*z; z++; }
      if( *z==0 ) break;
      spec[sp++] = *z;
      spec[sp] = 0;
      if( *z=='d' || *z=='i' || *z=='x' || *z=='X' || *z=='o' ){
        i64 v = 0;
        if( i<n && a[i].type!=VT_NULL ) v = (a[i].type==VT_INT)?a[i].i:(i64)textToReal(valText(p->pA,&a[i]));
        i++;
        k += snprintf(buf+k,sizeof(buf)-k,spec,v);
