        double v = 0;
        if( i<n && a[i].type!=VT_NULL ) v = (a[i].type==VT_REAL)?a[i].r:((a[i].type==VT_INT)?(double)a[i].i:textToReal(valText(p->pA,&a[i])));
        i++;
        k += snprintf(buf+k,sizeof(buf)-k,spec,v);
      }else if( *z=='s' ){
        const char *v = "";
        if( i<n && a[i].type!=VT_NULL ) v = valText(p->pA,&a[i]);
        i++;
        k += snprintf(buf+k,sizeof(buf)-k,spec,v);
      }else if( *z=='q' ){
        const char *v = "";
        if( i<n && a[i].type!=VT_NULL ) v = valText(p->pA,&a[i]);
        i++;
        k += snprintf(buf+k,sizeof(buf)-k,"%s",v);
      }else if( *z=='w' ){
        const char *v = "";
        if( i<n && a[i].type!=VT_NULL ) v = valText(p->pA,&a[i]);
        i++;
        k += snprintf(buf+k,sizeof(buf)-k,"%s",v);
      }else{
        buf[k++] = '%';
        k += snprintf(buf+k,sizeof(buf)-k,"%s",spec);
      }
    }
  }
  buf[k] = 0;
  valSetText(p->pA,o,buf);
}

