int likeMatch(const char *zPat, int np, const char *zStr, int ns, int esc){
  int iPat = 0, iStr = 0;
  unsigned char c, c2, prior_c = 0;
  int cEsc = esc & 0xff;
  int seen = 0;
  while( iPat<np ){
    c = zPat[iPat++];
    if( cEsc && c==cEsc && iPat<np ){
      c = zPat[iPat++];
      if( iStr>=ns || (unsigned char)zStr[iStr]!=c ) return 0;
      iStr++;
      prior_c = c;
      seen = 1;
      continue;
    }
    if( c=='*' || c=='%' ){
      /* collapse */
      while( iPat<np && ((c=zPat[iPat])=='%'||c=='*') ) iPat++;
      if( iPat>=np ) return 1;
      while( iStr<ns ){
        if( likeMatch(zPat+iPat, np-iPat, zStr+iStr, ns-iStr, esc) ) return 1;
        iStr++;
      }
      return 0;
    }
    if( c=='_' || c=='?' ){
      if( iStr>=ns ) return 0;
      iStr++;
      prior_c = c;
      seen = 1;
      continue;
    }
    if( c=='[' ){
      int not = 0;
