        if( zPat[iPat]=='-' && !first && iPat+1<np && zPat[iPat+1]!=']' ){
          lo = (unsigned char)zPat[iPat-1];
          hi = (unsigned char)zPat[iPat+1];
          if( c2>=lo && c2<=hi ) match = 1;
          iPat += 2;
          continue;
        }
        if( iPat+1<np && zPat[iPat]=='-' && zPat[iPat+1]!=']' ){
          /* handled above */
        }
        if( (unsigned char)zPat[iPat]==c2 ) match = 1;
        iPat++;
        first = 0;
