      if( iPat>=np ) return 1;
      while( iStr<ns ){
        if( likeMatch(zPat+iPat, np-iPat, zStr+iStr, ns-iStr, esc) ) return 1;
        iStr++;
      }
      return 0;
    }
    if( c=='_' || c=='?' ){
      if( iStr>=ns ) return 0;
      iStr++;
      prior_c = c;
      seen = 1;
      continue;
    }
    if( c=='[' ){
      int not = 0;
      int first = 1;
      int match = 0;
      if( iStr>=ns ) return 0;
      if( iPat<np && zPat[iPat]=='^' ){ not = 1; iPat++; }
      c2 = zStr[iStr];
      while( iPat<np && zPat[iPat]!=']' ){
        int lo, hi;
        if( zPat[iPat]=='-' && !first && iPat+1<np && zPat[iPat+1]!=']' ){
          lo = (unsigned char)zPat[iPat-1];
          hi = (unsigned char)zPat[iPat+1];
          if( c2>=lo && c2<=hi ) match = 1;
          iPat += 2;
          continue;
        }
        if( iPat+1<np && zPat[iPat]=='-' && zPat[iPat+1]!=']' ){
          /* handled above */
        }
        if( (unsigned char)zPat[iPat]==c2 ) match = 1;
        iPat++;
        first = 0;
      }
      if( iPat<np && zPat[iPat]==']' ) iPat++;
      if( match==not ) return 0;
      iStr++;
      prior_c = c;
      seen = 1;
      continue;
    }
    if( iStr>=ns || (unsigned char)zStr[iStr]!=c ) return 0;
    iStr++;
    prior_c = c;
    seen = 1;
  }
  if( !seen && ns>0 ) return 1;
  return iStr==ns;
}
int globMatch(const char *zPat, int np, const char *zStr, int ns){
  int iPat = 0, iStr = 0;
  unsigned char c, c2;
  while( iPat<np ){
    c = zPat[iPat++];
    if( c=='*' || c=='%' ){
      while( iPat<np && ((c=zPat[iPat])=='%'||c=='*') ) iPat++;
      if( iPat>=np ) return 1;
      while( iStr<ns ){
        if( globMatch(zPat+iPat,np-iPat,zStr+iStr,ns-iStr) ) return 1;
        iStr++;
      }
      return 0;
    }
    if( c=='_' || c=='?' ){
      if( iStr>=ns ) return 0;
      iStr++;
      continue;
    }
    if( c=='[' ){
      int not = 0, first = 1, match = 0;
      if( iStr>=ns ) return 0;
      if( iPat<np && zPat[iPat]=='^' ){ not=1; iPat++; }
      c2 = zStr[iStr];
      while( iPat<np && zPat[iPat]!=']' ){
        if( zPat[iPat]=='-' && !first && iPat+1<np && zPat[iPat+1]!=']' ){
          int lo = (unsigned char)zPat[iPat-1], hi = (unsigned char)zPat[iPat+1];
          if( c2>=lo && c2<=hi ) match = 1;
          iPat += 2;
          continue;
        }
        if( (unsigned char)zPat[iPat]==c2 ) match = 1;
        iPat++;
        first = 0;
      }
      if( iPat<np && zPat[iPat]==']' ) iPat++;
      if( match==not ) return 0;
      iStr++;
      continue;
    }
    if( iStr>=ns || (unsigned char)zStr[iStr]!=c ) return 0;
    iStr++;
  }
  return iStr==ns;
}

/* ============ misc ============ */
int evalIsTrue(Value *p){
  if( p->type==VT_INT ) return p->i!=0;
  if( p->type==VT_REAL ) return p->r!=0.0 && p->r==p->r;
  if( p->type==VT_TEXT ) return textToReal(p->z)!=0.0;
  if( p->type==VT_BLOB ) return 0;
  return 0;
}

/* ============ aggregates ============ */
typedef struct AggAcc {
  int kind;         /* 0 count, 1 sum, 2 total, 3 avg, 4 min, 5 max, 6 group_concat, 7 string_agg, 8 json_group_array, 9 json_group_object */
  i64 i;
  double r;
  char *z;
  int n;
  int nRow;
  int distinct;
  int seenNull;
  int bInt;
  int bOverflow;
} AggAcc;

static int isAggName(const char *z){
  static const char *az[] = {"count","sum","total","avg","min","max","group_concat",
                             "string_agg","json_group_array","json_group_object","total_changes",0};
  int i;
  for(i=0;az[i];i++) if( strEq(az[i],z) ) return 1;
  return 0;
}
static void aggStep(AggAcc *p, Arena *pA, Value *aArg, int nArg, int isStar){
  switch( p->kind ){
    case 0: /* count */
      if( isStar ) p->i++;
      else if( aArg[0].type!=VT_NULL ) p->i++;
      p->nRow++;
      break;
    case 1: case 2: {  /* sum/total */
      double d;
      if( aArg[0].type==VT_NULL ) break;
      if( aArg[0].type==VT_INT ){
        if( p->bInt && !p->bOverflow ){
          i64 v = p->i + aArg[0].i;
          if( (p->i>0 && aArg[0].i>0 && v<0) || (p->i<0 && aArg[0].i<0 && v>0) ){ p->bOverflow=1; }
          p->i = v;
        }
        d = (double)aArg[0].i;
      }else if( aArg[0].type==VT_REAL ){ d = aArg[0].r; p->bInt = 0; }
      else { d = textToReal(valText(pA,&aArg[0])); p->bInt = 0; }
      p->r += d;
      p->nRow++;
      break;
    }
    case 3: {
      double d;
      if( aArg[0].type==VT_NULL ) break;
      if( aArg[0].type==VT_INT ) d = (double)aArg[0].i;
      else if( aArg[0].type==VT_REAL ) d = aArg[0].r;
      else d = textToReal(valText(pA,&aArg[0]));
      p->r += d;
      p->nRow++;
      break;
    }
    case 4: case 5: {
      Value tmp;
      valInit(&tmp);
      if( aArg[0].type==VT_NULL ) return;
      if( p->nRow==0 ){ valCopy(pA,&p->z?(Value*)0:&tmp,&aArg[0]); }
      (void)tmp;
      if( p->nRow==0 ){
        valCopy(pA, (Value*)p->z, &aArg[0]);
      }else{
        Value *cur = (Value*)p->z;
        int c = valCmp(&aArg[0], cur);
        if( (p->kind==4 && c<0) || (p->kind==5 && c>0) ) valCopy(pA, cur, &aArg[0]);
      }
      p->nRow++;
      break;
    }
    case 6: {
      const char *zSep = nArg>1 ? valText(pA,&aArg[1]) : ",";
      if( aArg[0].type==VT_NULL ) break;
      if( p->z==0 ){ p->z = arenaStrdup(pA, valText(pA,&aArg[0])); p->n = (int)strlen(p->z); }
      else {
        char *t = arenaStrdup(pA, p->z);
        t = arenaRealloc(pA, t, p->n, p->n + strlen(zSep) + strlen(valText(pA,&aArg[0])) + 1);
        strcat(t, zSep);
        strcat(t, valText(pA,&aArg[0]));
        p->z = t;
        p->n = (int)strlen(t);
      }
      p->nRow++;
      break;
    }
    case 7: {
      const char *zSep = nArg>1 ? valText(pA,&aArg[1]) : "";
      if( aArg[0].type==VT_NULL ) break;
      if( p->z==0 ){ p->z = arenaStrdup(pA, valText(pA,&aArg[0])); p->n=(int)strlen(p->z); }
      else {
        char *t = arenaStrdup(pA, p->z);
        t = arenaRealloc(pA, t, p->n, p->n + strlen(zSep) + strlen(valText(pA,&aArg[0])) + 1);
        strcat(t, zSep);
        strcat(t, valText(pA,&aArg[0]));
        p->z = t;
        p->n = (int)strlen(t);
      }
      p->nRow++;
      break;
    }
    case 8: {
      char *jq = jsonQuote(pA,&aArg[0]);
      if( p->z==0 ){ p->z = arenaStrdup(pA,"["); p->n=1; }
      else { p->z = arenaRealloc(pA, p->z, p->n, p->n+1); strcat(p->z,","); p->n++; }
      p->z = arenaRealloc(pA, p->z, p->n, p->n + (int)strlen(jq) + 1);
      strcat(p->z, jq);
      p->n = (int)strlen(p->z);
      p->nRow++;
      break;
    }
    case 9: {
      char *jq = jsonQuote(pA,&aArg[1]);
      char *kq = jsonQuote(pA,&aArg[0]);
      if( p->z==0 ){ p->z = arenaStrdup(pA,"{"); p->n=1; }
      else { p->z = arenaRealloc(pA, p->z, p->n, p->n+1); strcat(p->z,","); p->n++; }
      p->z = arenaRealloc(pA, p->z, p->n, p->n + (int)strlen(kq)+1+(int)strlen(jq)+1);
      strcat(p->z,kq); strcat(p->z,":"); strcat(p->z,jq);
      p->n = (int)strlen(p->z);
      p->nRow++;
      break;
    }
  }
}
static void aggFinal(AggAcc *p, Arena *pA, Value *o){
  switch( p->kind ){
    case 0: valSetInt(pA,o,p->i); break;
    case 1:
      if( p->nRow==0 ){ valSetNull(o); break; }
      if( p->bOverflow || !p->bInt ){ valSetReal(pA,o,p->r); }
      else valSetInt(pA,o,p->i);
      break;
    case 2: valSetReal(pA,o,p->r); break;
    case 3:
      if( p->nRow==0 ) valSetNull(o);
      else valSetReal(pA,o,p->r/p->nRow);
      break;
    case 4: case 5:
      if( p->nRow==0 ) valSetNull(o);
      else valCopy(pA,o,(Value*)p->z);
      break;
    case 6: case 7:
      if( p->z==0 ) valSetNull(o); else valSetTextN(pA,o,p->z,p->n);
      break;
    case 8: valSetText(pA,o, p->z ? strAppend(p->z,"]") : "[]"); break;
    case 9: valSetText(pA,o, p->z ? strAppend(p->z,"}") : "{}"); break;
  }
}
