/* ============ scopes ============ */
typedef struct CurRow {
  Value **apRow;
  i64 *aiRowid;
} CurRow;

static Scope *scopeNew(Eval *p, Scope *pParent){
  Scope *s = arenaAlloc(p->pA, sizeof(Scope));
  memset(s,0,sizeof(*s));
  s->pParent = pParent;
  s->pEv = p;
  return s;
}
static void scopeAddRows(Scope *s, const char *zAlias, RowBuf *pRows, char **azCol, int nCol, int bRowid){
  int iOff = 0;
  int i;
  for(i=0;i<s->nSrc;i++) iOff += s->a[i].nCol + (s->a[i].bRowid?1:0);
  s->a[s->nSrc].zAlias = zAlias ? arenaStrdup(s->pEv->pA, zAlias) : 0;
  s->a[s->nSrc].pTab = 0;
  s->a[s->nSrc].pRows = pRows;
  s->a[s->nSrc].azCol = azCol;
  s->a[s->nSrc].nCol = nCol;
  s->a[s->nSrc].iOff = iOff;
  s->a[s->nSrc].bRowid = bRowid;
  s->nSrc++;
}
static void scopeAddTable(Scope *s, const char *zAlias, Table *pTab){
  char **az = arenaAlloc(s->pEv->pA, pTab->nCol*sizeof(char*));
  int i;
  for(i=0;i<pTab->nCol;i++) az[i] = pTab->aCol[i].zName;
  scopeAddRows(s, zAlias, 0, az, pTab->nCol, !pTab->withoutRowid);
  s->a[s->nSrc-1].pTab = pTab;
}

/* find a column in a scope */
static int scopeFindCol(Scope *s, const char *zTab, const char *zCol, int *piSrc){
  int i, j;
  int isRowid = strEq(zCol,"rowid")||strEq(zCol,"oid")||strEq(zCol,"_rowid_");
  if( zTab ){
    for(i=0;i<s->nSrc;i++){
      if( strEq(s->a[i].zAlias, zTab) ){
        for(j=0;j<s->a[i].nCol;j++) if( strEq(s->a[i].azCol[j], zCol) ){ *piSrc = i; return j; }
        if( isRowid && s->a[i].bRowid ){ *piSrc=i; return -1; }
        return -2;
      }
    }
    return -2;
  }
  for(i=0;i<s->nSrc;i++){
    for(j=0;j<s->a[i].nCol;j++) if( strEq(s->a[i].azCol[j], zCol) ){ *piSrc=i; return j; }
  }
  for(i=0;i<s->nSrc;i++){
    if( isRowid && s->a[i].bRowid ){ *piSrc=i; return -1; }
  }
  return -1;
}

/* ============ resolution ============ */
static int exprHasAgg(Eval *p, Expr *e);
static int resolveExpr(Eval *p, Expr *e, Scope *pScope){
  int rc = 0;
  if( e==0 ) return 0;
  switch( e->op ){
    case TKX_COLUMN: {
      int iSrc = -1;
      int iCol;
      if( pScope==0 ) return 0;
      iCol = scopeFindCol(pScope, e->zTok2, e->zTok, &iSrc);
      if( iCol==-2 ){
        errSetPos(p->pErr, e->start, "no such column: %s", e->zTok);
        return 1;
      }
      if( iCol==-1 ){
        Scope *ps = pScope;
        while( ps && iCol==-1 ){
          iCol = scopeFindCol(ps, e->zTok2, e->zTok, &iSrc);
          if( iCol==-1 && ps->pParent==0 ){
            errSetPos(p->pErr, e->start, "no such column: %s", e->zTok);
            return 1;
          }
          if( iCol==-1 ) ps = ps->pParent;
        }
        if( iCol==-1 ) return 1;
      }
      e->iSrc = iSrc;
      e->iCol = iCol;
      e->flags |= EF_Const*0;
      return 0;
    }
    case TKX_ROWID: {
      int iSrc = 0;
      if( pScope==0 ) return 0;
      e->iSrc = 0;
      e->iCol = -1;
      if( e->zTok2 ){
        int i;
        for(i=0;i<pScope->nSrc;i++) if( strEq(pScope->a[i].zAlias, e->zTok2) ) { iSrc=i; break; }
      }
      e->iSrc = iSrc;
      if( !pScope->a[iSrc].bRowid ){
        errSetPos(p->pErr, e->start, "no such column: %s", e->zTok);
        return 1;
      }
      return 0;
    }
    case TKX_FUNCTION: {
      int i;
      FuncCtx fc;
      if( isAggName(e->zTok) ) e->flags |= EF_Agg;
      else if( strEq(e->zTok,"changes")||strEq(e->zTok,"last_insert_rowid")||strEq(e->zTok,"total_changes")||strEq(e->zTok,"random") ) e->flags |= EF_Agg*0;
      if( e->pList ){
        for(i=0;i<e->pList->nExpr;i++){
          if( resolveExpr(p, e->pList->apExpr[i], pScope) ) return 1;
        }
      }
      if( !isAggName(e->zTok) ){
        memset(&fc,0,sizeof(fc));
        fc.pA = p->pA;
        fc.pErr = p->pErr;
        if( funcFind(e->zTok, e->pList?e->pList->nExpr:0)==0 ){
          if( strEq(e->zTok,"sqlite_offset")||strEq(e->zTok,"load_extension") ){
            errSetPos(p->pErr, e->start, "no such function: %s", e->zTok);
            return 1;
          }
          errSetPos(p->pErr, e->start, "no such function: %s", e->zTok);
          return 1;
        }
      }
      if( e->flags & EF_Agg ) e->aggKind = 1;
      return 0;
    }
    case TKX_SELECT: {
      return 0;
    }
    default:
      if( e->pLeft ) rc |= resolveExpr(p, e->pLeft, pScope);
      if( e->pRight ) rc |= resolveExpr(p, e->pRight, pScope);
      if( e->pList ){
        int i;
        for(i=0;i<e->pList->nExpr;i++) rc |= resolveExpr(p, e->pList->apExpr[i], pScope);
      }
      return rc;
  }
}
static int exprHasAgg(Eval *p, Expr *e){
  int r = 0;
  if( e==0 ) return 0;
  if( e->flags & EF_Agg ) return 1;
  r |= exprHasAgg(p, e->pLeft);
  r |= exprHasAgg(p, e->pRight);
  if( e->pList ){ int i; for(i=0;i<e->pList->nExpr;i++) r |= exprHasAgg(p, e->pList->apExpr[i]); }
  return r;
}
