/* ============ scopes ============ */
typedef struct CurRow {
  Value **apRow;
  i64 *aiRowid;
} CurRow;

static Scope *scopeNew(Eval *p, Scope *pParent){
  Scope *s = arenaAlloc(p->pA, sizeof(Scope));
  memset(s,0,sizeof(*s));
  s->pParent = pParent;
  s->pEv = p;
  return s;
}
static void scopeAddRows(Scope *s, const char *zAlias, RowBuf *pRows, char **azCol, int nCol, int bRowid){
  int iOff = 0;
  int i;
  for(i=0;i<s->nSrc;i++) iOff += s->a[i].nCol + (s->a[i].bRowid?1:0);
  s->a[s->nSrc].zAlias = zAlias ? arenaStrdup(s->pEv->pA, zAlias) : 0;
  s->a[s->nSrc].pTab = 0;
  s->a[s->nSrc].pRows = pRows;
  s->a[s->nSrc].azCol = azCol;
  s->a[s->nSrc].nCol = nCol;
  s->a[s->nSrc].iOff = iOff;
  s->a[s->nSrc].bRowid = bRowid;
  s->nSrc++;
}
static void scopeAddTable(Scope *s, const char *zAlias, Table *pTab){
  char **az = arenaAlloc(s->pEv->pA, pTab->nCol*sizeof(char*));
  int i;
  for(i=0;i<pTab->nCol;i++) az[i] = pTab->aCol[i].zName;
  scopeAddRows(s, zAlias, 0, az, pTab->nCol, !pTab->withoutRowid);
  s->a[s->nSrc-1].pTab = pTab;
}

/* find a column in a scope */
static int scopeFindCol(Scope *s, const char *zTab, const char *zCol, int *piSrc){
  int i, j;
  int isRowid = strEq(zCol,"rowid")||strEq(zCol,"oid")||strEq(zCol,"_rowid_");
  if( zTab ){
    for(i=0;i<s->nSrc;i++){
      if( strEq(s->a[i].zAlias, zTab) ){
        for(j=0;j<s->a[i].nCol;j++) if( strEq(s->a[i].azCol[j], zCol) ){ *piSrc = i; return j; }
        if( isRowid && s->a[i].bRowid ){ *piSrc=i; return -1; }
        return -2;
      }
    }
    return -2;
  }
  for(i=0;i<s->nSrc;i++){
    for(j=0;j<s->a[i].nCol;j++) if( strEq(s->a[i].azCol[j], zCol) ){ *piSrc=i; return j; }
  }
  for(i=0;i<s->nSrc;i++){
    if( isRowid && s->a[i].bRowid ){ *piSrc=i; return -1; }
  }
  return -1;
}

/* ============ resolution ============ */
static int exprHasAgg(Eval *p, Expr *e);
static int resolveExpr(Eval *p, Expr *e, Scope *pScope){
  int rc = 0;
  if( e==0 ) return 0;
  switch( e->op ){
    case TKX_COLUMN: {
      int iSrc = -1;
      int iCol;
      if( pScope==0 ) return 0;
      iCol = scopeFindCol(pScope, e->zTok2, e->zTok, &iSrc);
      if( iCol==-2 ){
        errSetPos(p->pErr, e->start, "no such column: %s", e->zTok);
        return 1;
      }
      if( iCol==-1 ){
        Scope *ps = pScope;
        while( ps && iCol==-1 ){
          iCol = scopeFindCol(ps, e->zTok2, e->zTok, &iSrc);
          if( iCol==-1 && ps->pParent==0 ){
            errSetPos(p->pErr, e->start, "no such column: %s", e->zTok);
            return 1;
          }
          if( iCol==-1 ) ps = ps->pParent;
        }
        if( iCol==-1 ) return 1;
      }
      e->iSrc = iSrc;
      e->iCol = iCol;
      e->flags |= EF_Const*0;
      return 0;
    }
    case TKX_ROWID: {
      int iSrc = 0;
      if( pScope==0 ) return 0;
      e->iSrc = 0;
      e->iCol = -1;
      if( e->zTok2 ){
        int i;
        for(i=0;i<pScope->nSrc;i++) if( strEq(pScope->a[i].zAlias, e->zTok2) ) { iSrc=i; break; }
      }
      e->iSrc = iSrc;
      if( !pScope->a[iSrc].bRowid ){
        errSetPos(p->pErr, e->start, "no such column: %s", e->zTok);
        return 1;
      }
      return 0;
    }
    case TKX_FUNCTION: {
      int i;
      FuncCtx fc;
      if( isAggName(e->zTok) ) e->flags |= EF_Agg;
      else if( strEq(e->zTok,"changes")||strEq(e->zTok,"last_insert_rowid")||strEq(e->zTok,"total_changes")||strEq(e->zTok,"random") ) e->flags |= EF_Agg*0;
      if( e->pList ){
        for(i=0;i<e->pList->nExpr;i++){
          if( resolveExpr(p, e->pList->apExpr[i], pScope) ) return 1;
        }
      }
      if( !isAggName(e->zTok) ){
        memset(&fc,0,sizeof(fc));
        fc.pA = p->pA;
        fc.pErr = p->pErr;
        if( funcFind(e->zTok, e->pList?e->pList->nExpr:0)==0 ){
          if( strEq(e->zTok,"sqlite_offset")||strEq(e->zTok,"load_extension") ){
            errSetPos(p->pErr, e->start, "no such function: %s", e->zTok);
            return 1;
          }
          errSetPos(p->pErr, e->start, "no such function: %s", e->zTok);
          return 1;
        }
      }
      if( e->flags & EF_Agg ) e->aggKind = 1;
      return 0;
    }
    case TKX_SELECT: {
      return 0;
    }
    default:
      if( e->pLeft ) rc |= resolveExpr(p, e->pLeft, pScope);
      if( e->pRight ) rc |= resolveExpr(p, e->pRight, pScope);
      if( e->pList ){
        int i;
        for(i=0;i<e->pList->nExpr;i++) rc |= resolveExpr(p, e->pList->apExpr[i], pScope);
      }
      return rc;
  }
}
static int exprHasAgg(Eval *p, Expr *e){
  int r = 0;
  if( e==0 ) return 0;
  if( e->flags & EF_Agg ) return 1;
  r |= exprHasAgg(p, e->pLeft);
  r |= exprHasAgg(p, e->pRight);
  if( e->pList ){ int i; for(i=0;i<e->pList->nExpr;i++) r |= exprHasAgg(p, e->pList->apExpr[i]); }
  return r;
}
EEOF
gcc -c -O1 -o exec.o exec.c -Wall -I. 2>&1|grep error|head; echo rc=$?"}

{"command": "cd /workspace/src && python3 - <<'PY'
h=open('exec.h').read()
h=h.replace("struct Eval {","struct Eval {\n  void *pCur;")
open('exec.h','w').write(h)
PY
cat >> exec.c <<'EEOF'

/* ============ expression evaluation ============ */
static int likeCI(unsigned char a, unsigned char b){
  if( a>='A' && a<='Z' ) a += 32;
  if( b>='A' && b<='Z' ) b += 32;
  return a==b;
}
static int valueToNumber(Value *p, Arena *pA, i64 *pi, double *pr, int *pbReal){
  *pbReal = 0;
  switch( p->type ){
    case VT_INT: *pi = p->i; return 1;
    case VT_REAL: *pr = p->r; *pbReal = 1; return 1;
    case VT_NULL: return 0;
    default: {
      const char *z = valText(pA, p);
      if( isNumericText(z) ){
        const char *q = z;
        int alldig = 1;
        int neg = 0;
        while( *q==' '||*q=='\t'||*q=='\n'||*q=='\r'||*q=='\f' ) q++;
        if( *q=='+'||*q=='-' ){ neg = (*q=='-'); q++; }
        { const char *r2 = q; while( *r2 ){ if( *r2=='.'||*r2=='e'||*r2=='E' ){ alldig=0; break; } r2++; } }
        if( alldig ){ *pi = neg ? -strtoll(q,0,10) : strtoll(q,0,10); return 1; }
        *pr = textToReal(z); *pbReal = 1; return 1;
      }
      *pi = 0; *pr = 0.0;
      return 1;
    }
  }
}
static int valueToNumberReal(Value *p, Arena *pA, double *pr){
  switch( p->type ){
    case VT_INT: *pr = (double)p->i; return 1;
    case VT_REAL: *pr = p->r; return 1;
    case VT_NULL: return 0;
    default: *pr = textToReal(valText(pA,p)); return 1;
  }
}
static void numericBinop(Eval *p, int op, Value *a, Value *b, Value *o){
  i64 x, y;
  double dx, dy;
  int bx, by;
  if( a->type==VT_NULL || b->type==VT_NULL ){ valSetNull(o); return; }
  if( !valueToNumber(a,p->pA,&x,&dx,&bx) ){ valSetNull(o); return; }
  if( !valueToNumber(b,p->pA,&y,&dy,&by) ){ valSetNull(o); return; }
  if( op==TKX_DIV && y==0 && !by ){ valSetNull(o); return; }
  if( op==TKX_MOD && y==0 && !by ){ valSetNull(o); return; }
  if( !bx && !by ){
    switch( op ){
      case TKX_ADD: {
        i64 v = x + y;
        if( ((x>0&&y>0&&v<0)||(x<0&&y<0&&v>0)) ){ valSetReal(p->pA,o,(double)x+(double)y); return; }
        valSetInt(p->pA,o,v); return;
      }
      case TKX_SUB: {
        i64 v = x - y;
        if( ((x>0&&y<0&&v<0)||(x<0&&y>0&&v>0)) ){ valSetReal(p->pA,o,(double)x-(double)y); return; }
        valSetInt(p->pA,o,v); return;
      }
      case TKX_MUL: {
        i64 v = x * y;
        if( x!=0 && v/x!=y ){ valSetReal(p->pA,o,(double)x*(double)y); return; }
        valSetInt(p->pA,o,v); return;
      }
      case TKX_DIV: valSetInt(p->pA,o, x/y); return;
      case TKX_MOD: valSetInt(p->pA,o, x%y); return;
    }
  }
  if( !bx ) dx = (double)x;
  if( !by ) dy = (double)y;
  switch( op ){
    case TKX_ADD: valSetReal(p->pA,o,dx+dy); break;
    case TKX_SUB: valSetReal(p->pA,o,dx-dy); break;
    case TKX_MUL: valSetReal(p->pA,o,dx*dy); break;
    case TKX_DIV: valSetReal(p->pA,o,dy==0.0?0.0/0.0:dx/dy); break;
    case TKX_MOD: valSetReal(p->pA,o,dy==0.0?0.0/0.0:fmod(dx,dy)); break;
    default: valSetNull(o); break;
  }
}
static void intBinop(Eval *p, int op, Value *a, Value *b, Value *o){
  i64 x, y;
  double dx, dy;
  int bx, by;
  if( a->type==VT_NULL || b->type==VT_NULL ){ valSetNull(o); return; }
  if( !valueToNumber(a,p->pA,&x,&dx,&bx) ){ valSetNull(o); return; }
  if( !valueToNumber(b,p->pA,&y,&dy,&by) ){ valSetNull(o); return; }
  if( !bx ) x = (i64)dx;
  if( !by ) y = (i64)dy;
  switch( op ){
    case TKX_BITAND: valSetInt(p->pA,o,x&y); break;
    case TKX_BITOR: valSetInt(p->pA,o,x|y); break;
    case TKX_LSHIFT: {
      if( y>=64 || y<=-64 ) valSetInt(p->pA,o,0);
      else if( y>=0 ) valSetInt(p->pA,o,(i64)((u64)x<<y));
      else valSetInt(p->pA,o,(i64)((u64)x>>(-y)));
      break;
    }
    case TKX_RSHIFT: {
      if( y>=64 || y<=-64 ) valSetInt(p->pA,o, x<0?-1:0);
      else if( y>=0 ) valSetInt(p->pA,o,x>>y);
      else valSetInt(p->pA,o,(i64)((u64)x<<(-y)));
      break;
    }
    default: valSetNull(o); break;
  }
}
/* compare two values applying affinity of a column operand */
static int compareVals(Eval *p, Expr *ea, Value *a, Expr *eb, Value *b){
  Value ta, tb;
  int affA = -1, affB = -1;
  int c;
  if( ea && ea->op==TKX_COLUMN && p->pScope ){
    Scope *s = p->pScope;
    if( ea->iSrc>=0 && ea->iSrc<s->nSrc && s->a[ea->iSrc].pTab ){
      affA = s->a[ea->iSrc].pTab->aCol[ea->iCol>=0?ea->iCol:0].affinity;
    }
  }
  if( eb && eb->op==TKX_COLUMN && p->pScope ){
    Scope *s = p->pScope;
    if( eb->iSrc>=0 && eb->iSrc<s->nSrc && s->a[eb->iSrc].pTab ){
      affB = s->a[eb->iSrc].pTab->aCol[eb->iCol>=0?eb->iCol:0].affinity;
    }
  }
  valInit(&ta); valInit(&tb);
  valCopy(p->pA,&ta,a);
  valCopy(p->pA,&tb,b);
  if( affA>=0 && ta.type==VT_TEXT && tb.type!=VT_TEXT ) applyAffinity(&ta,affA);
  if( affB>=0 && tb.type==VT_TEXT && ta.type!=VT_TEXT ) applyAffinity(&tb,affB);
  if( ta.type==VT_TEXT && tb.type==VT_TEXT && affA==AF_BLOB && affB!=AF_BLOB ) applyAffinity(&tb,AF_TEXT);
  if( tb.type==VT_TEXT && ta.type==VT_TEXT && affB==AF_BLOB && affA!=AF_BLOB ) applyAffinity(&ta,AF_TEXT);
  c = valCmp(&ta,&tb);
  return c;
}
