/* evaluate a subquery; returns a RowBuf */
static RowBuf *evalSubquery(Eval *p, Select *s, Scope *pScope, int *pnCol, char ***pazCol){
  Out o;
  RowBuf *rb = arenaAlloc(p->pA, sizeof(RowBuf));
  Eval sub;
  char **azCol = 0;
  int nCol = 0;
