  sub.iDepth = p->iDepth+1;
  sub.pScope = pScope;
  sub.pCur = 0;
  sub.pAggRows = 0;
  if( sub.iDepth>100 ){ errSet(p->pErr,"too many levels of query nesting"); return rb; }
  {
    extern int selRun(Eval *p, Select *s, Out *pOut, Scope *pOuter);
    selRun(&sub, s, &o, pScope);
