            c2.aiRowid = arenaAlloc(p->pA, (pScope->nSrc)*sizeof(i64));
            for(i=0;i<pScope->nSrc;i++){
              c2.apRow[i] = (i==0)? rows->ap[k] : (saveRow?saveRow:0);
              c2.aiRowid[i] = (i==0)? rows->aiRowid[k] : saveId;
            }
            if( nArg==0 && e->pList && e->pList->nExpr==1 && e->pList->apExpr[0]->op==TKX_STAR ){
              aggStep(&acc, p->pA, &tmp, 0, 1);
            }else{
              int j;
              Value a2[8];
              for(j=0;j<nArg && j<8;j++){ valInit(&a2[j]); evalExprIn(p,e->pList->apExpr[j],pScope,(CurRow*)&c2,&a2[j]); }
              aggStep(&acc, p->pA, a2, nArg, 0);
              for(j=0;j<nArg && j<8;j++) valFree(&a2[j]);
            }
          }
          (void)saveRow; (void)saveId;
        }
        aggFinal(&acc,p->pA,o);
        break;
      }
      aArg = arenaAlloc(p->pA, (nArg>0?nArg:1)*sizeof(Value));
      for(i=0;i<nArg;i++) valInit(&aArg[i]);
      for(i=0;i<nArg;i++) evalExprIn(p,e->pList->apExpr[i],pScope,pCur,&aArg[i]);
      memset(&fc,0,sizeof(fc));
      fc.pA = p->pA;
      fc.pErr = p->pErr;
      fc.pDb = p->pDb;
      fc.pEv = p;
      valSetNull(o);
      if( !funcCall(&fc, e->zTok, aArg, nArg, o) ){
        errSetPos(p->pErr, e->start, "no such function: %s", e->zTok);
      }
      break;
    }
    default:
      valSetNull(o);
      break;
  }
  *p = save;
}
void evalExpr(Eval *p, Expr *e, Value *o){
  evalExprIn(p, e, p->pScope, (CurRow*)p->pCur, o);
}
