static Value *curCol(Eval *p, int iSrc, int iCol){
  CurRow *cur = (CurRow*)p->pCur;
  Scope *s = p->pScope;
  if( cur==0 || s==0 ) return 0;
  if( iSrc<0 || iSrc>=s->nSrc ) return 0;
  if( cur->apRow[iSrc]==0 ) return 0;
  if( iCol<0 ) return 0;
  return cur->apRow[iSrc] + iCol;
}
static i64 curRowid(Eval *p, int iSrc){
  CurRow *cur = (CurRow*)p->pCur;
  Scope *s = p->pScope;
  if( cur==0 || s==0 ) return 0;
  if( iSrc<0 || iSrc>=s->nSrc ) return 0;
  if( cur->apRow[iSrc]==0 ) return 0;
  return cur->aiRowid[iSrc];
}

static void evalExprIn(Eval *p, Expr *e, Scope *pScope, CurRow *pCur, Value *o);

/* evaluate a subquery; returns a RowBuf */
static RowBuf *evalSubquery(Eval *p, Select *s, Scope *pScope, int *pnCol, char ***pazCol){
  Out o;
  RowBuf *rb = arenaAlloc(p->pA, sizeof(RowBuf));
  Eval sub;
  char **azCol = 0;
  int nCol = 0;
  memset(&o,0,sizeof(o));
  rowbufInit(rb, p->pA, 1);
  o.pArg = rb;
  o.pOut = p->pOut;
  sub = *p;
  sub.iDepth = p->iDepth+1;
  sub.pScope = pScope;
  sub.pCur = 0;
  sub.pAggRows = 0;
  if( sub.iDepth>100 ){ errSet(p->pErr,"too many levels of query nesting"); return rb; }
  {
    extern int selRun(Eval *p, Select *s, Out *pOut, Scope *pOuter);
    selRun(&sub, s, &o, pScope);
  }
  nCol = ((RowBuf*)o.pArg)->nCol;
  *pnCol = nCol;
  if( pazCol ){
    azCol = arenaAlloc(p->pA, (nCol>0?nCol:1)*sizeof(char*));
    {
      int i;
      for(i=0;i<nCol;i++) azCol[i] = 0;
    }
    *pazCol = azCol;
  }
  return rb;
}

static void evalExprIn(Eval *p, Expr *e, Scope *pScope, CurRow *pCur, Value *o){
  Eval save;
  if( e==0 ){ valSetNull(o); return; }
  save = *p;
  p->pScope = pScope;
  p->pCur = (void*)pCur;
  switch( e->op ){
    case TKX_INT: valSetInt(p->pA,o,e->v.i); break;
    case TKX_REAL: valSetReal(p->pA,o,e->v.r); break;
    case TKX_TEXT: valCopy(p->pA,o,&e->v); break;
    case TKX_BLOB: valCopy(p->pA,o,&e->v); break;
    case TKX_NULL: valSetNull(o); break;
    case TKX_TRUE: valSetInt(p->pA,o,1); break;
    case TKX_FALSE: valSetInt(p->pA,o,0); break;
    case TKX_CURRENT_DATE: case TKX_CURRENT_TIME: case TKX_CURRENT_TIMESTAMP: {
      double jd;
      int ok;
      parseDateTime("now",&jd,&ok);
      if( e->op==TKX_CURRENT_DATE ){
        int Y,M,D; char buf[32];
        ymdFromJd(jd,&Y,&M,&D);
        snprintf(buf,sizeof(buf),"%04d-%02d-%02d",Y,M,D);
        valSetText(p->pA,o,buf);
      }else if( e->op==TKX_CURRENT_TIME ){
        double frac = jd+0.5; int s = (int)((frac-floor(frac))*86400.0+0.0000005);
        char buf[32];
        snprintf(buf,sizeof(buf),"%02d:%02d:%02d",s/3600,(s%3600)/60,s%60);
        valSetText(p->pA,o,buf);
      }else formatDateTime(jd,0,p->pA,o);
      break;
    }
    case TKX_COLUMN: {
      Value *v = curCol(p, e->iSrc, e->iCol);
      if( v==0 ){ valSetNull(o); break; }
      valCopy(p->pA,o,v);
      break;
    }
    case TKX_ROWID: valSetInt(p->pA,o,curRowid(p,e->iSrc)); break;
    case TKX_VARIABLE: {
      int i;
      Param *pp = p->pParam;
      valSetNull(o);
      if( pp==0 ) break;
      for(i=0;i<pp->n;i++){
        if( pp->azName[i] && strEq(pp->azName[i], e->zTok) ){ valCopy(p->pA,o,&pp->apVal[i]); break; }
      }
      break;
    }
    case TKX_NEG: {
      Value t;
      valInit(&t);
      evalExprIn(p,e->pLeft,pScope,pCur,&t);
      if( t.type==VT_NULL ) valSetNull(o);
      else if( t.type==VT_INT ) valSetInt(p->pA,o,-t.i);
      else if( t.type==VT_REAL ) valSetReal(p->pA,o,-t.r);
      else {
        double d;
        if( valueToNumberReal(&t,p->pA,&d) && isNumericText(valText(p->pA,&t)) ) valSetReal(p->pA,o,-d);
        else valSetInt(p->pA,o,0);
      }
      break;
    }
    case TKX_UMPL: evalExprIn(p,e->pLeft,pScope,pCur,o); break;
    case TKX_BITNOT: {
      Value t;
      valInit(&t);
      evalExprIn(p,e->pLeft,pScope,pCur,&t);
      if( t.type==VT_NULL ) valSetNull(o);
      else {
        i64 x; double d; int br;
        if( valueToNumber(&t,p->pA,&x,&d,&br) ){ if( br ) x = (i64)d; valSetInt(p->pA,o,~x); }
        else valSetInt(p->pA,o,0);
      }
      break;
    }
    case TKX_NOT: {
      Value t;
      valInit(&t);
      evalExprIn(p,e->pLeft,pScope,pCur,&t);
      if( t.type==VT_NULL ) valSetNull(o);
      else valSetInt(p->pA,o, evalIsTrue(&t)?0:1);
      break;
    }
    case TKX_AND: case TKX_OR: {
      Value a, b;
      int ta = -1, tb = -1;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type!=VT_NULL ) ta = evalIsTrue(&a)?1:0;
      if( b.type!=VT_NULL ) tb = evalIsTrue(&b)?1:0;
      if( e->op==TKX_AND ){
        if( ta==0 || tb==0 ) valSetInt(p->pA,o,0);
        else if( ta==1 && tb==1 ) valSetInt(p->pA,o,1);
        else valSetNull(o);
      }else{
        if( ta==1 || tb==1 ) valSetInt(p->pA,o,1);
        else if( ta==0 && tb==0 ) valSetInt(p->pA,o,0);
        else valSetNull(o);
      }
      break;
    }
    case TKX_ADD: case TKX_SUB: case TKX_MUL: case TKX_DIV: case TKX_MOD: {
      Value a,b;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      numericBinop(p,e->op,&a,&b,o);
      break;
    }
    case TKX_BITAND: case TKX_BITOR: case TKX_LSHIFT: case TKX_RSHIFT: {
      Value a,b;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      intBinop(p,e->op,&a,&b,o);
      break;
    }
    case TKX_CONCAT: {
      Value a,b;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type==VT_NULL || b.type==VT_NULL ){ valSetNull(o); break; }
      {
        const char *za = valText(p->pA,&a);
        const char *zb = valText(p->pA,&b);
        char *z = arenaAlloc(p->pA, strlen(za)+strlen(zb)+1);
        strcpy(z, za);
        strcat(z, zb);
        valSetText(p->pA,o,z);
      }
      break;
    }
    case TKX_ISNULL: case TKX_NOTNULL: {
      Value a;
      valInit(&a);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      if( e->op==TKX_ISNULL ) valSetInt(p->pA,o, a.type==VT_NULL?1:0);
      else valSetInt(p->pA,o, a.type==VT_NULL?0:1);
      break;
    }
    case TKX_EQ: case TKX_NE: case TKX_LT: case TKX_LE: case TKX_GT: case TKX_GE: {
      Value a,b;
      int c;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type==VT_NULL || b.type==VT_NULL ){ valSetNull(o); break; }
      c = compareVals(p,e->pLeft,&a,e->pRight,&b);
      switch( e->op ){
        case TKX_EQ: valSetInt(p->pA,o,c==0); break;
        case TKX_NE: valSetInt(p->pA,o,c!=0); break;
        case TKX_LT: valSetInt(p->pA,o,c<0); break;
        case TKX_LE: valSetInt(p->pA,o,c<=0); break;
        case TKX_GT: valSetInt(p->pA,o,c>0); break;
        default: valSetInt(p->pA,o,c>=0); break;
      }
      break;
    }
    case TKX_IS: case TKX_ISNOT: {
      Value a,b;
      int eq;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type==VT_NULL && b.type==VT_NULL ) eq = 1;
      else if( a.type==VT_NULL || b.type==VT_NULL ) eq = 0;
      else eq = (compareVals(p,e->pLeft,&a,e->pRight,&b)==0);
      valSetInt(p->pA,o, e->op==TKX_IS ? eq : !eq);
      break;
    }
    case TKX_BETWEEN: case TKX_NOTBETWEEN: {
      Value a, lo, hi;
      int c1, c2, r;
      valInit(&a); valInit(&lo); valInit(&hi);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pList->apExpr[0],pScope,pCur,&lo);
      evalExprIn(p,e->pList->apExpr[1],pScope,pCur,&hi);
      if( a.type==VT_NULL || lo.type==VT_NULL || hi.type==VT_NULL ){ valSetNull(o); break; }
      c1 = compareVals(p,0,&a,0,&lo);
      c2 = compareVals(p,0,&a,0,&hi);
      r = (c1>=0 && c2<=0);
      valSetInt(p->pA,o, e->op==TKX_BETWEEN ? r : !r);
      break;
    }
    case TKX_IN: case TKX_NOTIN: {
      Value a;
      int found = 0, hasNull = 0, nList = 0;
      valInit(&a);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      if( e->pList ){
        int i;
        nList = e->pList->nExpr;
        for(i=0;i<nList;i++){
          Value v;
          valInit(&v);
          evalExprIn(p,e->pList->apExpr[i],pScope,pCur,&v);
          if( v.type==VT_NULL ){ hasNull = 1; continue; }
          if( a.type!=VT_NULL && compareVals(p,0,&a,0,&v)==0 ) found = 1;
        }
      }else if( e->pSelect ){
        int nCol;
        char **az;
        RowBuf *rb = evalSubquery(p, e->pSelect, pScope, &nCol, &az);
        int i;
        nList = rb->n;
        for(i=0;i<rb->n;i++){
          Value *v = rb->ap[i];
          if( v[0].type==VT_NULL ){ hasNull = 1; continue; }
          if( a.type!=VT_NULL && compareVals(p,0,&a,0,&v[0])==0 ){ found = 1; break; }
        }
      }else if( e->zTok ){
        Table *t = dbFindTable(p->pDb, e->zTok, 0, 0);
        int i;
        if( t ){
          nList = t->nRow;
          for(i=0;i<t->nRow;i++){
            Value *v = t->apRow[i]->aVal;
            if( v[0].type==VT_NULL ){ hasNull=1; continue; }
            if( a.type!=VT_NULL && compareVals(p,0,&a,0,&v[0])==0 ){ found=1; break; }
          }
        }
      }
      if( a.type==VT_NULL ){ valSetNull(o); break; }
      if( found ) valSetInt(p->pA,o, e->op==TKX_IN?1:0);
      else if( hasNull ) valSetNull(o);
      else valSetInt(p->pA,o, e->op==TKX_IN?0:1);
      break;
    }
    case TKX_LIKE: case TKX_GLOB: case TKX_REGEXP: case TKX_MATCH: {
      Value a, pat, esc;
      int r = 0;
      valInit(&a); valInit(&pat); valInit(&esc);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      if( e->pList->nExpr>0 ) evalExprIn(p,e->pList->apExpr[0],pScope,pCur,&pat);
      if( e->pList->nExpr>1 ) evalExprIn(p,e->pList->apExpr[1],pScope,pCur,&esc);
      if( a.type==VT_NULL || pat.type==VT_NULL ){ valSetNull(o); break; }
      if( e->op==TKX_LIKE ){
        const char *zp = valText(p->pA,&pat);
        const char *zs = valText(p->pA,&a);
        r = likeMatch(zp,(int)strlen(zp),zs,(int)strlen(zs),
                      e->pList->nExpr>1&&esc.type!=VT_NULL ? (unsigned char)valText(p->pA,&esc)[0] : 0);
      }else if( e->op==TKX_GLOB ){
        const char *zp = valText(p->pA,&pat);
        const char *zs = valText(p->pA,&a);
        r = globMatch(zp,(int)strlen(zp),zs,(int)strlen(zs));
      }else r = 0;
      if( e->flags & 0x200 ) r = !r;
      valSetInt(p->pA,o,r);
      break;
    }
    case TKX_CASE: {
      Value test;
      int i;
      valInit(&test);
      if( e->pLeft ) evalExprIn(p,e->pLeft,pScope,pCur,&test);
      for(i=0;i+1<e->pList->nExpr;i+=2){
        Value w;
        int hit;
        valInit(&w);
        evalExprIn(p,e->pList->apExpr[i],pScope,pCur,&w);
        if( e->pLeft ) hit = (test.type!=VT_NULL && w.type!=VT_NULL && compareVals(p,0,&test,0,&w)==0);
        else hit = evalIsTrue(&w);
        if( hit ){ evalExprIn(p,e->pList->apExpr[i+1],pScope,pCur,o); return; }
      }
      if( e->pRight ) evalExprIn(p,e->pRight,pScope,pCur,o);
      else valSetNull(o);
      break;
    }
    case TKX_CAST: {
      Value a;
      int aff;
      valInit(&a);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      aff = affinityOf(e->zTok);
      valCopy(p->pA,o,&a);
      applyAffinity(o,aff);
      if( aff==AF_INT && o->type==VT_REAL ){
        if( o->r!=o->r || o->r>9223372036854775807.0 || o->r<-9223372036854775808.0 ){
          valSetInt(p->pA,o, o->r>0 ? (i64)9223372036854775807LL : (i64)(-9223372036854775807LL-1));
        }else valSetInt(p->pA,o,(i64)o->r);
      }
      if( aff==AF_TEXT && o->type!=VT_TEXT && o->type!=VT_NULL ){
        valSetText(p->pA,o,valText(p->pA,o));
      }
      if( aff==AF_REAL && o->type==VT_INT ){ valSetReal(p->pA,o,(double)o->i); }
      if( aff==AF_BLOB && o->type==VT_TEXT ){
        valSetBlob(p->pA,o,o->z,o->n);
      }
      if( aff==AF_NUMERIC && o->type==VT_TEXT ) applyAffinity(o,AF_NUMERIC);
      break;
    }
    case TKX_COLLATE: evalExprIn(p,e->pLeft,pScope,pCur,o); break;
    case TKX_EXISTS: {
      int nCol; char **az;
      RowBuf *rb = evalSubquery(p,e->pSelect,pScope,&nCol,&az);
      valSetInt(p->pA,o, rb->n>0 ? 1 : 0);
      break;
    }
    case TKX_SELECT: {
      int nCol; char **az;
      RowBuf *rb = evalSubquery(p,e->pSelect,pScope,&nCol,&az);
      if( rb->n>0 ) valCopy(p->pA,o,rb->ap[0]);
      else valSetNull(o);
      break;
    }
    case TKX_ARROW: case TKX_DOUBLEARROW: {
      Value a, b;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type==VT_NULL || b.type==VT_NULL ){ valSetNull(o); break; }
      jsonExtract(p->pA, valText(p->pA,&a), (int)strlen(valText(p->pA,&a)), valText(p->pA,&b), o,
                  e->op==TKX_DOUBLEARROW);
      break;
    }
    case TKX_RAISE: valSetNull(o); break;
    case TKX_FUNCTION: {
      Value *aArg;
      int nArg = e->pList ? e->pList->nExpr : 0;
      int i;
      FuncCtx fc;
      if( e->flags & EF_Agg ){
        /* aggregate over the current group */
        AggAcc acc;
        memset(&acc,0,sizeof(acc));
        valInit(o);
        acc.bInt = 1;
        {
          const char *zn = e->zTok;
          if( strEq(zn,"count") ) acc.kind = 0;
          else if( strEq(zn,"sum") ) acc.kind = 1;
          else if( strEq(zn,"total") ) acc.kind = 2;
          else if( strEq(zn,"avg") ) acc.kind = 3;
          else if( strEq(zn,"min") ) acc.kind = 4;
          else if( strEq(zn,"max") ) acc.kind = 5;
          else if( strEq(zn,"group_concat") ) acc.kind = 6;
          else if( strEq(zn,"string_agg") ) acc.kind = 7;
          else if( strEq(zn,"json_group_array") ) acc.kind = 8;
          else if( strEq(zn,"json_group_object") ) acc.kind = 9;
          else acc.kind = 0;
        }
        {
          RowBuf *rows = p->pAggRows;
          CurRow c2;
          Value *saveRow;
          i64 saveId;
          int k;
          if( rows==0 ){ aggFinal(&acc,p->pA,o); break; }
          saveRow = pCur?pCur->apRow[pCur->iSrc]:0;
          saveId = pCur?pCur->aiRowid[pCur->iSrc]:0;
          for(k=0;k<rows->n;k++){
            Value tmp;
            valInit(&tmp);
            c2.apRow = arenaAlloc(p->pA, (pScope->nSrc)*sizeof(Value*));
            c2.aiRowid = arenaAlloc(p->pA, (pScope->nSrc)*sizeof(i64));
            for(i=0;i<pScope->nSrc;i++){
              c2.apRow[i] = (i==0)? rows->ap[k] : (saveRow?saveRow:0);
              c2.aiRowid[i] = (i==0)? rows->aiRowid[k] : saveId;
            }
            if( nArg==0 && e->pList && e->pList->nExpr==1 && e->pList->apExpr[0]->op==TKX_STAR ){
              aggStep(&acc, p->pA, &tmp, 0, 1);
            }else{
              int j;
              Value a2[8];
              for(j=0;j<nArg && j<8;j++){ valInit(&a2[j]); evalExprIn(p,e->pList->apExpr[j],pScope,(CurRow*)&c2,&a2[j]); }
              aggStep(&acc, p->pA, a2, nArg, 0);
              for(j=0;j<nArg && j<8;j++) valFree(&a2[j]);
            }
          }
          (void)saveRow; (void)saveId;
        }
        aggFinal(&acc,p->pA,o);
        break;
      }
      aArg = arenaAlloc(p->pA, (nArg>0?nArg:1)*sizeof(Value));
      for(i=0;i<nArg;i++) valInit(&aArg[i]);
      for(i=0;i<nArg;i++) evalExprIn(p,e->pList->apExpr[i],pScope,pCur,&aArg[i]);
      memset(&fc,0,sizeof(fc));
      fc.pA = p->pA;
      fc.pErr = p->pErr;
      fc.pDb = p->pDb;
      fc.pEv = p;
      valSetNull(o);
      if( !funcCall(&fc, e->zTok, aArg, nArg, o) ){
        errSetPos(p->pErr, e->start, "no such function: %s", e->zTok);
      }
      break;
    }
    default:
      valSetNull(o);
      break;
  }
  *p = save;
}
void evalExpr(Eval *p, Expr *e, Value *o){
  evalExprIn(p, e, p->pScope, (CurRow*)p->pCur, o);
}
