static i64 curRowid(Eval *p, int iSrc){
  CurRow *cur = (CurRow*)p->pCur;
  Scope *s = p->pScope;
  if( cur==0 || s==0 ) return 0;
  if( iSrc<0 || iSrc>=s->nSrc ) return 0;
  if( cur->apRow[iSrc]==0 ) return 0;
  return cur->aiRowid[iSrc];
}

static void evalExprIn(Eval *p, Expr *e, Scope *pScope, CurRow *pCur, Value *o);

/* evaluate a subquery; returns a RowBuf */
static RowBuf *evalSubquery(Eval *p, Select *s, Scope *pScope, int *pnCol, char ***pazCol){
  Out o;
  RowBuf *rb = arenaAlloc(p->pA, sizeof(RowBuf));
  Eval sub;
  char **azCol = 0;
  int nCol = 0;
  memset(&o,0,sizeof(o));
  rowbufInit(rb, p->pA, 1);
  o.pArg = rb;
  o.pOut = p->pOut;
  sub = *p;
  sub.iDepth = p->iDepth+1;
  sub.pScope = pScope;
  sub.pCur = 0;
  sub.pAggRows = 0;
  if( sub.iDepth>100 ){ errSet(p->pErr,"too many levels of query nesting"); return rb; }
  {
    extern int selRun(Eval *p, Select *s, Out *pOut, Scope *pOuter);
    selRun(&sub, s, &o, pScope);
  }
  nCol = ((RowBuf*)o.pArg)->nCol;
  *pnCol = nCol;
  if( pazCol ){
    azCol = arenaAlloc(p->pA, (nCol>0?nCol:1)*sizeof(char*));
    {
      int i;
      for(i=0;i<nCol;i++) azCol[i] = 0;
    }
    *pazCol = azCol;
  }
  return rb;
}

static void evalExprIn(Eval *p, Expr *e, Scope *pScope, CurRow *pCur, Value *o){
  Eval save;
  if( e==0 ){ valSetNull(o); return; }
  save = *p;
  p->pScope = pScope;
  p->pCur = (void*)pCur;
  switch( e->op ){
    case TKX_INT: valSetInt(p->pA,o,e->v.i); break;
    case TKX_REAL: valSetReal(p->pA,o,e->v.r); break;
    case TKX_TEXT: valCopy(p->pA,o,&e->v); break;
    case TKX_BLOB: valCopy(p->pA,o,&e->v); break;
    case TKX_NULL: valSetNull(o); break;
    case TKX_TRUE: valSetInt(p->pA,o,1); break;
    case TKX_FALSE: valSetInt(p->pA,o,0); break;
    case TKX_CURRENT_DATE: case TKX_CURRENT_TIME: case TKX_CURRENT_TIMESTAMP: {
