        ymdFromJd(jd,&Y,&M,&D);
        snprintf(buf,sizeof(buf),"%04d-%02d-%02d",Y,M,D);
        valSetText(p->pA,o,buf);
      }else if( e->op==TKX_CURRENT_TIME ){
        double frac = jd+0.5; int s = (int)((frac-floor(frac))*86400.0+0.0000005);
        char buf[32];
