      valCopy(p->pA,o,v);
      break;
    }
    case TKX_ROWID: valSetInt(p->pA,o,curRowid(p,e->iSrc)); break;
    case TKX_VARIABLE: {
      int i;
      Param *pp = p->pParam;
      valSetNull(o);
      if( pp==0 ) break;
      for(i=0;i<pp->n;i++){
        if( pp->azName[i] && strEq(pp->azName[i], e->zTok) ){ valCopy(p->pA,o,&pp->apVal[i]); break; }
      }
      break;
    }
    case TKX_NEG: {
      Value t;
      valInit(&t);
      evalExprIn(p,e->pLeft,pScope,pCur,&t);
      if( t.type==VT_NULL ) valSetNull(o);
      else if( t.type==VT_INT ) valSetInt(p->pA,o,-t.i);
      else if( t.type==VT_REAL ) valSetReal(p->pA,o,-t.r);
      else {
        double d;
        if( valueToNumberReal(&t,p->pA,&d) && isNumericText(valText(p->pA,&t)) ) valSetReal(p->pA,o,-d);
        else valSetInt(p->pA,o,0);
