      break;
    }
    case TKX_UMPL: evalExprIn(p,e->pLeft,pScope,pCur,o); break;
    case TKX_BITNOT: {
      Value t;
      valInit(&t);
      evalExprIn(p,e->pLeft,pScope,pCur,&t);
      if( t.type==VT_NULL ) valSetNull(o);
      else {
        i64 x; double d; int br;
        if( valueToNumber(&t,p->pA,&x,&d,&br) ){ if( br ) x = (i64)d; valSetInt(p->pA,o,~x); }
        else valSetInt(p->pA,o,0);
      }
      break;
    }
    case TKX_NOT: {
      Value t;
      valInit(&t);
      evalExprIn(p,e->pLeft,pScope,pCur,&t);
      if( t.type==VT_NULL ) valSetNull(o);
      else valSetInt(p->pA,o, evalIsTrue(&t)?0:1);
