    case TKX_AND: case TKX_OR: {
      Value a, b;
      int ta = -1, tb = -1;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type!=VT_NULL ) ta = evalIsTrue(&a)?1:0;
      if( b.type!=VT_NULL ) tb = evalIsTrue(&b)?1:0;
      if( e->op==TKX_AND ){
        if( ta==0 || tb==0 ) valSetInt(p->pA,o,0);
        else if( ta==1 && tb==1 ) valSetInt(p->pA,o,1);
        else valSetNull(o);
      }else{
        if( ta==1 || tb==1 ) valSetInt(p->pA,o,1);
        else if( ta==0 && tb==0 ) valSetInt(p->pA,o,0);
        else valSetNull(o);
