      break;
    }
    case TKX_ADD: case TKX_SUB: case TKX_MUL: case TKX_DIV: case TKX_MOD: {
      Value a,b;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      numericBinop(p,e->op,&a,&b,o);
      break;
    }
    case TKX_BITAND: case TKX_BITOR: case TKX_LSHIFT: case TKX_RSHIFT: {
      Value a,b;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
