    case TKX_CONCAT: {
      Value a,b;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type==VT_NULL || b.type==VT_NULL ){ valSetNull(o); break; }
      {
        const char *za = valText(p->pA,&a);
        const char *zb = valText(p->pA,&b);
        char *z = arenaAlloc(p->pA, strlen(za)+strlen(zb)+1);
