    }
    case TKX_EQ: case TKX_NE: case TKX_LT: case TKX_LE: case TKX_GT: case TKX_GE: {
      Value a,b;
      int c;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type==VT_NULL || b.type==VT_NULL ){ valSetNull(o); break; }
      c = compareVals(p,e->pLeft,&a,e->pRight,&b);
      switch( e->op ){
        case TKX_EQ: valSetInt(p->pA,o,c==0); break;
        case TKX_NE: valSetInt(p->pA,o,c!=0); break;
        case TKX_LT: valSetInt(p->pA,o,c<0); break;
        case TKX_LE: valSetInt(p->pA,o,c<=0); break;
        case TKX_GT: valSetInt(p->pA,o,c>0); break;
        default: valSetInt(p->pA,o,c>=0); break;
