      break;
    }
    case TKX_IS: case TKX_ISNOT: {
      Value a,b;
      int eq;
      valInit(&a); valInit(&b);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pRight,pScope,pCur,&b);
      if( a.type==VT_NULL && b.type==VT_NULL ) eq = 1;
      else if( a.type==VT_NULL || b.type==VT_NULL ) eq = 0;
      else eq = (compareVals(p,e->pLeft,&a,e->pRight,&b)==0);
      valSetInt(p->pA,o, e->op==TKX_IS ? eq : !eq);
