    }
    case TKX_BETWEEN: case TKX_NOTBETWEEN: {
      Value a, lo, hi;
      int c1, c2, r;
      valInit(&a); valInit(&lo); valInit(&hi);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      evalExprIn(p,e->pList->apExpr[0],pScope,pCur,&lo);
      evalExprIn(p,e->pList->apExpr[1],pScope,pCur,&hi);
      if( a.type==VT_NULL || lo.type==VT_NULL || hi.type==VT_NULL ){ valSetNull(o); break; }
      c1 = compareVals(p,0,&a,0,&lo);
      c2 = compareVals(p,0,&a,0,&hi);
      r = (c1>=0 && c2<=0);
      valSetInt(p->pA,o, e->op==TKX_BETWEEN ? r : !r);
      break;
    }
    case TKX_IN: case TKX_NOTIN: {
      Value a;
      int found = 0, hasNull = 0, nList = 0;
      valInit(&a);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      if( e->pList ){
        int i;
        nList = e->pList->nExpr;
        for(i=0;i<nList;i++){
          Value v;
          valInit(&v);
          evalExprIn(p,e->pList->apExpr[i],pScope,pCur,&v);
          if( v.type==VT_NULL ){ hasNull = 1; continue; }
          if( a.type!=VT_NULL && compareVals(p,0,&a,0,&v)==0 ) found = 1;
        }
      }else if( e->pSelect ){
        int nCol;
        char **az;
        RowBuf *rb = evalSubquery(p, e->pSelect, pScope, &nCol, &az);
        int i;
        nList = rb->n;
        for(i=0;i<rb->n;i++){
          Value *v = rb->ap[i];
          if( v[0].type==VT_NULL ){ hasNull = 1; continue; }
          if( a.type!=VT_NULL && compareVals(p,0,&a,0,&v[0])==0 ){ found = 1; break; }
        }
      }else if( e->zTok ){
        Table *t = dbFindTable(p->pDb, e->zTok, 0, 0);
        int i;
        if( t ){
          nList = t->nRow;
          for(i=0;i<t->nRow;i++){
            Value *v = t->apRow[i]->aVal;
            if( v[0].type==VT_NULL ){ hasNull=1; continue; }
            if( a.type!=VT_NULL && compareVals(p,0,&a,0,&v[0])==0 ){ found=1; break; }
          }
        }
      }
      if( a.type==VT_NULL ){ valSetNull(o); break; }
      if( found ) valSetInt(p->pA,o, e->op==TKX_IN?1:0);
      else if( hasNull ) valSetNull(o);
      else valSetInt(p->pA,o, e->op==TKX_IN?0:1);
