    case TKX_LIKE: case TKX_GLOB: case TKX_REGEXP: case TKX_MATCH: {
      Value a, pat, esc;
      int r = 0;
      valInit(&a); valInit(&pat); valInit(&esc);
      evalExprIn(p,e->pLeft,pScope,pCur,&a);
      if( e->pList->nExpr>0 ) evalExprIn(p,e->pList->apExpr[0],pScope,pCur,&pat);
      if( e->pList->nExpr>1 ) evalExprIn(p,e->pList->apExpr[1],pScope,pCur,&esc);
      if( a.type==VT_NULL || pat.type==VT_NULL ){ valSetNull(o); break; }
      if( e->op==TKX_LIKE ){
        const char *zp = valText(p->pA,&pat);
        const char *zs = valText(p->pA,&a);
        r = likeMatch(zp,(int)strlen(zp),zs,(int)strlen(zs),
                      e->pList->nExpr>1&&esc.type!=VT_NULL ? (unsigned char)valText(p->pA,&esc)[0] : 0);
      }else if( e->op==TKX_GLOB ){
        const char *zp = valText(p->pA,&pat);
        const char *zs = valText(p->pA,&a);
        r = globMatch(zp,(int)strlen(zp),zs,(int)strlen(zs));
