      for(i=0;i+1<e->pList->nExpr;i+=2){
        Value w;
        int hit;
        valInit(&w);
        evalExprIn(p,e->pList->apExpr[i],pScope,pCur,&w);
        if( e->pLeft ) hit = (test.type!=VT_NULL && w.type!=VT_NULL && compareVals(p,0,&test,0,&w)==0);
        else hit = evalIsTrue(&w);
        if( hit ){ evalExprIn(p,e->pList->apExpr[i+1],pScope,pCur,o); return; }
