        AggAcc acc;
        memset(&acc,0,sizeof(acc));
        valInit(o);
        acc.bInt = 1;
        {
          const char *zn = e->zTok;
          if( strEq(zn,"count") ) acc.kind = 0;
          else if( strEq(zn,"sum") ) acc.kind = 1;
          else if( strEq(zn,"total") ) acc.kind = 2;
          else if( strEq(zn,"avg") ) acc.kind = 3;
          else if( strEq(zn,"min") ) acc.kind = 4;
          else if( strEq(zn,"max") ) acc.kind = 5;
          else if( strEq(zn,"group_concat") ) acc.kind = 6;
          else if( strEq(zn,"string_agg") ) acc.kind = 7;
          else if( strEq(zn,"json_group_array") ) acc.kind = 8;
          else if( strEq(zn,"json_group_object") ) acc.kind = 9;
          else acc.kind = 0;
        }
        {
          RowBuf *rows = p->pAggRows;
          CurRow c2;
          Value *saveRow;
          i64 saveId;
          int k;
          if( rows==0 ){ aggFinal(&acc,p->pA,o); break; }
          saveRow = pCur?pCur->apRow[pCur->iSrc]:0;
          saveId = pCur?pCur->aiRowid[pCur->iSrc]:0;
          for(k=0;k<rows->n;k++){
            Value tmp;
            valInit(&tmp);
            c2.apRow = arenaAlloc(p->pA, (pScope->nSrc)*sizeof(Value*));
            c2.aiRowid = arenaAlloc(p->pA, (pScope->nSrc)*sizeof(i64));
            for(i=0;i<pScope->nSrc;i++){
              c2.apRow[i] = (i==0)? rows->ap[k] : (saveRow?saveRow:0);
              c2.aiRowid[i] = (i==0)? rows->aiRowid[k] : saveId;
            }
            if( nArg==0 && e->pList && e->pList->nExpr==1 && e->pList->apExpr[0]->op==TKX_STAR ){
              aggStep(&acc, p->pA, &tmp, 0, 1);
            }else{
              int j;
              Value a2[8];
              for(j=0;j<nArg && j<8;j++){ valInit(&a2[j]); evalExprIn(p,e->pList->apExpr[j],pScope,(CurRow*)&c2,&a2[j]); }
              aggStep(&acc, p->pA, a2, nArg, 0);
              for(j=0;j<nArg && j<8;j++) valFree(&a2[j]);
            }
          }
          (void)saveRow; (void)saveId;
        }
        aggFinal(&acc,p->pA,o);
        break;
      }
      aArg = arenaAlloc(p->pA, (nArg>0?nArg:1)*sizeof(Value));
      for(i=0;i<nArg;i++) valInit(&aArg[i]);
      for(i=0;i<nArg;i++) evalExprIn(p,e->pList->apExpr[i],pScope,pCur,&aArg[i]);
      memset(&fc,0,sizeof(fc));
      fc.pA = p->pA;
      fc.pErr = p->pErr;
      fc.pDb = p->pDb;
      fc.pEv = p;
      valSetNull(o);
      if( !funcCall(&fc, e->zTok, aArg, nArg, o) ){
        errSetPos(p->pErr, e->start, "no such function: %s", e->zTok);
      }
      break;
    }
    default:
      valSetNull(o);
      break;
  }
  *p = save;
}
void evalExpr(Eval *p, Expr *e, Value *o){
  evalExprIn(p, e, p->pScope, (CurRow*)p->pCur, o);
}
