/* ============ expression to text (for column names) ============ */
char *exprToText(Arena *pA, Expr *e){
  if( e==0 ) return arenaStrdup(pA,"");
  if( e->end>e->start && e->start>=0 ){
    /* need the source text; stored in zTok2 for some nodes; use global */
    extern const char *execSourceText(void);
    const char *z = execSourceText();
    if( z ) return arenaStrndup(pA, z+e->start, e->end-e->start);
  }
  return arenaStrdup(pA,"");
}

/* ============ CTE handling ============ */
typedef struct CteTab { char *zName; Table *pTab; } CteTab;
int selRun(Eval *p, Select *s, Out *pOut, Scope *pOuter);

static Table *cteFind(Eval *p, const char *zName){
  extern Table *cteLookup(Eval *p, const char *zName);
  return cteLookup(p, zName);
}

/* materialize the sources of a select into a scope */
static int buildScope(Eval *p, Select *s, Scope *pScope){
  SrcList *pSrc = s->pSrc;
  int i;
  if( pSrc==0 ) return 0;
  for(i=0;i<pSrc->nSrc;i++){
    SrcItem *it = &pSrc->a[i];
    Table *t;
    if( it->pSelect ){
      int nCol;
      char **azCol;
      RowBuf *rb;
      Out o;
      Eval sub;
      memset(&o,0,sizeof(o));
      rb = arenaAlloc(p->pA, sizeof(RowBuf));
      rowbufInit(rb, p->pA, 1);
      o.pArg = rb;
      sub = *p;
      sub.pCur = 0;
      sub.pScope = pScope;
      sub.iDepth = p->iDepth+1;
      if( sub.iDepth>100 ){ errSet(p->pErr,"too many levels of query nesting"); return 1; }
      if( selRun(&sub, it->pSelect, &o, pScope) ) return 1;
      nCol = rb->nCol;
      azCol = arenaAlloc(p->pA, (nCol>0?nCol:1)*sizeof(char*));
      {
        int k;
        for(k=0;k<nCol;k++) azCol[k] = 0;
      }
      scopeAddRows(pScope, it->zAlias?it->zAlias:0, rb, azCol, nCol, 0);
      pScope->a[pScope->nSrc-1].azNameBuf = 0;
    }else if( it->pSub ){
      /* nested source list */
      extern int matSrcGroup(Eval *p, SrcList *pSrc2, RowBuf *pOut2, char ***pazNames, int *pnNames);
      RowBuf *rb = arenaAlloc(p->pA, sizeof(RowBuf));
      char **az = 0;
      int nNames = 0;
      rowbufInit(rb, p->pA, 1);
      if( matSrcGroup(p, it->pSub, rb, &az, &nNames) ) return 1;
      scopeAddRows(pScope, it->zAlias?it->zAlias:0, rb, az, nNames, 0);
    }else{
      t = cteFind(p, it->zTab);
      if( t==0 ) t = dbFindTable(p->pDb, it->zTab, it->zDb, 0);
      if( t==0 ){
        errSetPos(p->pErr, s->startPos+it->iNameOff, "no such table: %s", it->zTab);
        return 1;
      }
      scopeAddTable(pScope, it->zAlias?it->zAlias:it->zTab, t);
    }
  }
  return 0;
}

/* join rows from all sources; calls the callback for each combination */
typedef int (*RowFn)(Eval *p, CurRow *pCur, void *pArg);
static int iterateJoin(Eval *p, Scope *pScope, RowFn xFn, void *pArg){
  SrcList *pSrc;
  int i;
  int nSrc;
  RowBuf **apRows;
  int *aiIdx;
  int *anRows;
  int total;
  Value *flat;
  i64 *aRid;
  CurRow cur;
  int done = 0;
  Select *s = (Select*)pArg;
  pSrc = s->pSrc;
  if( pSrc==0 ){
    /* no FROM: single empty row */
    cur.apFlat = 0;
    return xFn(p, &cur, pArg);
  }
  nSrc = pScope->nSrc;
  apRows = arenaAlloc(p->pA, nSrc*sizeof(RowBuf*));
  anRows = arenaAlloc(p->pA, nSrc*sizeof(int));
  aiIdx = arenaAlloc(p->pA, nSrc*sizeof(int));
  total = 0;
  for(i=0;i<nSrc;i++){
    SrcItem *it = &pSrc->a[i];
    if( pScope->a[i].pRows ) { apRows[i] = pScope->a[i].pRows; anRows[i] = pScope->a[i].pRows->n; }
    else if( pScope->a[i].pTab ){ apRows[i] = 0; anRows[i] = pScope->a[i].pTab->nRow; }
    else anRows[i] = 0;
    aiIdx[i] = 0;
  }
  flat = arenaAlloc(p->pA, (total+1)*sizeof(Value));
  cur.apFlat = flat;
  {
    int width = 0;
    for(i=0;i<nSrc;i++) width += pScope->a[i].nCol + (pScope->a[i].bRowid?1:0);
    flat = arenaAlloc(p->pA, (width>0?width:1)*sizeof(Value));
    for(i=0;i<width;i++) valInit(&flat[i]);
    cur.apFlat = flat;
  }
  for(;;){
    /* build the flat row */
    int w = 0;
    int ok = 1;
    for(i=0;i<nSrc;i++){
      int j;
      SrcItem *it = &pSrc->a[i];
      if( pScope->a[i].pTab ){
        Table *t = pScope->a[i].pTab;
        if( aiIdx[i]>=t->nRow ){ ok = 0; break; }
        {
          Row *r = t->apRow[aiIdx[i]];
          for(j=0;j<t->nCol;j++){ valInit(&flat[w+j]); valCopy(p->pA,&flat[w+j], r->aVal+j); }
          w += t->nCol;
          valInit(&flat[w]);
          valSetInt(p->pA,&flat[w], r->rowid);
          w++;
        }
      }else if( pScope->a[i].pRows ){
        RowBuf *rb = pScope->a[i].pRows;
        if( aiIdx[i]>=rb->n ){ ok = 0; break; }
        for(j=0;j<rb->nCol;j++){ valInit(&flat[w+j]); valCopy(p->pA,&flat[w+j], rb->ap[aiIdx[i]]+j); }
        w += rb->nCol;
      }else{ ok = 0; break; }
    }
    if( !ok ) break;
    /* check join constraints */
    for(i=0;i<nSrc;i++){
      SrcItem *it = &pSrc->a[i];
      if( it->pOn ){
        Value v;
