/* evaluate a select core into pOut; returns names via pazNames */
static int runCore(Eval *p, Select *s, RowBuf *pOut, char ***pazNames, Scope *pOuter){
  Scope *pScope;
  int i, nRes = 0;
  Expr **apRes;
  char **azName;
  int bAgg = 0;
  int bGroup = (s->pGroupBy && s->pGroupBy->nExpr>0);
  Grp *apGrp = 0;
  int nGrp = 0, capGrp = 0;
  RowBuf allRows;
  int bWindow = 0;
  int rc = 0;
  /* --- WITH --- */
  if( s->pWith ){
    extern int matWith(Eval *p, With *pWith);
    if( matWith(p, s->pWith) ) return 1;
  }
  pScope = scopeNew(p, pOuter);
  p->pScope = pScope;
  if( buildScope(p, s, pScope) ) return 1;
  /* --- expand result list --- */
  {
    ExprList *l = s->pEList;
    apRes = arenaAlloc(p->pA, 64*sizeof(Expr*));
    azName = arenaAlloc(p->pA, 64*sizeof(char*));
    nRes = 0;
    if( l==0 ) l = pxNone();
    for(i=0;i<l->nExpr;i++){
      Expr *e = l->apExpr[i];
      if( e->op==TKX_STAR ){
        int k, j;
        for(k=0;k<pScope->nSrc;k++){
          if( pScope->a[k].pRows && pScope->a[k].azCol ){
            for(j=0;j<pScope->a[k].nCol;j++){
              Expr *c = pxNewExpr(p,TKX_COLUMN);
              c->zTok = arenaStrdup(p->pA, pScope->a[k].azCol[j]);
              c->iSrc = k; c->iCol = j;
              c->start = -1; c->end = -1;
              apRes[nRes] = c;
              azName[nRes] = arenaStrdup(p->pA, pScope->a[k].azCol[j]);
              nRes++;
            }
          }else if( pScope->a[k].pTab ){
            Table *t = pScope->a[k].pTab;
            for(j=0;j<t->nCol;j++){
              Expr *c = pxNewExpr(p,TKX_COLUMN);
              c->zTok = arenaStrdup(p->pA, t->aCol[j].zName);
              c->iSrc = k; c->iCol = j;
              c->start = -1; c->end = -1;
              apRes[nRes] = c;
              azName[nRes] = arenaStrdup(p->pA, t->aCol[j].zName);
              nRes++;
            }
          }
        }
      }else if( e->op==TKX_STAR_TABLE ){
        int k, j;
        for(k=0;k<pScope->nSrc;k++){
          if( pScope->a[k].zAlias && strEq(pScope->a[k].zAlias, e->zTok) ){
            if( pScope->a[k].pTab ){
              Table *t = pScope->a[k].pTab;
              for(j=0;j<t->nCol;j++){
                Expr *c = pxNewExpr(p,TKX_COLUMN);
                c->zTok = arenaStrdup(p->pA, t->aCol[j].zName);
                c->iSrc = k; c->iCol = j;
                c->start=-1; c->end=-1;
                apRes[nRes] = c;
                azName[nRes] = arenaStrdup(p->pA, t->aCol[j].zName);
                nRes++;
              }
            }else if( pScope->a[k].azCol ){
              for(j=0;j<pScope->a[k].nCol;j++){
                Expr *c = pxNewExpr(p,TKX_COLUMN);
                c->zTok = arenaStrdup(p->pA, pScope->a[k].azCol[j]);
                c->iSrc=k; c->iCol=j;
                c->start=-1; c->end=-1;
                apRes[nRes] = c;
                azName[nRes] = arenaStrdup(p->pA, pScope->a[k].azCol[j]);
                nRes++;
              }
            }
            break;
          }
        }
        if( k>=pScope->nSrc ){
          errSetPos(p->pErr, e->start, "no such table: %s", e->zTok);
          return 1;
        }
      }else{
        if( resolveExpr(p, e, pScope) ) return 1;
        apRes[nRes] = e;
        if( l->azName && l->azName[i] ) azName[nRes] = l->azName[i];
        else {
          if( e->op==TKX_COLUMN ) azName[nRes] = arenaStrdup(p->pA, e->zTok);
          else if( e->op==TKX_ROWID ) azName[nRes] = arenaStrdup(p->pA,"rowid");
          else azName[nRes] = exprToText(p->pA, e);
        }
        nRes++;
      }
      if( nRes>2000 ){ errSet(p->pErr,"too many columns"); return 1; }
    }
  }
  for(i=0;i<nRes;i++) bAgg |= exprHasAgg(p, apRes[i]);
  if( s->pHaving ) bAgg = 1;
  rowbufInit(&allRows, p->pA, nRes);
  pOut->nCol = nRes;
  if( bGroup || bAgg ){
    /* group rows */
    int nKeys = bGroup ? s->pGroupBy->nExpr : 0;
    iterateJoin(p, pScope, s, &allRows);   /* dummy call to prime; real work below */
    {
      /* manual iteration to group */
      extern int joinGroup(Eval *p, Scope *pScope, Select *s, Expr **apRes, int nRes,
                           ExprList *pGroupBy, RowBuf *pOut, int *pbAny);
      if( joinGroup(p, pScope, s, apRes, nRes, s->pGroupBy, pOut, &rc) ) return 1;
    }
  }else{
    /* plain rows */
    extern int joinPlain(Eval *p, Scope *pScope, Select *s, Expr **apRes, int nRes, RowBuf *pOut);
    if( joinPlain(p, pScope, s, apRes, nRes, pOut) ) return 1;
  }
  /* WHERE with no aggregates handled inside joinPlain/joinGroup */
  *pazNames = azName;
  return 0;
}
