/* iterate the join calling xFn for each row passing the ON constraints */
static int iterateJoin(Eval *p, Scope *pScope, Select *s, int (*xFn)(Eval*,CurRow*,void*), void *pArg){
  int i, nSrc;
  int *aiIdx, *anRows;
  Value *flat;
  CurRow cur;
  int done = 0;
  if( s->pSrc==0 || pScope->nSrc==0 ){
    cur.apFlat = 0;
    cur.aiRowid = 0;
    return xFn(p, &cur, pArg);
  }
  nSrc = pScope->nSrc;
  anRows = arenaAlloc(p->pA, nSrc*sizeof(int));
  aiIdx = arenaAlloc(p->pA, nSrc*sizeof(int));
  {
    int width = 0;
    for(i=0;i<nSrc;i++) width += pScope->a[i].nCol + (pScope->a[i].bRowid?1:0);
    flat = arenaAlloc(p->pA, (width>0?width:1)*sizeof(Value));
    for(i=0;i<width;i++) valInit(&flat[i]);
    cur.apFlat = flat;
    cur.aiRowid = 0;
  }
  for(i=0;i<nSrc;i++){
    if( pScope->a[i].pTab ) anRows[i] = pScope->a[i].pTab->nRow;
    else if( pScope->a[i].pRows ) anRows[i] = pScope->a[i].pRows->n;
    else anRows[i] = 0;
    aiIdx[i] = 0;
  }
  for(;;){
    int w = 0, ok = 1;
    for(i=0;i<nSrc;i++){
      int j;
      if( pScope->a[i].pTab ){
        Table *t = pScope->a[i].pTab;
        if( aiIdx[i]>=t->nRow ){ ok=0; break; }
        {
          Row *r = t->apRow[aiIdx[i]];
          for(j=0;j<t->nCol;j++){ valInit(&flat[w+j]); valCopy(p->pA,&flat[w+j], r->aVal+j); }
          w += t->nCol;
          valInit(&flat[w]);
          valSetInt(p->pA,&flat[w], r->rowid);
          w++;
        }
      }else if( pScope->a[i].pRows ){
        RowBuf *rb = pScope->a[i].pRows;
        if( aiIdx[i]>=rb->n ){ ok=0; break; }
        for(j=0;j<rb->nCol;j++){ valInit(&flat[w+j]); valCopy(p->pA,&flat[w+j], rb->ap[aiIdx[i]]+j); }
        w += rb->nCol;
      }else{ ok=0; break; }
    }
    if( !ok ) break;
    for(i=0;i<nSrc;i++){
      SrcItem *it = &s->pSrc->a[i];
      if( it->pOn ){
        Value v;
        valInit(&v);
        evalExprIn(p, it->pOn, pScope, &cur, &v);
        if( !evalIsTrue(&v) ){ ok=0; break; }
      }
    }
    if( ok ){
      if( xFn(p,&cur,pArg) ) return 1;
    }
    for(i=nSrc-1;i>=0;i--){
      aiIdx[i]++;
      if( aiIdx[i]<anRows[i] ) break;
      aiIdx[i]=0;
      if( i==0 ) done=1;
    }
    if( done ) break;
  }
  return 0;
}

/* callback: filter with WHERE and append the flat row */
typedef struct FlatCtx {
  RowBuf *pOut;
  Expr *pWhere;
} FlatCtx;
static int flatFn(Eval *p, CurRow *cur, void *pArg){
  FlatCtx *fc = pArg;
  if( fc->pWhere ){
    Value v;
    valInit(&v);
    evalExprIn(p, fc->pWhere, p->pScope, cur, &v);
    if( !evalIsTrue(&v) ) return 0;
  }
  rowbufAppend(fc->pOut, cur->apFlat, 0);
  return 0;
}

/* callback: grouping */
typedef struct GrpCtx {
  ExprList *pGroupBy;
  Expr *pWhere;
  Grp *apGrp;
  int nGrp, capGrp;
} GrpCtx;
static int grpFn(Eval *p, CurRow *cur, void *pArg){
  GrpCtx *gc = pArg;
  Value aKey[32];
  int i;
  char *zKey = arenaStrdup(p->pA, "");
  int found = -1;
  if( gc->pWhere ){
    Value v;
    valInit(&v);
    evalExprIn(p, gc->pWhere, p->pScope, cur, &v);
    if( !evalIsTrue(&v) ) return 0;
  }
  for(i=0;i<gc->pGroupBy->nExpr;i++){
    valInit(&aKey[i]);
    evalExprIn(p, gc->pGroupBy->apExpr[i], p->pScope, cur, &aKey[i]);
  }
  for(i=0;i<nKeys;i++){
    char *zv = arenaStrdup(p->pA, valText(p->pA,&aKey[i]));
    char *t = arenaStrdup(p->pA, zKey);
    zKey = arenaRealloc(p->pA, t, strlen(t), strlen(t)+strlen(zv)+2);
    strcat(zKey, zv);
    strcat(zKey, "\x01");
  }
  for(i=0;i<gc->nGrp;i++){
    int j, ok = 1;
    for(j=0;j<gc->pGroupBy->nExpr;j++){
      if( valCmp(gc->apGrp[i].aKey+j, &aKey[j])!=0 ){ ok=0; break; }
    }
    if( ok ){ found = i; break; }
  }
  if( found<0 ){
    if( gc->nGrp>=gc->capGrp ){
      gc->capGrp = gc->capGrp?gc->capGrp*2:8;
      gc->apGrp = arenaRealloc(p->pA, gc->apGrp, gc->nGrp*sizeof(Grp), gc->capGrp*sizeof(Grp));
    }
    memset(&gc->apGrp[gc->nGrp],0,sizeof(Grp));
    gc->apGrp[gc->nGrp].aKey = arenaAlloc(p->pA, gc->pGroupBy->nExpr*sizeof(Value));
    for(i=0;i<gc->pGroupBy->nExpr;i++){ valInit(&gc->apGrp[gc->nGrp].aKey[i]); valCopy(p->pA,&gc->apGrp[gc->nGrp].aKey[i], &aKey[i]); }
    rowbufInit(&gc->apGrp[gc->nGrp].rows, p->pA, 0);
    found = gc->nGrp++;
  }
  rowbufAppend(&gc->apGrp[found].rows, cur->apFlat, 0);
  return 0;
}
