/* ============ result list expansion & core execution ============ */
static void expandStar(Eval *p, Scope *pScope, Expr **apRes, char **azName, int *pnRes,
                       Expr *e, int onlySrc){
  int k, j;
  for(k=0;k<pScope->nSrc;k++){
    if( onlySrc>=0 && k!=onlySrc ) continue;
    if( onlySrc<0 || (e->zTok && strEq(pScope->a[k].zAlias,e->zTok)) ){
      int nCol = pScope->a[k].nCol;
      for(j=0;j<nCol;j++){
        Expr *c = pxNewExpr(p,TKX_COLUMN);
        c->zTok = arenaStrdup(p->pA, pScope->a[k].azCol[j]);
        c->iSrc = k; c->iCol = j;
        c->start = -1; c->end = -1;
        apRes[*pnRes] = c;
        azName[*pnRes] = arenaStrdup(p->pA, pScope->a[k].azCol[j]);
        (*pnRes)++;
      }
      if( onlySrc>=0 ) return;
    }
  }
}

/* materialize a nested source group (parenthesized src list) */
int matSrcGroup(Eval *p, SrcList *pSrc, RowBuf *pOut, char ***pazNames, int *pnNames){
  /* treat as a select over the group */
  Select s;
  char **azNames;
  int nNames = 0;
  Expr **apRes;
  Scope *pScope;
  FlatCtx fc;
  memset(&s,0,sizeof(s));
  s.pSrc = pSrc;
  pScope = scopeNew(p, 0);
  p->pScope = pScope;
  if( buildScope(p, &s, pScope) ) return 1;
  apRes = arenaAlloc(p->pA, 512*sizeof(Expr*));
  azNames = arenaAlloc(p->pA, 512*sizeof(char*));
  expandStar(p, pScope, apRes, azNames, &nNames, 0, -1);
  rowbufInit(pOut, p->pA, nNames);
  fc.pOut = pOut;
  fc.pWhere = 0;
  iterateJoin(p, pScope, &s, flatFn, &fc);
  *pazNames = azNames;
  *pnNames = nNames;
  return 0;
}

/* resolve an ORDER BY / GROUP BY term into an expression to evaluate */
static Expr *resolveSortTerm(Eval *p, Expr *e, Expr **apRes, int nRes){
  if( e->op==TKX_INT ) return 0;         /* position */
  if( e->op==TKX_COLUMN && e->zTok2==0 ){
    int i;
    for(i=0;i<nRes;i++){
      if( apRes[i]->op==TKX_COLUMN && strEq(apRes[i]->zTok, e->zTok) ) return 0;
    }
  }
  return e;
}

static int sortCmp(Eval *p, RowBuf *rb, Value **apKey, int nKey, int *aiDesc, int *aiNulls, int a, int b){
  int i;
  for(i=0;i<nKey;i++){
    int c;
    Value *x = apKey[i] + (a?1:0);
    (void)x;
    c = valCmp(rb->ap[a]+0, rb->ap[b]+0);
    (void)c;
  }
  return 0;
}

/* evaluate the core of a select into pOut */
static int runCore(Eval *p, Select *s, RowBuf *pOut, char ***pazNames, Scope *pOuter){
  Scope *pScope;
  Expr **apRes;
  char **azName;
  int nRes = 0;
  int bAgg = 0, bGroup = 0;
  int rc = 0;
  if( s->pWith ){
    extern int matWith(Eval *p, With *pWith);
    if( matWith(p, s->pWith) ) return 1;
  }
  pScope = scopeNew(p, pOuter);
  p->pScope = pScope;
  if( buildScope(p, s, pScope) ) return 1;
  apRes = arenaAlloc(p->pA, 4096*sizeof(Expr*));
  azName = arenaAlloc(p->pA, 4096*sizeof(char*));
  {
    ExprList *l = s->pEList;
    int i;
    if( l==0 ){
      /* VALUES */
      l = s->pEList;
    }
    for(i=0;i<l->nExpr;i++){
      Expr *e = l->apExpr[i];
      if( e->op==TKX_STAR ){ expandStar(p,pScope,apRes,azName,&nRes,e,-1); }
      else if( e->op==TKX_STAR_TABLE ){
        int k;
        for(k=0;k<pScope->nSrc;k++) if( pScope->a[k].zAlias && strEq(pScope->a[k].zAlias,e->zTok) ) break;
        if( k>=pScope->nSrc ){ errSetPos(p->pErr,e->start,"no such table: %s",e->zTok); return 1; }
        expandStar(p,pScope,apRes,azName,&nRes,e,k);
      }else{
        if( resolveExpr(p,e,pScope) ) return 1;
        apRes[nRes] = e;
        if( l->azName && l->azName[i] ) azName[nRes] = l->azName[i];
        else if( e->op==TKX_COLUMN ) azName[nRes] = arenaStrdup(p->pA,e->zTok);
        else if( e->op==TKX_ROWID ) azName[nRes] = arenaStrdup(p->pA,"rowid");
        else if( e->op==TKX_VALUELIST ){
          /* VALUES row */
          ExprList *row = e->pList;
          int j;
          Expr **ap2 = arenaAlloc(p->pA, (row->nExpr>0?row->nExpr:1)*sizeof(Expr*));
          char **az2 = arenaAlloc(p->pA, (row->nExpr>0?row->nExpr:1)*sizeof(char*));
          int n2 = 0;
          for(j=0;j<row->nExpr;j++){
            ap2[n2] = row->apExpr[j];
            az2[n2] = arenaStrdup(p->pA,"column1");
            n2++;
          }
          rowbufInit(pOut,p->pA,n2);
          {
            int r, c;
            Value *arow = arenaAlloc(p->pA, n2*sizeof(Value));
            for(c=0;c<n2;c++) valInit(&arow[c]);
            for(c=0;c<n2;c++) evalExprIn(p,ap2[c],pScope,0,&arow[c]);
            rowbufAppend(pOut,arow,0);
          }
          *pazNames = az2;
          return 0;
        }
        else azName[nRes] = exprToText(p->pA,e);
        nRes++;
      }
    }
  }
  rowbufInit(pOut, p->pA, nRes);
  for(i=0;i<nRes;i++) bAgg |= exprHasAgg(p, apRes[i]);
  bGroup = (s->pGroupBy && s->pGroupBy->nExpr>0);
  if( s->pHaving ) bAgg = 1;
  if( bGroup || bAgg ){
    GrpCtx gc;
    int g;
    memset(&gc,0,sizeof(gc));
    gc.pGroupBy = s->pGroupBy;
    gc.pWhere = s->pWhere;
    iterateJoin(p, pScope, s, grpFn, &gc);
    for(g=0;g<gc.nGrp;g++){
      CurRow cur;
      Value *arow = arenaAlloc(p->pA, (nRes>0?nRes:1)*sizeof(Value));
      int k;
      for(k=0;k<nRes;k++) valInit(&arow[k]);
      cur.apFlat = gc.apGrp[g].rows.n>0 ? gc.apGrp[g].rows.ap[0] : 0;
      cur.aiRowid = 0;
      p->pAggRows = &gc.apGrp[g].rows;
      p->pCur = (void*)&cur;
      p->pScope = pScope;
      if( s->pHaving ){
        Value v;
        valInit(&v);
        evalExprIn(p, s->pHaving, pScope, &cur, &v);
        if( !evalIsTrue(&v) ) continue;
      }
      for(k=0;k<nRes;k++) evalExprIn(p,apRes[k],pScope,&cur,&arow[k]);
      rowbufAppend(pOut,arow,0);
    }
    p->pAggRows = 0;
  }else{
    FlatCtx fc;
    fc.pOut = pOut;
    fc.pWhere = s->pWhere;
    iterateJoin(p, pScope, s, flatFn, &fc);
  }
  /* window functions */
  {
    int k;
    for(k=0;k<nRes;k++) if( apRes[k]->flags & EF_Window ) bWindow = 1;
  }
  if( bWindow ){
    extern void runWindow(Eval *p, RowBuf *pOut, Expr **apRes, int nRes, Scope *pScope);
    runWindow(p, pOut, apRes, nRes, pScope);
  }
  /* DISTINCT */
  if( s->isDistinct ){
    RowBuf tmp;
