/* sort helper */
static void sortRows(Eval *p, RowBuf *pOut, RowBuf *pKeys, ExprList *pOrderBy, int nRes){
  int n = pOut->n;
  int nk = pOrderBy ? pOrderBy->nExpr : 0;
  int *aiIdx = arenaAlloc(p->pA, (n>0?n:1)*sizeof(int));
  int i, j;
  /* fill in keys for integer-literal and alias terms */
  for(i=0;i<n;i++){
    for(j=0;j<nk;j++){
      Expr *e = pOrderBy->apExpr[j];
      Value *kv = pKeys->ap[i]+j;
      if( e->op==TKX_INT ){
        int c = (int)e->v.i - 1;
        valInit(kv);
        if( c>=0 && c<pOut->nCol ) valCopy(p->pA,kv,pOut->ap[i]+c);
      }else if( e->op==TKX_COLUMN && e->zTok2==0 && kv->type==VT_NULL ){
        int z;
        for(z=0;z<nRes;z++){
          (void)z;
        }
      }
    }
  }
  for(i=0;i<n;i++) aiIdx[i] = i;
  /* insertion sort */
  for(i=1;i<n;i++){
    int x = aiIdx[i];
    j = i-1;
    while( j>=0 ){
      int c = 0;
      int q;
      for(q=0;q<nk;q++){
        c = valCmp(pKeys->ap[aiIdx[j]]+q, pKeys->ap[x]+q);
        if( c==0 ) continue;
        break;
      }
      if( c>0 ){ aiIdx[j+1]=aiIdx[j]; j--; }
      else break;
    }
    aiIdx[j+1] = x;
  }
  {
    RowBuf tmp;
    rowbufInit(&tmp,p->pA,pOut->nCol);
    for(i=0;i<n;i++) rowbufAppend(&tmp,pOut->ap[aiIdx[i]],0);
    *pOut = tmp;
  }
}

/* compound fold */
int selRun(Eval *p, Select *s, Out *pOut, Scope *pOuter){
  RowBuf rb, kb;
  char **azNames = 0;
  int i;
  /* handle compound */
  if( s->op!=0 ){
    RowBuf acc, kacc;
    char **az = 0;
    Select *cur = s;
    /* first core */
    rowbufInit(&acc,p->pA,0);
    rowbufInit(&kacc,p->pA,0);
    if( runCore(p,cur,&acc,&kacc,&az,pOuter) ) return 1;
    azNames = az;
    cur = cur->pNext;
    while( cur ){
      RowBuf rb2, kb2;
      char **az2 = 0;
      rowbufInit(&rb2,p->pA,0);
      rowbufInit(&kb2,p->pA,0);
      if( runCore(p,cur,&rb2,&kb2,&az2,pOuter) ) return 1;
      {
        int op = s->op;
        RowBuf out;
        int a, b;
        rowbufInit(&out,p->pA,acc.nCol);
        if( op==2 ){   /* UNION ALL */
          for(a=0;a<acc.n;a++) rowbufAppend(&out,acc.ap[a],0);
          for(a=0;a<rb2.n;a++) rowbufAppend(&out,rb2.ap[a],0);
        }else if( op==1 ){  /* UNION */
          for(a=0;a<acc.n;a++) rowbufAppend(&out,acc.ap[a],0);
          for(a=0;a<rb2.n;a++){
            int dup = 0;
            for(b=0;b<out.n;b++) if( cmpResRow(&out,a,b)==0 ){ dup=1; break; }
            for(b=0;b<acc.n;b++) if( cmpResRow(&acc,a,b)==0 ){ dup=1; break; }
            if( !dup ) rowbufAppend(&out,rb2.ap[a],0);
          }
        }else if( op==3 ){  /* EXCEPT */
          for(a=0;a<acc.n;a++){
            int dup = 0;
            for(b=0;b<rb2.n;b++) if( cmpResRow(&acc,a,b)==0 ){ dup=1; break; }
            if( !dup ) rowbufAppend(&out,acc.ap[a],0);
          }
        }else{  /* INTERSECT */
          for(a=0;a<acc.n;a++){
            int dup = 0;
            for(b=0;b<rb2.n;b++) if( cmpResRow(&acc,a,b)==0 ){ dup=1; break; }
            if( dup ) rowbufAppend(&out,acc.ap[a],0);
          }
        }
        acc = out;
      }
      cur = cur->pNext;
    }
    rb = acc;
  }else{
    rowbufInit(&rb,p->pA,0);
    rowbufInit(&kb,p->pA,0);
    if( runCore(p,s,&rb,&kb,&azNames,pOuter) ) return 1;
  }
  /* ORDER BY */
  if( s->pOrderBy && s->pOrderBy->nExpr>0 ){
    RowBuf k2;
    ExprList *po = s->pOrderBy;
    int nk = po->nExpr;
    rowbufInit(&k2,p->pA,nk);
    for(i=0;i<rb.n;i++){
      Value *akey = arenaAlloc(p->pA, nk*sizeof(Value));
      int q;
      for(q=0;q<nk;q++) valInit(&akey[q]);
      for(q=0;q<nk;q++){
        Expr *e = po->apExpr[q];
        if( e->op==TKX_INT ){
          int c = (int)e->v.i-1;
          if( c>=0 && c<rb.nCol ) valCopy(p->pA,&akey[q],rb.ap[i]+c);
        }else if( e->op==TKX_COLUMN && e->zTok2==0 ){
          int z;
          for(z=0;z<rb.nCol;z++){
            (void)z;
          }
          /* look up by alias */
          {
            /* find alias index */
            int found = -1;
            int k;
            for(k=0;k<rb.nCol;k++){
              if( azNames && azNames[k] && strEq(azNames[k],e->zTok) ){ found=k; break; }
            }
            if( found>=0 ) valCopy(p->pA,&akey[q],rb.ap[i]+found);
          }
        }
      }
      rowbufAppend(&k2,akey,0);
    }
    /* DESC handling: invert by negating? simplest: sort with direction */
    {
      int *aiDesc = arenaAlloc(p->pA, nk*sizeof(int));
      int n = rb.n;
      int *aiIdx = arenaAlloc(p->pA, (n>0?n:1)*sizeof(int));
      int a, b;
      for(i=0;i<nk;i++) aiDesc[i] = po->aiSortOrder[i];
      for(i=0;i<n;i++) aiIdx[i] = i;
      for(i=1;i<n;i++){
        int x = aiIdx[i];
        int j = i-1;
        while( j>=0 ){
          int c = 0;
          int q;
          for(q=0;q<nk;q++){
            c = valCmp(k2.ap[aiIdx[j]]+q, k2.ap[x]+q);
            if( aiDesc[q] ) c = -c;
            if( c==0 ) continue;
            break;
          }
          if( c>0 ){ aiIdx[j+1]=aiIdx[j]; j--; }
          else break;
        }
        aiIdx[j+1] = x;
      }
      {
        RowBuf tmp;
        rowbufInit(&tmp,p->pA,rb.nCol);
        for(i=0;i<n;i++) rowbufAppend(&tmp,rb.ap[aiIdx[i]],0);
        rb = tmp;
      }
    }
  }
  /* LIMIT / OFFSET */
  if( s->pLimit || s->pOffset ){
    i64 nLimit = -1, nOffset = 0;
    Value v;
    if( s->pOffset ){ valInit(&v); evalExprIn(p,s->pOffset,0,0,&v); if( v.type==VT_INT ) nOffset = v.i; }
    if( s->pLimit ){ valInit(&v); evalExprIn(p,s->pLimit,0,0,&v); if( v.type==VT_INT ) nLimit = v.i; }
    {
      RowBuf tmp;
      int start = (int)nOffset;
      int end = (nLimit<0) ? rb.n : (int)(start+nLimit);
      if( start<0 ) start = 0;
      if( start>rb.n ) start = rb.n;
      if( end>rb.n ) end = rb.n;
      rowbufInit(&tmp,p->pA,rb.nCol);
      for(i=start;i<end;i++) rowbufAppend(&tmp,rb.ap[i],0);
      rb = tmp;
    }
  }
  /* emit */
  pOut->nOut = rb.nCol;
  pOut->azName = azNames;
  for(i=0;i<rb.n;i++){
    if( pOut->xRow ) pOut->xRow(pOut->pArg, rb.ap[i], rb.nCol, azNames);
    pOut->nRow++;
  }
  return 0;
}
