/* ============ CTE ============ */
typedef struct CteList {
  CteTab a[16];
  int n;
} CteList;
Table *cteLookup(Eval *p, const char *zName){
  CteList *l = p->pCte;
  int i;
  if( l==0 ) return 0;
  for(i=l->n-1;i>=0;i--) if( strEq(l->a[i].zName,zName) ) return l->a[i].pTab;
  return 0;
}
static Table *mkSimpleTable(Arena *pA, const char *zName, char **azCol, int nCol){
  Table *t = arenaAlloc(pA, sizeof(Table));
  int i;
  memset(t,0,sizeof(*t));
  t->zName = arenaStrdup(pA,zName);
  t->nCol = nCol;
  t->aCol = arenaAlloc(pA, (nCol>0?nCol:1)*sizeof(Column));
  memset(t->aCol,0,nCol*sizeof(Column));
  for(i=0;i<nCol;i++){
    t->aCol[i].zName = arenaStrdup(pA, azCol[i]);
    t->aCol[i].affinity = AF_BLOB;
    t->aCol[i].zType = 0;
  }
  t->apRow = 0;
  t->nRow = 0;
  t->nRowCap = 0;
  t->nextRowid = 1;
  return t;
}
static void ctePush(Eval *p, const char *zName, Table *t){
  CteList *l = p->pCte;
  if( l==0 ){ l = arenaAlloc(p->pA,sizeof(CteList)); memset(l,0,sizeof(*l)); p->pCte = l; }
  l->a[l->n].zName = arenaStrdup(p->pA,zName);
  l->a[l->n].pTab = t;
  l->n++;
}
static void ctePop(Eval *p){
  CteList *l = p->pCte;
  if( l && l->n>0 ) l->n--;
}
int matWith(Eval *p, With *pWith){
  int i;
  for(i=0;i<pWith->nCte;i++){
    Cte *c = pWith->apCte[i];
    Table *t;
    char *azCol[64];
    int nCol = 0;
    RowBuf rb;
    char **azNames = 0;
    RowBuf kb;
    Out o;
    Eval sub;
    if( c->pCols ){
      int j;
      for(j=0;j<c->pCols->nExpr;j++){
        azCol[nCol++] = arenaStrdup(p->pA, valText(p->pA,&c->pCols->apExpr[j]->v));
      }
    }
    t = mkSimpleTable(p->pA, c->zName, azCol, nCol>0?nCol:1);
    ctePush(p, c->zName, t);
    if( nCol==0 ){
      /* need column names from the body */
      rowbufInit(&rb,p->pA,0);
      rowbufInit(&kb,p->pA,0);
      memset(&o,0,sizeof(o));
      o.pArg = &rb;
      sub = *p;
      sub.pCur = 0;
      sub.iDepth = p->iDepth+1;
      if( selRun(&sub, c->pSelect, &o, p->pScope) ) return 1;
      nCol = rb.nCol;
      azCol[0] = arenaStrdup(p->pA,"column1");
      t = mkSimpleTable(p->pA, c->zName, azCol, nCol);
      ctePop(p);
      ctePush(p, c->zName, t);
      /* copy rows */
      {
        int j2;
        for(j2=0;j2<rb.n;j2++){
          Value *r = arenaAlloc(p->pA, nCol*sizeof(Value));
          int k;
          for(k=0;k<nCol;k++){ valInit(&r[k]); valCopy(p->pA,&r[k],rb.ap[j2]+k); }
          tableInsertRow(0, t, j2+1, r);
        }
      }
      continue;
    }
    if( pWith->recursive && c->pSelect->op!=0 ){
      /* recursive CTE */
      RowBuf acc, queue;
      Select *sBody = c->pSelect;
      int iter = 0;
      rowbufInit(&acc,p->pA,nCol);
      rowbufInit(&queue,p->pA,nCol);
      /* initial part */
      {
        Out o2;
        RowBuf rb2;
        Eval sub;
        memset(&o2,0,sizeof(o2));
        rowbufInit(&rb2,p->pA,nCol);
        o2.pArg = &rb2;
        sub = *p;
        sub.pCur = 0;
        sub.iDepth = p->iDepth+1;
        if( selRun(&sub, sBody, &o2, p->pScope) ) return 1;
        {
          int j2;
          for(j2=0;j2<rb2.n;j2++){
            Value *r = arenaAlloc(p->pA, nCol*sizeof(Value));
            int k;
            for(k=0;k<nCol;k++){ valInit(&r[k]); valCopy(p->pA,&r[k],rb2.ap[j2]+k); }
            rowbufAppend(&acc,r,0);
            rowbufAppend(&queue,r,0);
          }
        }
      }
      while( queue.n>0 && iter<100000 ){
        Out o2;
        RowBuf rb2, kb2;
        Eval sub;
        Select *sRec = sBody->pNext;
        int j2;
        /* set the CTE table to the queue rows */
        t->nRow = 0;
        for(j2=0;j2<queue.n;j2++){
          Value *r = arenaAlloc(p->pA, nCol*sizeof(Value));
          int k;
          for(k=0;k<nCol;k++){ valInit(&r[k]); valCopy(p->pA,&r[k],queue.ap[j2]+k); }
          tableInsertRow(0, t, j2+1, r);
        }
        rowbufInit(&rb2,p->pA,nCol);
        rowbufInit(&kb2,p->pA,nCol);
        memset(&o2,0,sizeof(o2));
        o2.pArg = &rb2;
        sub = *p;
        sub.pCur = 0;
        sub.iDepth = p->iDepth+1;
        if( selRun(&sub, sRec, &o2, p->pScope) ) return 1;
        queue.n = 0;
        for(j2=0;j2<rb2.n;j2++){
          Value *r = arenaAlloc(p->pA, nCol*sizeof(Value));
          int k;
          for(k=0;k<nCol;k++){ valInit(&r[k]); valCopy(p->pA,&r[k],rb2.ap[j2]+k); }
          rowbufAppend(&acc,r,0);
          rowbufAppend(&queue,r,0);
        }
        iter++;
        if( rb2.n==0 ) break;
      }
      /* install accumulated rows */
      t->nRow = 0;
      {
        int j2;
        for(j2=0;j2<acc.n;j2++){
          Value *r = arenaAlloc(p->pA, nCol*sizeof(Value));
          int k;
          for(k=0;k<nCol;k++){ valInit(&r[k]); valCopy(p->pA,&r[k],acc.ap[j2]+k); }
          tableInsertRow(0, t, j2+1, r);
        }
      }
    }else{
      Out o2;
      RowBuf rb2, kb2;
      Eval sub;
      memset(&o2,0,sizeof(o2));
      rowbufInit(&rb2,p->pA,nCol);
      rowbufInit(&kb2,p->pA,nCol);
      o2.pArg = &rb2;
      sub = *p;
      sub.pCur = 0;
      sub.iDepth = p->iDepth+1;
      if( selRun(&sub, c->pSelect, &o2, p->pScope) ) return 1;
      {
        int j2;
        for(j2=0;j2<rb2.n;j2++){
          Value *r = arenaAlloc(p->pA, nCol*sizeof(Value));
          int k;
          for(k=0;k<nCol;k++){ valInit(&r[k]); valCopy(p->pA,&r[k],rb2.ap[j2]+k); }
          tableInsertRow(0, t, j2+1, r);
        }
      }
    }
  }
  return 0;
}
