/* ============ window functions ============ */
void computeWindow(Eval *p, RowBuf *pOut, RowBuf *pArgs, RowBuf *pPart,
                   RowBuf *pOrd, int *aiWinCol, Expr **apWin, int nWin){
  int n = pOut->n;
  int q;
  int *aiIdx = arenaAlloc(p->pA, (n>0?n:1)*sizeof(int));
  for(q=0;q<n;q++) aiIdx[q] = q;
  for(q=0;q<nWin;q++){
    Expr *wf = apWin[q];
    const char *zn = wf->zTok;
    int na = wf->pList?wf->pList->nExpr:0;
    Window *w = (Window*)wf->pRight;
    int nPart = w ? (w->pPartition?w->pPartition->nExpr:0) : 0;
    int nOrd = w ? (w->pOrderBy?w->pOrderBy->nExpr:0) : 0;
    Value *apVal = arenaAlloc(p->pA, (n>0?n:1)*sizeof(Value));
    int i;
    int *aiSorted;
    for(i=0;i<n;i++) valInit(&apVal[i]);
    aiSorted = arenaAlloc(p->pA, (n>0?n:1)*sizeof(int));
    for(i=0;i<n;i++) aiSorted[i] = i;
    /* stable sort by partition then order */
    {
      int a, b;
      for(i=1;i<n;i++){
        int x = aiSorted[i];
        int j = i-1;
        while( j>=0 ){
          int c = 0;
          int k;
          for(k=0;k<nPart;k++){
            c = valCmp(pPart->ap[aiSorted[j]]+k, pPart->ap[x]+k);
            if( c ) break;
          }
          if( c==0 ){
            for(k=0;k<nOrd;k++){
              c = valCmp(pOrd->ap[aiSorted[j]]+k, pOrd->ap[x]+k);
              if( c ) break;
            }
          }
          if( c>0 ){ aiSorted[j+1]=aiSorted[j]; j--; } else break;
        }
        aiSorted[j+1] = x;
      }
    }
    /* walk partitions */
    {
      int start = 0;
      while( start<n ){
        int end = start;
        while( end<n ){
          int k, same = 1;
          for(k=0;k<nPart;k++){
            if( valCmp(pPart->ap[aiSorted[end]]+k, pPart->ap[aiSorted[start]]+k)!=0 ){ same=0; break; }
          }
          if( !same ) break;
          end++;
        }
        /* partition = [start,end) in sorted order */
        {
          int k;
          if( strEq(zn,"row_number") ){
            for(k=start;k<end;k++) valSetInt(p->pA,&apVal[aiSorted[k]], k-start+1);
          }else if( strEq(zn,"rank") || strEq(zn,"dense_rank") ){
            int rank = 1;
            int dense = 1;
            int pos = 0;
            for(k=start;k<end;k++){
              if( k>start ){
                int same = 1;
                int m;
                for(m=0;m<nOrd;m++){
                  if( valCmp(pOrd->ap[aiSorted[k]]+m, pOrd->ap[aiSorted[k-1]]+m)!=0 ){ same=0; break; }
                }
                if( !same ){ rank = k-start+1; dense++; }
              }
              if( strEq(zn,"rank") ) valSetInt(p->pA,&apVal[aiSorted[k]], rank);
              else valSetInt(p->pA,&apVal[aiSorted[k]], dense);
            }
          }else if( strEq(zn,"ntile") ){
            int nb = 1;
            if( na>0 && pArgs->ap[aiSorted[start]]->type==VT_INT ) nb = (int)pArgs->ap[aiSorted[start]]->i;
            if( nb<1 ) nb = 1;
            for(k=start;k<end;k++){
              int idx = k-start;
              valSetInt(p->pA,&apVal[aiSorted[k]], (idx*nb)/((end-start)>0?(end-start):1)+1);
            }
          }else if( strEq(zn,"lag") || strEq(zn,"lead") ){
            int off = 1;
            if( na>1 && pArgs->ap[aiSorted[start]+1].type==VT_INT ) off = (int)pArgs->ap[aiSorted[start]+1].i;
            for(k=start;k<end;k++){
              int idx = strEq(zn,"lag") ? (k-start)-off : (k-start)+off;
              if( idx<0 || idx>=(end-start) ){
                if( na>2 ) valCopy(p->pA,&apVal[aiSorted[k]], pArgs->ap[aiSorted[start]+2]);
                else valSetNull(&apVal[aiSorted[k]]);
              }else valCopy(p->pA,&apVal[aiSorted[k]], pArgs->ap[aiSorted[idx+start]]);
            }
          }else if( strEq(zn,"first_value") ){
            valCopy(p->pA,&apVal[aiSorted[start]], pArgs->ap[aiSorted[start]]);
            for(k=start;k<end;k++) valCopy(p->pA,&apVal[aiSorted[k]], pArgs->ap[aiSorted[start]]);
          }else if( strEq(zn,"last_value") ){
            for(k=start;k<end;k++) valCopy(p->pA,&apVal[aiSorted[k]], pArgs->ap[aiSorted[end-1]]);
          }else if( strEq(zn,"nth_value") ){
            int nth = 1;
            if( na>1 && pArgs->ap[aiSorted[start]+1].type==VT_INT ) nth = (int)pArgs->ap[aiSorted[start]+1].i;
            for(k=start;k<end;k++){
              int idx = start+nth-1;
              if( nth>=1 && idx<end ) valCopy(p->pA,&apVal[aiSorted[k]], pArgs->ap[aiSorted[idx]]);
              else valSetNull(&apVal[aiSorted[k]]);
            }
          }else{
            /* aggregate window function */
            AggAcc acc;
            int k, m;
            memset(&acc,0,sizeof(acc));
            acc.bInt = 1;
            if( strEq(zn,"count") ) acc.kind = 0;
            else if( strEq(zn,"sum") ) acc.kind = 1;
            else if( strEq(zn,"total") ) acc.kind = 2;
            else if( strEq(zn,"avg") ) acc.kind = 3;
            else if( strEq(zn,"min") ) acc.kind = 4;
            else if( strEq(zn,"max") ) acc.kind = 5;
            else if( strEq(zn,"group_concat") ) acc.kind = 6;
            else acc.kind = 0;
            /* frame: default.  With ORDER BY: unbounded preceding..current row (with peers);
            ** without ORDER BY: whole partition */
            {
              int frameEnd = end-1;
              if( nOrd>0 ){
                int k2;
                for(k2=end-1;k2>=start;k2--){
                  int same = 1;
                  int m2;
                  for(m2=0;m2<nOrd;m2++){
                    if( valCmp(pOrd->ap[aiSorted[k2]]+m2, pOrd->ap[aiSorted[end-1]]+m2)!=0 ){ same=0; break; }
                  }
                  if( same ) frameEnd = k2;
                  else break;
                }
              }
              for(k=start;k<=frameEnd;k++){
                Value tmp;
                valInit(&tmp);
                if( na==0 ) aggStep(&acc,p->pA,&tmp,0,1);
                else aggStep(&acc,p->pA,pArgs->ap[aiSorted[k]],na,0);
              }
            }
            aggFinal(&acc,p->pA,&apVal[aiSorted[end-1]]);
            for(m=end-2;m>=start;m--) valCopy(p->pA,&apVal[aiSorted[m]],&apVal[aiSorted[end-1]]);
            (void)m;
          }
        }
        start = end;
      }
    }
    /* patch output rows */
    for(i=0;i<n;i++){
      Value *dst = pOut->ap[i] + aiWinCol[q];
      valFree(dst);
      valCopy(p->pA,dst,&apVal[i]);
    }
  }
}
