#include "core.h"
#include "lex.h"
#include "parse.h"
#include "db.h"
#include "exec.h"
#include "func.h"

/* ============ db open/close ============ */
static Schema *schemaNew(const char *zName){
  Schema *s = malloc(sizeof(Schema));
  memset(s,0,sizeof(*s));
  s->zName = strDup(zName);
  s->pageSize = 4096;
  s->journalMode = 0;
  s->isMem = 1;
  return s;
}
Db *dbOpen(void){
  Db *p = malloc(sizeof(Db));
  memset(p,0,sizeof(*p));
  p->pMain = schemaNew("main");
  p->pTemp = schemaNew("temp");
  p->pMain->pDb = p;
  p->pTemp->pDb = p;
  p->pageSize = 4096;
  p->defensive = 1;
  return p;
}
void dbClose(Db *p){
  Schema *s, *ns;
  if( p==0 ) return;
  schemaFree(p->pMain);
  schemaFree(p->pTemp);
  for(s=p->pAttached;s;s=ns){ ns=s->pNext; schemaFree(s); }
  free(p);
}

/* ============ build objects from parsed statements ============ */
static int colAffinityOf(ColDef *c){ return affinityOf(c->zType); }

Table *makeTable(Db *pDb, Schema *pS, Stmt *p, Arena *pA, Error *pErr){
  Table *t = malloc(sizeof(Table));
  int i, nPk = 0;
  char buf[256];
  memset(t,0,sizeof(*t));
  t->zName = strDup(p->ct.zTab);
  t->nCol = p->nCol;
  t->aCol = malloc((t->nCol>0?t->nCol:1)*sizeof(Column));
  memset(t->aCol,0,t->nCol*sizeof(Column));
  t->iPk = -1;
  t->withoutRowid = p->ct.withoutRowid;
  t->nextRowid = 1;
  for(i=0;i<p->nCol;i++){
    ColDef *c = &p->aCol[i];
    t->aCol[i].zName = strDup(c->zName);
    t->aCol[i].zType = strDup(c->zType);
    t->aCol[i].affinity = colAffinityOf(c);
    t->aCol[i].notNull = c->notNull;
    t->aCol[i].collate = c->collate;
    if( c->pDefault ){
      Value v;
      valInit(&v);
      {
        extern void evalConstExpr(Eval *p, Expr *e, Value *o);
        Eval ev;
        memset(&ev,0,sizeof(ev));
        ev.pDb = pDb;
        ev.pA = pA;
        ev.pErr = pErr;
        evalConstExpr(&ev, c->pDefault, &v);
      }
      if( v.type==VT_TEXT || v.type==VT_BLOB ) t->aCol[i].zDflt = quoteSql(pA,&v);
      else if( v.type==VT_INT ) t->aCol[i].zDflt = strPrintf("%lld",v.i);
      else if( v.type==VT_REAL ) t->aCol[i].zDflt = realToText(pA,v.r);
      else t->aCol[i].zDflt = strDup("NULL");
      valFree(&v);
    }
    if( c->pk ){
      nPk++;
      t->aCol[i].pkOrd = nPk;
      if( strEq(c->zType,"INTEGER") || strEq(c->zType,"INT") || strEq(c->zType,"INT2") || strEq(c->zType,"INT8") ){
        t->iPk = i;
      }
    }
  }
  /* single-column INTEGER PRIMARY KEY is a rowid alias */
  if( nPk==1 && t->iPk>=0 ) t->iPk = t->iPk;
  else if( nPk==1 && t->iPk<0 ) t->iPk = -1;
  else t->iPk = -1;
  /* build SQL text: reproduce the CREATE TABLE statement */
  snprintf(buf,sizeof(buf),"CREATE TABLE %s(", t->zName);
  for(i=0;i<p->nCol;i++){
    ColDef *c = &p->aCol[i];
    if( i ) strcat(buf,", ");
    strcat(buf,c->zName);
    if( c->zType && c->zType[0] ){ strcat(buf," "); strcat(buf,c->zType); }
    if( c->notNull ) strcat(buf," NOT NULL");
    if( c->zDflt ){ strcat(buf," DEFAULT "); strcat(buf,c->zDflt); }
    if( c->pk ) strcat(buf," PRIMARY KEY");
    if( c->unique ) strcat(buf," UNIQUE");
  }
  strcat(buf,")");
  t->zSql = strDup(buf);
  /* auto indexes for unique / non-integer pk */
  for(i=0;i<p->nCol;i++){
    ColDef *c = &p->aCol[i];
    if( c->unique || (c->pk && !(t->iPk==i)) ){
      Index *x = malloc(sizeof(Index));
      memset(x,0,sizeof(*x));
      x->zName = strPrintf("sqlite_autoindex_%s_%d", t->zName, ++nAutoIdx);
      x->zTbl = strDup(t->zName);
      x->nCol = 1;
      x->aCol = malloc(sizeof(IndexCol));
      memset(x->aCol,0,sizeof(IndexCol));
      x->aCol[0].zName = strDup(c->zName);
      x->aCol[0].iCol = i;
      x->aCol[0].desc = c->pkDesc;
      x->unique = 1;
      x->origin = c->pk ? 1 : 2;
      x->zSql = 0;
      tableAddIndex(t,x);
    }
  }
  for(i=0;i<p->nCon;i++){
    struct TabCon *c = &p->aCon[i];
    if( c->type==0 || c->type==1 ){
      Index *x = malloc(sizeof(Index));
      int j, n = c->pList?c->pList->nExpr:0;
      int allInt = 1;
      int anyDesc = 0;
      memset(x,0,sizeof(*x));
      x->zTbl = strDup(t->zName);
      x->nCol = n>0?n:1;
      x->aCol = malloc(x->nCol*sizeof(IndexCol));
      memset(x->aCol,0,x->nCol*sizeof(IndexCol));
      for(j=0;j<x->nCol;j++){
        Expr *e = c->pList->apExpr[j];
        int ic = colIndexOf(t, e->zTok);
        if( ic<0 ) ic = 0;
        x->aCol[j].zName = strDup(t->aCol[ic].zName);
        x->aCol[j].iCol = ic;
        x->aCol[j].desc = c->pList->aiSortOrder[j];
        if( x->aCol[j].desc ) anyDesc = 1;
        if( t->aCol[ic].affinity!=AF_INT ) allInt = 0;
      }
      if( c->type==0 ){
        /* primary key */
        if( n==1 && allInt && !anyDesc && t->iPk<0 ){
          t->iPk = x->aCol[0].iCol;
          free(x);
          continue;
        }
        x->unique = 1;
        x->origin = 1;
      }else{
        x->unique = 1;
        x->origin = 2;
      }
      x->zName = strPrintf("sqlite_autoindex_%s_%d", t->zName, ++nAutoIdx);
      tableAddIndex(t,x);
    }
  }
  if( t->iPk>=0 ){
    /* rowid alias column: mark */
  }
  return t;
}
SEOF
gcc -c -O1 -o stmt.o stmt.c -Wall -I. 2>&1|grep error|head; echo rc=$?"}

