/* add an object to the schema, used when reading a database file */
int dbAddSchemaObject(Db *pDb, Schema *pS, const char *zType, const char *zName,
                     const char *zTbl, i64 rootpage, const char *zSql, i64 rowid, Arena *pA){
  Stmt *st;
