  if( st==0 ) return 1;
  if( strEq(zType,"table") && st->kind==ST_CREATE_TABLE ){
    Table *t = makeTable(pDb, pS, st, pA, &e);
    if( t ){
      t->iSchema = rowid;
      t->pNextTable = pS->pTable;
      pS->pTable = t;
    }
  }else if( strEq(zType,"index") && st->kind==ST_CREATE_INDEX ){
    Index *x = makeIndex(pDb, pS, st, pA, &e);
    if( x ){
      Table *t = schemaFindTable(pS, x->zTbl);
      if( t ){
        x->iSchema = rowid;
        x->pNext = t->pIndex;
        t->pIndex = x;
      }
    }
  }else if( strEq(zType,"view") && st->kind==ST_CREATE_VIEW ){
    View *v = makeView(pDb, pS, st, pA, &e);
    if( v ){
      v->iSchema = rowid;
      v->pNext = pS->pView;
      pS->pView = v;
    }
  }else if( strEq(zType,"trigger") && st->kind==ST_CREATE_TRIGGER ){
    Trigger *t = makeTrigger(pDb, pS, st, pA, &e);
    if( t ){
      t->iSchema = rowid;
      t->pNext = pS->pTrigger;
      pS->pTrigger = t;
    }
  }
  return 0;
}
