  if( e ) evalExpr(p,e,o);
}
static void applyColAffinity(Table *t, int iCol, Value *v){
  if( iCol<0 || iCol>=t->nCol ) return;
  applyAffinity(v, t->aCol[iCol].affinity);
}

/* build a row of values for insert */
static int buildInsertRow(Eval *p, Table *t, ExprList *pCols, ExprList *pRow, Value *aVal, int *pnOut){
  int i;
  int nCol = t->nCol;
  int aiMap[512];
  int nSpec = 0;
  for(i=0;i<nCol;i++) aiMap[i] = -1;
  if( pCols ){
    int j;
    nSpec = pCols->nExpr;
    for(j=0;j<nSpec;j++){
      int ic = colIndexOf(t, pCols->apExpr[j]->zTok);
      if( ic<0 ){
        errSetPos(p->pErr, pCols->apExpr[j]->start, "table %s has no column named %s", t->zName, pCols->apExpr[j]->zTok);
        return 1;
      }
      aiMap[ic] = j;
    }
  }
  for(i=0;i<nCol;i++) valInit(&aVal[i]);
  for(i=0;i<nCol;i++){
    if( aiMap[i]>=0 ){
      if( aiMap[i] < (pRow?pRow->nExpr:0) ){
        valFromExpr(p, pRow->apExpr[aiMap[i]], &aVal[i]);
      }else{
        valSetNull(&aVal[i]);
      }
    }else if( t->aCol[i].zDflt ){
      /* default value */
      const char *z = t->aCol[i].zDflt;
      if( strEq(z,"NULL") ) valSetNull(&aVal[i]);
      else if( isNumericText(z) ){
        if( strpbrk(z,".") ) valSetReal(p->pA,&aVal[i], textToReal(z));
        else valSetInt(p->pA,&aVal[i], strtoll(z,0,10));
      }else if( z[0]=='\'' ){
        char *r = arenaAlloc(p->pA, strlen(z));
        int j, k = 0;
        for(j=1;z[j]&&z[j+1];j++){
          if( z[j]=='\'' && z[j+1]=='\'' ){ r[k++]='\''; j++; }
          else r[k++] = z[j];
        }
        r[k] = 0;
        valSetTextN(p->pA,&aVal[i],r,k);
      }else valSetNull(&aVal[i]);
    }else{
      valSetNull(&aVal[i]);
    }
  }
  *pnOut = nCol;
  return 0;
}

/* check constraints for a row */
static int checkConstraints(Eval *p, Table *t, Value *aVal, i64 rowid, int iSkip){
  int i, j;
  for(i=0;i<t->nCol;i++){
    if( i==iSkip ) continue;
    if( t->aCol[i].notNull && aVal[i].type==VT_NULL ){
      errSetPos(p->pErr, 0, "NOT NULL constraint failed: %s.%s", t->zName, t->aCol[i].zName);
      p->pErr->hasPos = 0;
      return 1;
    }
  }
  /* unique indexes */
  for(;;){
    Index *x;
    int found = 0;
    for(x=t->pIndex; x; x=x->pNext){
      if( !x->unique ) continue;
      for(j=0;j<x->nKey;j++){
        int k, same = 1;
        if( x->aiKeyRowid[j]==rowid ) continue;
        for(k=0;k<x->nCol;k++){
          if( valCmp(x->apKeyVal[j]+k, &aVal[x->aCol[k].iCol])!=0 ){ same=0; break; }
        }
        if( same ){
          char buf[256];
          buf[0]=0;
          for(k=0;k<x->nCol;k++){
            if( k ) strcat(buf,", ");
            strcat(buf,t->zName); strcat(buf,"."); strcat(buf,t->aCol[x->aCol[k].iCol].zName);
          }
          errSet(p->pErr,"UNIQUE constraint failed: %s", buf);
          return 1;
        }
      }
    }
    (void)found;
    break;
  }
  return 0;
}
