/* ============ triggers ============ */
static int execTriggerBody(Eval *p, Trigger *tr, Table *t, Value *aNew, Value *aOld, i64 rowid);

static Table *mkOneRowTable(Eval *p, Table *t, Value *aVal, i64 rowid, const char *zName){
  Table *n = arenaAlloc(p->pA, sizeof(Table));
  int i;
  memset(n,0,sizeof(*n));
  n->zName = arenaStrdup(p->pA, zName);
  n->nCol = t->nCol;
  n->aCol = arenaAlloc(p->pA, t->nCol*sizeof(Column));
  memcpy(n->aCol, t->aCol, t->nCol*sizeof(Column));
  n->iPk = t->iPk;
  n->nextRowid = 1;
  {
    Value *r = arenaAlloc(p->pA, t->nCol*sizeof(Value));
    for(i=0;i<t->nCol;i++){ valInit(&r[i]); valCopy(p->pA,&r[i], aVal+i); }
    tableInsertRow(0, n, rowid, r);
  }
  return n;
}

static int fireTriggers(Eval *p, Table *t, int when, int event, Value *aNew, Value *aOld, i64 rowid){
  Db *pDb = p->pDb;
  Schema *pS;
  Trigger *tr;
  int rc = 0;
  for(pS=pDb->pMain; pS; pS=0){
    for(tr=pS->pTrigger; tr; tr=tr->pNext){
      if( !strEq(tr->zTbl,t->zName) ) continue;
      if( tr->when!=when ) continue;
      if( tr->event!=event ) continue;
      rc = execTriggerBody(p, tr, t, aNew, aOld, rowid);
      if( rc ) return rc;
    }
    break;
  }
  return 0;
}

static int execTriggerBody(Eval *p, Trigger *tr, Table *t, Value *aNew, Value *aOld, i64 rowid){
  int i;
  Table *tn = 0, *to = 0;
  if( aNew ) tn = mkOneRowTable(p, t, aNew, rowid, "new");
  if( aOld ) to = mkOneRowTable(p, t, aOld, rowid, "old");
  if( tn ) ctePush(p, "new", tn);
  if( to ) ctePush(p, "old", to);
  for(i=0;i<tr->nStmt;i++){
    Error e2;
    Out o2;
    Eval ev = *p;
    memset(&o2,0,sizeof(o2));
    memset(&e2,0,sizeof(e2));
    ev.pErr = &e2;
    ev.iDepth = p->iDepth+1;
    if( ev.iDepth>50 ) break;
    if( execStmt(p->pDb, tr->apStmt[i], p->pA, &o2, &e2, p->pParam) ){
      errSet(p->pErr,"%s", e2.msg);
      if( tn ) ctePop(p);
      if( to ) ctePop(p);
      return 1;
    }
  }
  if( tn ) ctePop(p);
  if( to ) ctePop(p);
  return 0;
}

/* ============ main statement execution ============ */
int execStmt(Db *pDb, Stmt *p, Arena *pA, Out *pOut, Error *pErr, Param *pParam){
  Eval ev;
  memset(&ev,0,sizeof(ev));
  ev.pDb = pDb;
  ev.pA = pA;
  ev.pErr = pErr;
  ev.pParam = pParam;
  ev.pOut = pOut;
  switch( p->kind ){
    case ST_SELECT: {
      if( selRun(&ev, p->pSelect, pOut, 0) ) return 1;
      return 0;
    }
    case ST_INSERT: {
      Table *t;
      Schema *pS;
      int i, nCol;
      t = dbFindTable(pDb, p->ins.zTab, p->ins.zDb, &pS);
      if( t==0 ){
        errSetPos(pErr, p->startPos, "no such table: %s", p->ins.zDb&&p->ins.zDb[0]?strPrintf("%s.%s",p->ins.zDb,p->ins.zTab):p->ins.zTab);
        return 1;
      }
      pDb->changes = 0;
      if( p->ins.defaultValues ){
        Value *aVal = arenaAlloc(pA, t->nCol*sizeof(Value));
        i64 rowid;
        buildInsertRow(&ev, t, 0, 0, aVal, &nCol);
        applyColAffinity(t,-1,0);
        for(i=0;i<t->nCol;i++) applyColAffinity(t,i,&aVal[i]);
        if( t->iPk>=0 && aVal[t->iPk].type==VT_NULL ){
          rowid = tableNextRowid(t);
          valSetInt(pA,&aVal[t->iPk],rowid);
        }else if( t->iPk>=0 ){
          rowid = aVal[t->iPk].i;
          if( tableFindKey(t,rowid)>=0 ){
            if( p->ins.onConflict==4 ){ return 0; }
            errSet(pErr,"UNIQUE constraint failed: %s.%s", t->zName, t->aCol[t->iPk].zName);
            return 1;
          }
        }else{
          rowid = tableNextRowid(t);
        }
        if( checkConstraints(&ev,t,aVal,rowid,-1) ) return 1;
        if( fireTriggers(&ev,t,0,1,aVal,0,rowid) ) return 1;
        tableInsertRow(pDb,t,rowid,aVal);
        fireTriggers(&ev,t,1,1,aVal,0,rowid);
        pDb->changes++;
        pDb->totalChanges++;
        return 0;
      }
      if( p->ins.apRowValues ){
        for(i=0;i<p->ins.nRow;i++){
          Value *aVal = arenaAlloc(pA, t->nCol*sizeof(Value));
          i64 rowid;
          ExprList *row = p->ins.apRowValues[i];
          if( row->nExpr != (p->ins.pCols?p->ins.pCols->nExpr:t->nCol) ){
            errSet(pErr,"table %s has %d columns but %d values were supplied",
                   t->zName, p->ins.pCols?p->ins.pCols->nExpr:t->nCol, row->nExpr);
            return 1;
          }
          if( buildInsertRow(&ev,t,p->ins.pCols,row,aVal,&nCol) ) return 1;
          for(i=0;i<t->nCol;i++) applyColAffinity(t,i,&aVal[i]);
          if( t->iPk>=0 && aVal[t->iPk].type==VT_NULL ){
            rowid = tableNextRowid(t);
            valSetInt(pA,&aVal[t->iPk],rowid);
          }else if( t->iPk>=0 ){
            rowid = aVal[t->iPk].i;
          }else{
            rowid = tableNextRowid(t);
          }
          if( checkConstraints(&ev,t,aVal,rowid,-1) ){
            if( p->ins.onConflict==4 ){ continue; }
            if( p->ins.onConflict==5 ){
              int k = tableFindKey(t,rowid);
              if( k<0 ) continue;
              tableDeleteRow(t,k);
            }else return 1;
          }
          if( fireTriggers(&ev,t,0,1,aVal,0,rowid) ) return 1;
          tableInsertRow(pDb,t,rowid,aVal);
          fireTriggers(&ev,t,1,1,aVal,0,rowid);
          pDb->changes++;
          pDb->totalChanges++;
        }
        return 0;
      }
      if( p->ins.pSelect ){
        RowBuf rb;
        char **az = 0;
        Out o;
        memset(&o,0,sizeof(o));
        rowbufInit(&rb,pA,0);
        o.pArg = &rb;
        if( selRun(&ev,p->ins.pSelect,&o,0) ) return 1;
        {
          int j;
          for(j=0;j<rb.n;j++){
            Value *aVal = arenaAlloc(pA, t->nCol*sizeof(Value));
            i64 rowid;
            int k;
            /* map the select's columns to the table columns */
            int nSrc = rb.nCol;
            for(k=0;k<t->nCol;k++) valInit(&aVal[k]);
            if( p->ins.pCols ){
              for(k=0;k<p->ins.pCols->nExpr;k++){
                int ic = colIndexOf(t, p->ins.pCols->apExpr[k]->zTok);
                if( ic>=0 && k<nSrc ){ valCopy(pA,&aVal[ic], rb.ap[j]+k); }
              }
            }else{
              for(k=0;k<t->nCol && k<nSrc;k++) valCopy(pA,&aVal[k], rb.ap[j]+k);
            }
            for(k=0;k<t->nCol;k++) applyColAffinity(t,k,&aVal[k]);
            if( t->iPk>=0 && aVal[t->iPk].type==VT_NULL ){
              rowid = tableNextRowid(t);
              valSetInt(pA,&aVal[t->iPk],rowid);
            }else if( t->iPk>=0 ){
              rowid = aVal[t->iPk].i;
            }else rowid = tableNextRowid(t);
            if( checkConstraints(&ev,t,aVal,rowid,-1) ){
              if( p->ins.onConflict==4 ) continue;
              if( p->ins.onConflict==5 ){
                int k2 = tableFindKey(t,rowid);
                if( k2>=0 ) tableDeleteRow(t,k2);
              }else return 1;
            }
            if( fireTriggers(&ev,t,0,1,aVal,0,rowid) ) return 1;
            tableInsertRow(pDb,t,rowid,aVal);
            fireTriggers(&ev,t,1,1,aVal,0,rowid);
            pDb->changes++;
            pDb->totalChanges++;
          }
        }
        return 0;
      }
      return 0;
    }
    case ST_UPDATE: {
      Table *t;
      Schema *pS;
      int i, k;
      t = dbFindTable(pDb, p->upd.zTab, p->upd.zDb, &pS);
      if( t==0 ){
        errSetPos(pErr, p->startPos, "no such table: %s", p->upd.zDb&&p->upd.zDb[0]?strPrintf("%s.%s",p->upd.zDb,p->upd.zTab):p->upd.zTab);
        return 1;
      }
      pDb->changes = 0;
      {
        int aiSet[512];
        Expr *apExpr[512];
        int nSet = p->upd.pSet?p->upd.pSet->nExpr:0;
        int *aiDel = arenaAlloc(pA,(t->nRow>0?t->nRow:1)*sizeof(int));
        int nDel = 0;
        for(i=0;i<nSet;i++){
          const char *zCol = p->upd.pSet->azName[i];
          int ic = colIndexOf(t,zCol);
          if( ic<0 ){
            errSetPos(pErr, 0, "no such column: %s", zCol);
            return 1;
          }
          aiSet[i] = ic;
          apExpr[i] = p->upd.pSet->apExpr[i];
        }
