        tableInsertRow(pDb,t,rowid,aVal);
        fireTriggers(&ev,t,1,1,aVal,0,rowid);
        pDb->changes++;
        pDb->totalChanges++;
        return 0;
      }
      if( p->ins.apRowValues ){
        for(i=0;i<p->ins.nRow;i++){
          Value *aVal = arenaAlloc(pA, t->nCol*sizeof(Value));
          i64 rowid;
          ExprList *row = p->ins.apRowValues[i];
          if( row->nExpr != (p->ins.pCols?p->ins.pCols->nExpr:t->nCol) ){
            errSet(pErr,"table %s has %d columns but %d values were supplied",
                   t->zName, p->ins.pCols?p->ins.pCols->nExpr:t->nCol, row->nExpr);
            return 1;
          }
          if( buildInsertRow(&ev,t,p->ins.pCols,row,aVal,&nCol) ) return 1;
          for(i=0;i<t->nCol;i++) applyColAffinity(t,i,&aVal[i]);
          if( t->iPk>=0 && aVal[t->iPk].type==VT_NULL ){
            rowid = tableNextRowid(t);
            valSetInt(pA,&aVal[t->iPk],rowid);
          }else if( t->iPk>=0 ){
            rowid = aVal[t->iPk].i;
          }else{
            rowid = tableNextRowid(t);
          }
          if( checkConstraints(&ev,t,aVal,rowid,-1) ){
            if( p->ins.onConflict==4 ){ continue; }
            if( p->ins.onConflict==5 ){
              int k = tableFindKey(t,rowid);
              if( k<0 ) continue;
              tableDeleteRow(t,k);
            }else return 1;
          }
          if( fireTriggers(&ev,t,0,1,aVal,0,rowid) ) return 1;
          tableInsertRow(pDb,t,rowid,aVal);
          fireTriggers(&ev,t,1,1,aVal,0,rowid);
          pDb->changes++;
          pDb->totalChanges++;
        }
        return 0;
      }
      if( p->ins.pSelect ){
        RowBuf rb;
        char **az = 0;
        Out o;
        memset(&o,0,sizeof(o));
        rowbufInit(&rb,pA,0);
        o.pArg = &rb;
        if( selRun(&ev,p->ins.pSelect,&o,0) ) return 1;
        {
          int j;
          for(j=0;j<rb.n;j++){
            Value *aVal = arenaAlloc(pA, t->nCol*sizeof(Value));
            i64 rowid;
            int k;
            /* map the select's columns to the table columns */
            int nSrc = rb.nCol;
            for(k=0;k<t->nCol;k++) valInit(&aVal[k]);
            if( p->ins.pCols ){
              for(k=0;k<p->ins.pCols->nExpr;k++){
                int ic = colIndexOf(t, p->ins.pCols->apExpr[k]->zTok);
                if( ic>=0 && k<nSrc ){ valCopy(pA,&aVal[ic], rb.ap[j]+k); }
              }
            }else{
              for(k=0;k<t->nCol && k<nSrc;k++) valCopy(pA,&aVal[k], rb.ap[j]+k);
            }
            for(k=0;k<t->nCol;k++) applyColAffinity(t,k,&aVal[k]);
            if( t->iPk>=0 && aVal[t->iPk].type==VT_NULL ){
              rowid = tableNextRowid(t);
              valSetInt(pA,&aVal[t->iPk],rowid);
            }else if( t->iPk>=0 ){
              rowid = aVal[t->iPk].i;
            }else rowid = tableNextRowid(t);
            if( checkConstraints(&ev,t,aVal,rowid,-1) ){
              if( p->ins.onConflict==4 ) continue;
              if( p->ins.onConflict==5 ){
                int k2 = tableFindKey(t,rowid);
                if( k2>=0 ) tableDeleteRow(t,k2);
              }else return 1;
            }
            if( fireTriggers(&ev,t,0,1,aVal,0,rowid) ) return 1;
            tableInsertRow(pDb,t,rowid,aVal);
            fireTriggers(&ev,t,1,1,aVal,0,rowid);
            pDb->changes++;
            pDb->totalChanges++;
          }
        }
        return 0;
      }
      return 0;
    }
    case ST_UPDATE: {
      Table *t;
      Schema *pS;
      int i, k;
      t = dbFindTable(pDb, p->upd.zTab, p->upd.zDb, &pS);
      if( t==0 ){
        errSetPos(pErr, p->startPos, "no such table: %s", p->upd.zDb&&p->upd.zDb[0]?strPrintf("%s.%s",p->upd.zDb,p->upd.zTab):p->upd.zTab);
        return 1;
      }
      pDb->changes = 0;
      {
        int aiSet[512];
        Expr *apExpr[512];
        int nSet = p->upd.pSet?p->upd.pSet->nExpr:0;
        int *aiDel = arenaAlloc(pA,(t->nRow>0?t->nRow:1)*sizeof(int));
        int nDel = 0;
        for(i=0;i<nSet;i++){
          const char *zCol = p->upd.pSet->azName[i];
          int ic = colIndexOf(t,zCol);
          if( ic<0 ){
            errSetPos(pErr, 0, "no such column: %s", zCol);
            return 1;
          }
          aiSet[i] = ic;
          apExpr[i] = p->upd.pSet->apExpr[i];
        }
        for(i=0;i<t->nRow;i++){
          Value aVal[512];
          CurRow cur;
          int width = t->nCol + 1;
          Value *flat = arenaAlloc(pA, width*sizeof(Value));
          Value v;
          int skip = 0;
          for(k=0;k<t->nCol;k++){ valInit(&flat[k]); valCopy(pA,&flat[k],t->apRow[i]->aVal+k); }
          valInit(&flat[t->nCol]);
          valSetInt(pA,&flat[t->nCol], t->apRow[i]->rowid);
          cur.apFlat = flat;
          cur.aiRowid = 0;
          ev.pScope = 0;
          ev.pCur = (void*)&cur;
          if( p->upd.pWhere ){
            valInit(&v);
            evalExpr(&ev,p->upd.pWhere,&v);
            if( !evalIsTrue(&v) ) continue;
          }
          for(k=0;k<t->nCol;k++){ valInit(&aVal[k]); valCopy(pA,&aVal[k],t->apRow[i]->aVal+k); }
          for(k=0;k<nSet;k++){
            Value nv;
            valInit(&nv);
            evalExpr(&ev,apExpr[k],&nv);
            applyColAffinity(t,aiSet[k],&nv);
            if( t->aCol[aiSet[k]].notNull && nv.type==VT_NULL ){
              errSet(pErr,"NOT NULL constraint failed: %s.%s", t->zName, t->aCol[aiSet[k]].zName);
              return 1;
            }
            valFree(&aVal[aiSet[k]]);
            aVal[aiSet[k]] = nv;
            if( aiSet[k]==t->iPk ) skip = 1;
          }
          if( checkConstraints(&ev,t,aVal,t->apRow[i]->rowid,-1) ){
            if( p->upd.orConf==4 ) continue;
            return 1;
          }
          aiDel[nDel++] = i;
          if( fireTriggers(&ev,t,0,3,aVal,t->apRow[i]->aVal,t->apRow[i]->rowid) ) return 1;
          {
            i64 rid = t->apRow[i]->rowid;
            int pos = tableFindKey(t,rid);
            if( pos>=0 ){
              tableDeleteRow(t,pos);
              tableInsertRow(pDb,t,rid,aVal);
            }
          }
          fireTriggers(&ev,t,1,3,aVal,t->apRow[i]->aVal,t->apRow[i]->rowid);
          pDb->changes++;
          pDb->totalChanges++;
          (void)skip;
        }
        (void)aiDel;
      }
      return 0;
    }
    case ST_DELETE: {
      Table *t;
      Schema *pS;
      int i;
      t = dbFindTable(pDb, p->del.zTab, p->del.zDb, &pS);
      if( t==0 ){
        errSetPos(pErr, p->startPos, "no such table: %s", p->del.zDb&&p->del.zDb[0]?strPrintf("%s.%s",p->del.zDb,p->del.zTab):p->del.zTab);
        return 1;
      }
      pDb->changes = 0;
      {
        int *aiDel = arenaAlloc(pA,(t->nRow>0?t->nRow:1)*sizeof(int));
        int nDel = 0;
        for(i=0;i<t->nRow;i++){
          Value aVal[512];
          CurRow cur;
          int width = t->nCol + 1;
          Value *flat = arenaAlloc(pA, width*sizeof(Value));
          Value v;
          int k;
          for(k=0;k<t->nCol;k++){ valInit(&flat[k]); valCopy(pA,&flat[k],t->apRow[i]->aVal+k); }
          valInit(&flat[t->nCol]);
          valSetInt(pA,&flat[t->nCol], t->apRow[i]->rowid);
          cur.apFlat = flat;
          cur.aiRowid = 0;
          ev.pScope = 0;
          ev.pCur = (void*)&cur;
          if( p->del.pWhere ){
            valInit(&v);
            evalExpr(&ev,p->del.pWhere,&v);
            if( !evalIsTrue(&v) ) continue;
          }
          for(k=0;k<t->nCol;k++){ valInit(&aVal[k]); valCopy(pA,&aVal[k],t->apRow[i]->aVal+k); }
          aiDel[nDel++] = i;
          if( fireTriggers(&ev,t,0,2,aVal,t->apRow[i]->aVal,t->apRow[i]->rowid) ) return 1;
          pDb->changes++;
          pDb->totalChanges++;
        }
        for(i=nDel-1;i>=0;i--) tableDeleteRow(t,aiDel[i]);
      }
      return 0;
    }
    default:
      errSet(pErr,"unknown statement");
      return 1;
  }
}
