}""","""    case ST_CREATE_TABLE: {
      Schema *pS = dbFindSchema(pDb, p->ct.zDb);
      Table *t;
      if( pS==0 ) pS = pDb->pMain;
      if( schemaFindTable(pS,p->ct.zTab) || schemaFindView(pS,p->ct.zTab) ){
        if( p->ct.ifNotExists ) return 0;
        errSetPos(pErr, p->startPos, "table %s already exists", p->ct.zTab);
        return 1;
      }
      if( p->ct.selectStmt ){
        /* CREATE TABLE x AS SELECT */
        RowBuf rb;
        char **az = 0;
        Out o;
        int j, k;
        memset(&o,0,sizeof(o));
        rowbufInit(&rb,pA,0);
        o.pArg = &rb;
        if( selRun(&ev,p->ct.pAsSelect,&o,0) ) return 1;
        t = malloc(sizeof(Table));
        memset(t,0,sizeof(*t));
        t->zName = strDup(p->ct.zTab);
        t->nCol = rb.nCol;
        t->aCol = malloc((rb.nCol>0?rb.nCol:1)*sizeof(Column));
        memset(t->aCol,0,rb.nCol*sizeof(Column));
        t->iPk = -1;
        t->nextRowid = 1;
        for(k=0;k<rb.nCol;k++){
          const char *zn = (az && az[k]) ? az[k] : strPrintf("column%d",k+1);
          t->aCol[k].zName = strDup(zn);
          t->aCol[k].affinity = AF_BLOB;
        }
        {
          char buf[512];
          snprintf(buf,sizeof(buf),"CREATE TABLE %s(",t->zName);
          for(k=0;k<t->nCol;k++){ if(k) strcat(buf,", "); strcat(buf,t->aCol[k].zName); }
          strcat(buf,")");
          t->zSql = strDup(buf);
        }
        t->iSchema = pS->nSchemaRowid++;
        {
          Table **pt = &pS->pTable;
          while( *pt ) pt = &(*pt)->pNextTable;
          *pt = t;
          t->pNextTable = 0;
        }
        for(j=0;j<rb.n;j++){
          Value *r = arenaAlloc(pA, rb.nCol*sizeof(Value));
          for(k=0;k<rb.nCol;k++){ valInit(&r[k]); valCopy(pA,&r[k],rb.ap[j]+k); }
          tableInsertRow(pDb,t,j+1,r);
        }
        pDb->changes = rb.n;
        pDb->totalChanges += rb.n;
        return 0;
      }
      t = makeTable(pDb,pS,p,pA,pErr);
      if( t==0 ) return 1;
      t->iSchema = pS->nSchemaRowid++;
      {
        Table **pt = &pS->pTable;
        while( *pt ) pt = &(*pt)->pNextTable;
        *pt = t;
        t->pNextTable = 0;
      }
      /* build index keys for auto indexes */
      {
        Index *x;
        for(x=t->pIndex;x;x=x->pNext) buildIndexKeys(pDb,t,x);
      }
      pDb->changes = 0;
      return 0;
    }
    case ST_CREATE_INDEX: {
      Schema *pS = dbFindSchema(pDb, p->ci.zDb);
      Table *t;
      Index *x;
      if( pS==0 ) pS = pDb->pMain;
      if( schemaFindIndex(pS,p->ci.zName) ){
        if( p->ci.ifNotExists ) return 0;
        errSetPos(pErr, p->startPos, "index %s already exists", p->ci.zName);
        return 1;
      }
      t = schemaFindTable(pS,p->ci.zTab);
      if( t==0 ){
        errSetPos(pErr,p->startPos,"no such table: %s", p->ci.zTab);
        return 1;
      }
      x = makeIndex(pDb,pS,p,pA,pErr);
      if( x==0 ) return 1;
      x->iSchema = pS->nSchemaRowid++;
      {
        Index **px = &t->pIndex;
        while( *px ) px = &(*px)->pNext;
        *px = x;
        x->pNext = 0;
      }
      buildIndexKeys(pDb,t,x);
      return 0;
    }
    case ST_CREATE_VIEW: {
      Schema *pS = dbFindSchema(pDb, p->cv.zDb);
      View *v;
      if( pS==0 ) pS = pDb->pMain;
      if( schemaFindView(pS,p->cv.zName) || schemaFindTable(pS,p->cv.zName) ){
        if( p->cv.ifNotExists ) return 0;
        errSetPos(pErr,p->startPos,"table %s already exists", p->cv.zName);
        return 1;
      }
      v = makeView(pDb,pS,p,pA,pErr);
      v->iSchema = pS->nSchemaRowid++;
      {
        View **pv = &pS->pView;
        while( *pv ) pv = &(*pv)->pNext;
        *pv = v;
        v->pNext = 0;
      }
      return 0;
    }
    case ST_CREATE_TRIGGER: {
      Schema *pS = dbFindSchema(pDb, p->ctr.zDb);
      Trigger *tr;
      if( pS==0 ) pS = pDb->pMain;
      if( schemaFindTrigger(pS,p->ctr.zName) ){
        if( p->ctr.ifNotExists ) return 0;
        errSetPos(pErr,p->startPos,"trigger %s already exists", p->ctr.zName);
        return 1;
      }
      tr = makeTrigger(pDb,pS,p,pA,pErr);
      tr->iSchema = pS->nSchemaRowid++;
      {
        Trigger **pt = &pS->pTrigger;
        while( *pt ) pt = &(*pt)->pNext;
        *pt = tr;
        tr->pNext = 0;
      }
      return 0;
    }
    case ST_DROP: {
      Schema *pS = dbFindSchema(pDb, p->drop.zDb);
      if( pS==0 ) pS = pDb->pMain;
      if( p->drop.what==0 ){
        Table *t = schemaFindTable(pS,p->drop.zName);
        if( t==0 ){
          if( p->drop.ifExists ) return 0;
          errSetPos(pErr,p->startPos,"no such table: %s", p->drop.zName);
          return 1;
        }
        {
          Table **pt = &pS->pTable;
          while( *pt ){
            if( *pt==t ){ *pt = t->pNextTable; break; }
            pt = &(*pt)->pNextTable;
          }
        }
        tableFree(t);
      }else if( p->drop.what==1 ){
        Table *t;
        Index *x = schemaFindIndex(pS,p->drop.zName);
        if( x==0 ){
          if( p->drop.ifExists ) return 0;
          errSetPos(pErr,p->startPos,"no such index: %s", p->drop.zName);
          return 1;
        }
        for(t=pS->pTable;t;t=t->pNextTable) tableRemoveIndex(t,p->drop.zName);
      }else if( p->drop.what==2 ){
        View *v = schemaFindView(pS,p->drop.zName);
        if( v==0 ){
          if( p->drop.ifExists ) return 0;
          errSetPos(pErr,p->startPos,"no such view: %s", p->drop.zName);
          return 1;
        }
        {
          View **pv = &pS->pView;
          while( *pv ){
            if( *pv==v ){ *pv = v->pNext; break; }
            pv = &(*pv)->pNext;
          }
        }
        free(v->zName); free(v->zSql); free(v);
      }else{
        Trigger *tr = schemaFindTrigger(pS,p->drop.zName);
        if( tr==0 ){
          if( p->drop.ifExists ) return 0;
          errSetPos(pErr,p->startPos,"no such trigger: %s", p->drop.zName);
          return 1;
        }
        {
          Trigger **pt = &pS->pTrigger;
          while( *pt ){
            if( *pt==tr ){ *pt = tr->pNext; break; }
            pt = &(*pt)->pNext;
          }
        }
        free(tr->zName); free(tr->zTbl); free(tr->zSql); free(tr);
      }
      pDb->changes = 0;
      return 0;
    }
    case ST_TXN: {
      if( p->txnOp==0 ){
        if( pDb->inTxn ){
          errSet(pErr,"cannot start a transaction within a transaction");
          return 1;
        }
        dbSnapshot(pDb);
        pDb->inTxn = 1;
      }else if( p->txnOp==1 ){
        if( !pDb->inTxn ){
          errSet(pErr,"cannot commit - no transaction is active");
          return 1;
        }
        pDb->inTxn = 0;
        {
          Error e2;
          memset(&e2,0,sizeof(e2));
          if( dbWriteFile(pDb,&e2) ) errSet(pErr,"%s", e2.msg);
        }
      }else if( p->txnOp==2 ){
        if( !pDb->inTxn ){
          errSet(pErr,"cannot rollback - no transaction is active");
          return 1;
        }
        dbRestoreSnapshot(pDb);
      }else if( p->txnOp==3 ){
        dbSnapshot(pDb);
      }else{
        dbRestoreSnapshot(pDb);
      }
      return 0;
    }
    case ST_VACUUM: {
      if( pDb->inTxn ){
        errSet(pErr,"cannot VACUUM from within a transaction");
        return 1;
      }
      {
        Error e2;
        memset(&e2,0,sizeof(e2));
        dbWriteFile(pDb,&e2);
      }
      return 0;
    }
    case ST_ANALYZE: return 0;
    case ST_REINDEX: return 0;
    case ST_ATTACH: return 0;
    case ST_DETACH: return 0;
    case ST_PRAGMA: {
      extern int execPragma(Db *pDb, Stmt *p, Arena *pA, Out *pOut, Error *pErr);
      return execPragma(pDb,p,pA,pOut,pErr);
    }
    default:
      errSet(pErr,"unknown statement");
      return 1;
  }
}
