{"command": "cd /workspace/src && cat > shell.c <<'SHEOF'
#include "core.h"
#include "lex.h"
#include "parse.h"
#include "db.h"
#include "exec.h"
#include "func.h"
#include "help.txt"

#define MODE_LIST 0
#define MODE_CSV 1
#define MODE_COLUMN 2
#define MODE_JSON 3
#define MODE_LINE 4
#define MODE_QUOTE 5
#define MODE_TABS 6
#define MODE_ASCII 7
#define MODE_HTML 8
#define MODE_INSERT 9
#define MODE_MARKDOWN 10
#define MODE_BOX 11
#define MODE_TABLE 12

typedef struct Shell {
  int mode;
  int headers;
  char *zColSep;
  char *zRowSep;
  char *zNull;
  FILE *out;
  FILE *outSave;
  int echo, bail, changes, timer, stats, crlf;
  Db *pDb;
  Arena *pA;
  Error err;
  Param param;
  int iLine;
  int nErr;
  int interactive;
  int bInterrupt;
  char zPrompt[128];
  char zPrompt2[128];
  char *zTabName;
  int bSafe;
  int iNonceOk;
  int oncePending;
  FILE *pOnce;
  char zOnceName[512];
  int screenWidth;
  int bTtyOut;
  int nWidth[64];
  int bWidthSet;
  int nWidthCount;
  int bEscape;
  int bHeaderDone;
  int nResCol;
  char **azResName;
  int iMode2;
} Shell;

static Shell g;

/* ============ output ============ */
static void outPut(const char *z){ fputs(z, g.out); }
static void outPutN(const char *z, int n){ fwrite(z,1,n,g.out); }
static void outNewline(void){ fputc('\n', g.out); }

/* csv/tab quoting */
static int needsCsvQuote(const char *z, int n, const char *sep){
  int i;
  for(i=0;i<n;i++){
    char c = z[i];
    if( c=='"' || c=='\n' || c=='\r' ) return 1;
    if( sep && strchr(sep,c) ) return 1;
  }
  if( n>0 && (z[0]==' '||z[n-1]==' ') ) return 1;
  return 0;
}
static void emitCsv(const char *z, int n, const char *sep){
  if( needsCsvQuote(z,n,sep) ){
    int i;
    fputc('"',g.out);
    for(i=0;i<n;i++){
      if( z[i]=='"' ) fputc('"',g.out);
      fputc(z[i],g.out);
    }
    fputc('"',g.out);
  }else outPutN(z,n);
}
static char *jsonStr(Arena *pA, const char *z, int n){
  int i, j = 0;
  char *r = arenaAlloc(pA, n*6+4);
  r[j++] = '"';
  for(i=0;i<n;i++){
    unsigned char c = z[i];
    if( c=='"' || c=='\\' ){ r[j++]='\\'; r[j++]=c; }
    else if( c=='\n' ){ r[j++]='\\'; r[j++]='n'; }
    else if( c=='\r' ){ r[j++]='\\'; r[j++]='r'; }
    else if( c=='\t' ){ r[j++]='\\'; r[j++]='t'; }
    else if( c=='\b' ){ r[j++]='\\'; r[j++]='b'; }
    else if( c=='\f' ){ r[j++]='\\'; r[j++]='f'; }
    else if( c<0x20 ){ j += snprintf(r+j,8,"\\u%04x",c); }
    else r[j++] = c;
  }
  r[j++] = '"';
  r[j] = 0;
  return r;
}

/* display width of a utf8 string */
static int dispWidth(const char *z, int n){
  int i = 0, w = 0;
  while( i<n ){
    unsigned char c = z[i];
    if( c<0x80 ){ i++; w++; }
    else if( (c&0xe0)==0xc0 ){ i+=2; w++; }
    else if( (c&0xf0)==0xe0 ){ i+=3; w++; }
    else if( (c&0xf8)==0xf0 ){ i+=4; w+=2; }
    else { i++; w++; }
  }
  return w;
}

static void emitValue(Shell *p, Value *v){
  Arena *pA = p->pA;
  if( v->type==VT_NULL ){ outPut(p->zNull); return; }
  switch( p->mode ){
    case MODE_CSV: {
      const char *z = valText(pA,v);
      emitCsv(z, v->n, p->zColSep);
      break;
    }
    case MODE_TABS: {
      const char *z = valText(pA,v);
      if( v->n>0 && (strchr(z,'\t')||strchr(z,'"')||strchr(z,'\n')) ) emitCsv(z,v->n,"\t");
      else outPutN(z,v->n);
      break;
    }
    case MODE_JSON: {
      if( v->type==VT_INT ) outPut(strPrintf("%lld",v->i));
      else if( v->type==VT_REAL ) outPut(realToText(pA,v->r));
      else if( v->type==VT_BLOB ){
        outPut(jsonStr(pA, v->z, v->n));
      }else outPut(jsonStr(pA, valText(pA,v), v->n));
      break;
