/* ============ buffered output ============ */
typedef struct OutBuf {
  Value **ap;
  int n, cap;
  int nCol;
  char **azName;
} OutBuf;
static OutBuf g_buf;

static void bufAdd(Value *aVal, int nCol, char **azName){
  Arena *pA = g.pA;
  if( g_buf.n>=g_buf.cap ){
    int nc = g_buf.cap?g_buf.cap*2:8;
    Value **ap = arenaAlloc(pA,nc*sizeof(Value*));
    if( g_buf.cap ) memcpy(ap,g_buf.ap,g_buf.n*sizeof(Value*));
    g_buf.ap = ap; g_buf.cap = nc;
  }
  {
    Value *v = arenaAlloc(pA, nCol*sizeof(Value));
    int i;
    for(i=0;i<nCol;i++){ valInit(v+i); valCopy(pA,v+i,aVal+i); }
    g_buf.ap[g_buf.n++] = v;
  }
  g_buf.nCol = nCol;
  if( azName && g_buf.azName==0 ){
    g_buf.azName = arenaAlloc(pA, nCol*sizeof(char*));
    for(i=0;i<nCol;i++) g_buf.azName[i] = azName[i] ? arenaStrdup(pA,azName[i]) : 0;
  }
}

static void outRowCb(void *pArg, Value *aVal, int nCol, char **azName){
  (void)pArg;
  if( g_buf.n==0 && azName ){
    g.azResName = arenaAlloc(g.pA, nCol*sizeof(char*));
    for(int i=0;i<nCol;i++) g.azResName[i] = azName[i]?arenaStrdup(g.pA,azName[i]):0;
    g.nResCol = nCol;
  }
  bufAdd(aVal,nCol,azName);
}

static void printBoxRow(Value **apRows, int nRow, int nCol, int *aW, int nRowIdx, int kind){
  /* kind: 0=box, 1=table */
  int j;
  if( kind==0 ) outPut("\xe2\x95\xad");
  else outPut("+");
  for(j=0;j<nCol;j++){
    int k;
    for(k=0;k<aW[j]+2;k++) outPut(kind==0?"\xe2\x94\x80":"-");
    if( j<nCol-1 ) outPut(kind==0?"\xe2\x95\xac":"+");
  }
  outPut(kind==0?"\xe2\x95\xae":"+");
  outNewline();
}
