static void flushOutput(Shell *p){
  Arena *pA = p->pA;
  OutBuf *b = &g_buf;
  int i, j;
  int nCol = b->nCol;
  int aW[256];
  if( nCol<=0 && b->n==0 ){
    /* nothing */
  }
  switch( p->mode ){
    case MODE_LIST: {
      if( p->headers && nCol>0 ){
        for(j=0;j<nCol;j++){ if(j) outPut(p->zColSep); outPut(p->azResName[j]); }
        outNewline();
      }
      for(i=0;i<b->n;i++){
        for(j=0;j<nCol;j++){
          Value *v = b->ap[i]+j;
          if(j) outPut(p->zColSep);
          if( v->type==VT_NULL ) outPut(p->zNull);
          else outPutN(valText(pA,v), v->n);
        }
        outNewline();
      }
      break;
    }
    case MODE_CSV: {
      if( p->headers && nCol>0 ){
        for(j=0;j<nCol;j++){ if(j) outPut(p->zColSep); emitCsv(p->azResName[j],(int)strlen(p->azResName[j]),p->zColSep); }
        outNewline();
      }
      for(i=0;i<b->n;i++){
        for(j=0;j<nCol;j++){
          Value *v = b->ap[i]+j;
          if(j) outPut(p->zColSep);
          if( v->type==VT_NULL ) ;
          else emitCsv(valText(pA,v),v->n,p->zColSep);
        }
        outNewline();
      }
      break;
    }
    case MODE_TABS: {
      if( p->headers && nCol>0 ){
        for(j=0;j<nCol;j++){ if(j) outPut("\t"); emitCsv(p->azResName[j],(int)strlen(p->azResName[j]),"\t"); }
        outNewline();
      }
      for(i=0;i<b->n;i++){
        for(j=0;j<nCol;j++){
          Value *v = b->ap[i]+j;
          if(j) outPut("\t");
          if( v->type==VT_NULL ) ;
          else emitCsv(valText(pA,v),v->n,"\t");
        }
        outNewline();
      }
      break;
    }
    case MODE_ASCII: {
      for(i=0;i<b->n;i++){
        for(j=0;j<nCol;j++){
          Value *v = b->ap[i]+j;
          if(j) fputc(0x1f,g.out);
          if( v->type==VT_NULL ) ;
          else outPutN(valText(pA,v), v->n);
        }
        fputc(0x1e,g.out);
      }
      break;
    }
    case MODE_JSON: {
      if( b->n==0 ){ outPut("[]"); outNewline(); break; }
      if( b->n==1 ){
        outPut("[");
        for(j=0;j<nCol;j++){
          if(j) outPut(",");
          outPut(jsonStr(pA,p->azResName[j],(int)strlen(p->azResName[j])));
          outPut(":");
          { Value t; valInit(&t); valCopy(pA,&t,b->ap[0]+j); 
            if( t.type==VT_NULL ) outPut("null");
            else if( t.type==VT_INT ) outPut(strPrintf("%lld",t.i));
            else if( t.type==VT_REAL ) outPut(realToText(pA,t.r));
            else if( t.type==VT_BLOB ) outPut(jsonStr(pA,t.z,t.n));
            else outPut(jsonStr(pA,t.z,t.n));
          }
        }
        outPut("]");
        outNewline();
      }else{
        outPut("[");
        outNewline();
        for(i=0;i<b->n;i++){
          outPut("{");
          for(j=0;j<nCol;j++){
            if(j) outPut(",");
            outPut(jsonStr(pA,p->azResName[j],(int)strlen(p->azResName[j])));
            outPut(":");
            { Value t; valInit(&t); valCopy(pA,&t,b->ap[i]+j);
              if( t.type==VT_NULL ) outPut("null");
              else if( t.type==VT_INT ) outPut(strPrintf("%lld",t.i));
              else if( t.type==VT_REAL ) outPut(realToText(pA,t.r));
              else if( t.type==VT_BLOB ) outPut(jsonStr(pA,t.z,t.n));
              else outPut(jsonStr(pA,t.z,t.n));
            }
          }
          outPut("}");
          if( i<b->n-1 ) outPut(",");
          outNewline();
        }
        outPut("]");
        outNewline();
      }
      break;
    }
    case MODE_QUOTE: {
      for(i=0;i<b->n;i++){
        for(j=0;j<nCol;j++){
          if(j) outPut(",");
          outPut(quoteSql(pA,b->ap[i]+j));
        }
        outNewline();
      }
      break;
    }
    case MODE_LINE: {
      if( p->headers && nCol>0 ){
        for(i=0;i<b->n;i++){
          for(j=0;j<nCol;j++){
            outPut(p->azResName[j]);
            outPut(": ");
            { Value *v = b->ap[i]+j; if( v->type==VT_NULL ) outPut(p->zNull); else outPutN(valText(pA,v),v->n); }
            outNewline();
          }
          outNewline();
        }
      }
      break;
    }
    case MODE_HTML: {
      if( p->headers && nCol>0 ){
        outPut("<TR>");
        outNewline();
        for(j=0;j<nCol;j++){ outPut("<TH>"); outPut(p->azResName[j]); outNewline(); }
        outPut("</TR>");
        outNewline();
      }
      for(i=0;i<b->n;i++){
        outPut("<TR>");
        outNewline();
        for(j=0;j<nCol;j++){
          outPut("<TD>");
          { Value *v = b->ap[i]+j; if( v->type==VT_NULL ) outPut("null"); else { p->mode = MODE_HTML; emitValue(p,v); } }
          outNewline();
        }
        outPut("</TR>");
        outNewline();
      }
      break;
    }
    case MODE_INSERT: {
      for(i=0;i<b->n;i++){
        outPut("INSERT INTO ");
        outPut(p->zTabName ? p->zTabName : "table");
        if( p->headers && nCol>0 ){
          outPut("(");
          for(j=0;j<nCol;j++){ if(j) outPut(","); outPut(p->azResName[j]); }
          outPut(")");
        }
        outPut(" VALUES(");
        for(j=0;j<nCol;j++){ if(j) outPut(","); outPut(quoteSql(pA,b->ap[i]+j)); }
        outPut(");");
        outNewline();
      }
      break;
    }
    case MODE_COLUMN: {
      int nMax = 1;
      colWidths(p,b->ap,b->n,nCol,aW);
      for(j=0;j<nCol;j++) if( aW[j]>nMax ) nMax = aW[j];
      if( p->headers && nCol>0 ){
        /* header row: centered */
        for(j=0;j<nCol;j++){
          const char *z = p->azResName[j];
          int w = dispWidth(z,(int)strlen(z));
          int pad = aW[j]-w;
          int left = pad/2;
          if( j ) outPut("  ");
          { int k; for(k=0;k<left;k++) fputc(' ',g.out); }
          outPutN(z,(int)strlen(z));
          { int k; for(k=0;k<pad-left;k++) fputc(' ',g.out); }
        }
        outNewline();
        for(j=0;j<nCol;j++){
          int k;
          if( j ) outPut("  ");
          for(k=0;k<aW[j];k++) fputc('-',g.out);
        }
        outNewline();
      }
      for(i=0;i<b->n;i++){
        int nLines = 1;
        int aLine[256];
        for(j=0;j<nCol;j++){
          int len = dispWidth(valText(pA,b->ap[i]+j),(b->ap[i]+j)->n);
          int chunks = aW[j]>0 ? (len+aW[j]-1)/aW[j] : 1;
          if( chunks<1 ) chunks = 1;
          aLine[j] = chunks;
          if( chunks>nLines ) nLines = chunks;
        }
        for(j=0;j<nLines;j++){
          for(int c=0;c<nCol;c++){
            Value *v = b->ap[i]+c;
            const char *z = v->type==VT_NULL ? p->zNull : valText(pA,v);
            int len = dispWidth(z, v->type==VT_NULL ? (int)strlen(p->zNull) : v->n);
            int off = aW[c]*j;
            int chunk = aW[c];
            if( off>len ) off = len;
            if( off+chunk>len ) chunk = len-off;
            if( c ) outPut("  ");
            if( off<len && chunk>0 ){
              int right = 0;
              if( v->type==VT_INT || v->type==VT_REAL ) right = aW[c] - chunk;
              { int k; for(k=0;k<right;k++) fputc(' ',g.out); }
              outPutN(z+off,chunk);
              if( !right ){ int k; for(k=0;k<aW[c]-chunk;k++) fputc(' ',g.out); }
            }else{
              int k;
              if( v->type==VT_INT || v->type==VT_REAL ){ for(k=0;k<aW[c];k++) fputc(' ',g.out); }
              else { for(k=0;k<aW[c];k++) fputc(' ',g.out); }
            }
          }
          /* trim trailing spaces */
          break;
        }
        outNewline();
      }
      break;
    }
    default: break;
  }
  g_buf.n = 0;
  g_buf.nCol = 0;
  g_buf.azName = 0;
}
