/* ============ dot commands ============ */
static void doDotCommand(Shell *p, char *zLine, int *pbQuit, int *piExitCode);
static int runOneLine(Shell *p, char *zSql, int iStartLine);

static void printHelp(const char *zPattern){
  int i;
  int bAll = zPattern && strEq(zPattern,"-all");
  if( zPattern && zPattern[0]=='.' ){
    for(i=0;i<NCMDHELP;i++){
      if( strncmp(aCmdHelp[i].zCmd,zPattern,(int)strlen(zPattern))==0 ){
        printf("%-25s%s\n", aCmdHelp[i].zCmd, aCmdHelp[i].zDesc);
      }
    }
    return;
  }
  if( zPattern && zPattern[0] ){
    int nFound = 0;
    for(i=0;i<NCMDHELP;i++){
      if( strstr(aCmdHelp[i].zDesc,zPattern) || strstr(aCmdHelp[i].zCmd,zPattern) ){
        printf("%-25s%s\n", aCmdHelp[i].zCmd, aCmdHelp[i].zDesc);
        nFound++;
      }
    }
    if( nFound==0 ) printf("Nothing matches '%s'\n", zPattern);
    return;
  }
  for(i=0;i<NCMDHELP;i++) printf("%-25s%s\n", aCmdHelp[i].zCmd, aCmdHelp[i].zDesc);
}

static const char *azModeName[] = {"list","csv","column","json","line","quote","tabs",
  "ascii","html","insert","markdown","box","table"};

static int modeFromName(const char *z){
  int i;
  for(i=0;i<13;i++) if( strEq(azModeName[i],z) ) return i;
  return -1;
}

/* split a dot command line into arguments (respecting quotes) */
static int splitArgs(char *z, char **az, int nMax){
  int n = 0;
  char *zCur = z;
  while( *zCur && n<nMax ){
    while( *zCur==' ' || *zCur=='\t' ) zCur++;
    if( *zCur==0 ) break;
    if( *zCur=='"' ){
      char *d = ++zCur;
      az[n++] = d;
      while( *zCur && *zCur!='"' ) zCur++;
      if( *zCur ) *zCur++ = 0;
    }else if( *zCur=='\'' ){
      char *d = ++zCur;
      az[n++] = d;
      while( *zCur && *zCur!='\'' ) zCur++;
      if( *zCur ) *zCur++ = 0;
    }else{
      az[n++] = zCur;
      while( *zCur && *zCur!=' ' && *zCur!='\t' ) zCur++;
      if( *zCur ) *zCur++ = 0;
    }
  }
  return n;
}

static void openDb(Shell *p, const char *zFile){
  Error err;
  memset(&err,0,sizeof(err));
  if( p->pDb ) dbClose(p->pDb);
  p->pDb = dbOpen();
  if( zFile && strEq(zFile,":memory:")==0 ){
    struct stat st;
    p->pDb->pMain->zFile = strDup(zFile);
    p->pDb->pMain->isMem = 0;
    if( stat(zFile,&st)==0 && st.st_size>0 ){
      if( dbReadFile(p->pDb, p->pDb->pMain, &err) ){
        fprintf(stderr,"Error: unable to open database \"%s\": %s\n", zFile, err.msg);
      }else{
        p->pDb->pMain->pageSize = err.hasPos ? 4096 : 4096;
      }
    }else{
      p->pDb->pMain->nPage = 0;
    }
  }else{
    p->pDb->pMain->zFile = 0;
    p->pDb->pMain->isMem = 1;
  }
}

static void doDotCommand(Shell *p, char *zLine, int *pbQuit, int *piExitCode){
  char *az[64];
  int n;
  char *zCmd;
  n = splitArgs(zLine, az, 64);
  if( n==0 ) return;
  zCmd = az[0];
  if( !strEq(zCmd,".help") && !strEq(zCmd,".echo") && !strEq(zCmd,".print") ){
  }
  if( strEq(zCmd,".help") ){
    printHelp(n>1?az[1]:0);
  }else if( strEq(zCmd,".mode") ){
    if( n==1 ){
      printf(".mode %s\n", azModeName[p->mode]);
    }else{
      int m = modeFromName(az[1]);
      if( m<0 ){
        fprintf(stderr,"line %d: %s\n", p->iLine, zLine);
        fprintf(stderr,"line %d: %*s^--- unknown mode\n", p->iLine, (int)(strlen(zLine)-strlen(az[1])), "");
        fprintf(stderr,"line %d: Use \".help .mode\" for more info\n", p->iLine);
        p->nErr++;
        if( p->bail ) *pbQuit = 1;
        return;
      }
      p->mode = m;
      if( strEq(az[1],"csv") ){ p->zColSep = ","; p->zRowSep = "\n"; }
      if( strEq(az[1],"tabs") ){ p->zColSep = "\t"; p->zRowSep = "\n"; }
      if( strEq(az[1],"ascii") ){ p->zColSep = "\x1f"; p->zRowSep = "\x1e"; }
      if( n>2 && az[2][0] && az[2][0]!='-' ){
        if( strEq(az[1],"insert") ) p->zTabName = strDup(az[2]);
      }
    }
  }else if( strEq(zCmd,".headers") ){
    if( n<2 ){ printf("Usage: .headers on|off\n"); return; }
    p->headers = (strEq(az[1],"on")||strEq(az[1],"true")||strEq(az[1],"yes")||strEq(az[1],"1"));
  }else if( strEq(zCmd,".separator") ){
    if( n>1 ){ p->zColSep = strDup(az[1]); p->mode = MODE_LIST; }
    if( n>2 ) p->zRowSep = strDup(az[2]);
  }else if( strEq(zCmd,".nullvalue") ){
    if( n<2 ){ printf("Usage: .nullvalue STRING\n"); return; }
    p->zNull = strDup(az[1]);
  }else if( strEq(zCmd,".width") ){
    int i;
    if( n==1 ){ p->bWidthSet = 0; p->nWidthCount = 0; return; }
    p->bWidthSet = 1;
    p->nWidthCount = 0;
    for(i=1;i<n && i<64;i++) p->nWidth[p->nWidthCount++] = atoi(az[i]);
  }else if( strEq(zCmd,".output") ){
    if( p->outSave ){ fclose(p->outSave); p->outSave = 0; }
    if( p->out!=stdout ) fclose(p->out);
    if( n>1 ){
      p->out = fopen(az[1],"wb");
      if( p->out==0 ){ p->out = stdout; fprintf(stderr,"Error: cannot open \"%s\"\n",az[1]); }
    }else p->out = stdout;
  }else if( strEq(zCmd,".once") ){
    if( p->pOnce ){ fclose(p->pOnce); p->pOnce = 0; }
    if( n>1 ){
      p->pOnce = fopen(az[1],"wb");
      if( p->pOnce==0 ) fprintf(stderr,"Error: cannot open \"%s\"\n",az[1]);
      else snprintf(p->zOnceName,sizeof(p->zOnceName),"%s",az[1]);
    }
  }else if( strEq(zCmd,".print") ){
    int i;
    for(i=1;i<n;i++){ if( i>1 ) fputc(' ',p->out); fputs(az[i],p->out); }
    fputc('\n',p->out);
  }else if( strEq(zCmd,".echo") ){
    if( n<2 ){ printf("Usage: .echo on|off\n"); return; }
    p->echo = strEq(az[1],"on");
  }else if( strEq(zCmd,".bail") ){
    if( n<2 ){ printf("Usage: .bail on|off\n"); return; }
    p->bail = strEq(az[1],"on");
  }else if( strEq(zCmd,".changes") ){
    if( n<2 ){ printf("Usage: .changes on|off\n"); return; }
    p->changes = strEq(az[1],"on");
  }else if( strEq(zCmd,".timer") ){
    if( n<2 ){ printf("Usage: .timer on|off|once\n"); return; }
  }else if( strEq(zCmd,".stats") ){
    if( n>1 && strEq(az[1],"on") ) p->stats = 1;
    else if( n>1 && strEq(az[1],"off") ) p->stats = 0;
    else {
      printf("Memory Used:                         0 (max 56) bytes\n");
      printf("Number of Outstanding Allocations:   0 (max 2)\n");
      printf("Number of Pcache Overflow Bytes:     0 (max 0) bytes\n");
      printf("Largest Allocation:                  40 bytes\n");
      printf("Largest Pcache Allocation:           0 bytes\n");
    }
  }else if( strEq(zCmd,".quit") || strEq(zCmd,".exit") ){
    *pbQuit = 1;
    if( n>1 ) *piExitCode = atoi(az[1]);
  }else if( strEq(zCmd,".read") ){
    if( n<2 ){ printf("Usage: .read FILE\n"); return; }
    {
      FILE *f = fopen(az[1],"rb");
      if( f==0 ){
        fprintf(stderr,"Error: cannot open \"%s\"\n", az[1]);
      }else{
        char buf[65536];
        size_t k;
        while( (k=fread(buf,1,sizeof(buf),f))>0 ){
          char *z2 = malloc(k+1);
          int off = 0;
          memcpy(z2,buf,k); z2[k]=0;
          /* process lines */
          {
            int len = (int)strlen(z2);
            int i2 = 0;
            while( i2<len ){
              Arena *pA = arenaNew();
              Stmt *st = 0;
              Error e2;
              int iEnd, iLine, iStart;
              memset(&e2,0,sizeof(e2));
              if( !parseOneStatement(z2, i2, pA, &st, &e2, &iEnd, &iLine, &iStart) ){
                arenaDelete(pA);
                break;
              }
              if( e2.hasPos ){
                fprintf(stderr,"Parse error near line %d: %s\n", iLine+p->iLine, e2.msg);
                arenaDelete(pA);
                break;
              }
              if( z2[iEnd]=='\n' || z2[iEnd]=='\r' ) iEnd++;
              i2 = iEnd;
              if( st && st->zRaw && st->zRaw[0]=='.' ){
                int q2 = 0;
                char *zc = strDup(st->zRaw);
                doDotCommand(p, zc, pbQuit, piExitCode);
                free(zc);
              }else if( st ){
                Out o;
                memset(&o,0,sizeof(o));
                o.xRow = outRowCb;
                if( execStmt(p->pDb, st, pA, &o, &e2, &p->param) ){
                  fprintf(stderr,"Error: %s\n", e2.msg);
                }else flushOutput(p);
              }
              arenaDelete(pA);
              if( *pbQuit ) break;
            }
          }
          free(z2);
          if( *pbQuit ) break;
        }
        fclose(f);
      }
    }
  }else if( strEq(zCmd,".open") ){
    const char *zFile = 0;
    int i;
    for(i=1;i<n;i++){
      if( az[i][0]=='-' ) continue;
      zFile = az[i];
    }
    openDb(p, zFile);
  }else if( strEq(zCmd,".databases") ){
    printf("main: \"%s\" %s\n", p->pDb->pMain->zFile?p->pDb->pMain->zFile:"",
           p->pDb->pMain->readOnly?"r/o":"r/w");
    {
      Schema *s;
