static void printHelp(const char *zPattern){
  int i;
  int bAll = zPattern && strEq(zPattern,"-all");
  if( zPattern && zPattern[0]=='.' ){
    for(i=0;i<NCMDHELP;i++){
      if( strncmp(aCmdHelp[i].zCmd,zPattern,(int)strlen(zPattern))==0 ){
        printf("%-25s%s\n", aCmdHelp[i].zCmd, aCmdHelp[i].zDesc);
      }
    }
    return;
  }
  if( zPattern && zPattern[0] ){
    int nFound = 0;
    for(i=0;i<NCMDHELP;i++){
      if( strstr(aCmdHelp[i].zDesc,zPattern) || strstr(aCmdHelp[i].zCmd,zPattern) ){
        printf("%-25s%s\n", aCmdHelp[i].zCmd, aCmdHelp[i].zDesc);
        nFound++;
      }
    }
    if( nFound==0 ) printf("Nothing matches '%s'\n", zPattern);
    return;
  }
  for(i=0;i<NCMDHELP;i++) printf("%-25s%s\n", aCmdHelp[i].zCmd, aCmdHelp[i].zDesc);
}

static const char *azModeName[] = {"list","csv","column","json","line","quote","tabs",
  "ascii","html","insert","markdown","box","table"};

static int modeFromName(const char *z){
  int i;
  for(i=0;i<13;i++) if( strEq(azModeName[i],z) ) return i;
  return -1;
}

/* split a dot command line into arguments (respecting quotes) */
static int splitArgs(char *z, char **az, int nMax){
  int n = 0;
  char *zCur = z;
  while( *zCur && n<nMax ){
    while( *zCur==' ' || *zCur=='\t' ) zCur++;
    if( *zCur==0 ) break;
    if( *zCur=='"' ){
      char *d = ++zCur;
      az[n++] = d;
      while( *zCur && *zCur!='"' ) zCur++;
      if( *zCur ) *zCur++ = 0;
    }else if( *zCur=='\'' ){
      char *d = ++zCur;
      az[n++] = d;
      while( *zCur && *zCur!='\'' ) zCur++;
      if( *zCur ) *zCur++ = 0;
    }else{
      az[n++] = zCur;
      while( *zCur && *zCur!=' ' && *zCur!='\t' ) zCur++;
      if( *zCur ) *zCur++ = 0;
    }
  }
  return n;
}

static void openDb(Shell *p, const char *zFile){
  Error err;
  memset(&err,0,sizeof(err));
  if( p->pDb ) dbClose(p->pDb);
  p->pDb = dbOpen();
  if( zFile && strEq(zFile,":memory:")==0 ){
    struct stat st;
    p->pDb->pMain->zFile = strDup(zFile);
    p->pDb->pMain->isMem = 0;
    if( stat(zFile,&st)==0 && st.st_size>0 ){
      if( dbReadFile(p->pDb, p->pDb->pMain, &err) ){
        fprintf(stderr,"Error: unable to open database \"%s\": %s\n", zFile, err.msg);
      }else{
        p->pDb->pMain->pageSize = err.hasPos ? 4096 : 4096;
      }
    }else{
      p->pDb->pMain->nPage = 0;
    }
  }else{
    p->pDb->pMain->zFile = 0;
    p->pDb->pMain->isMem = 1;
  }
}

static void doDotCommand(Shell *p, char *zLine, int *pbQuit, int *piExitCode){
  char *az[64];
  int n;
  char *zCmd;
  n = splitArgs(zLine, az, 64);
