/* ============ error reporting ============ */
static void reportError(Shell *p, const char *zStmt, Error *e, int iLine, const char *zFile){
  if( e->code!=0 ){
    if( zFile ) fprintf(stderr,"Error near line %d of %s: %s\n", iLine, zFile, e->msg);
    else fprintf(stderr,"Error near line %d: %s\n", iLine, e->msg);
    return;
  }
  if( zFile ) fprintf(stderr,"Parse error near line %d of %s: %s\n", iLine, zFile, e->msg);
  else fprintf(stderr,"Parse error near line %d: %s\n", iLine, e->msg);
  if( e->hasPos && e->pos>0 && zStmt ){
    fprintf(stderr,"  %s\n", zStmt);
    if( e->pos<=23 ){
      fprintf(stderr,"  %*s^--- error here\n", e->pos, "");
    }else{
      fprintf(stderr,"  %*serror here ---^\n", e->pos-14, "");
    }
  }
}

/* process a buffer of statements */
static int processBuf(Shell *p, char *zBuf, const char *zFile, int *piLineBase){
  int off = 0;
  int len = (int)strlen(zBuf);
  int rc = 0;
  int prevOff;
  if( len==0 ) return 0;
  do{
    Arena *pA = arenaNew();
    Stmt *st = 0;
    Error e;
    int iEnd, iLine, iStart;
    char *zStmtText;
    memset(&e,0,sizeof(e));
    prevOff = off;
    if( !parseOneStatement(zBuf, off, pA, &st, &e, &iEnd, &iLine, &iStart) ){
      arenaDelete(pA);
      break;
    }
    zStmtText = st ? arenaStrndup(pA, st->zRaw?st->zRaw:zBuf+off, st->zRaw?(int)strlen(st->zRaw):iEnd-off) : 0;
    if( e.hasPos ){
      reportError(p, zBuf+off, &e, iLine, zFile);
      arenaDelete(pA);
      rc = 1;
      break;
    }
    if( st && st->zRaw && st->zRaw[0]=='.' ){
      int q = 0, ex = 0;
      char *zc = strDup(st->zRaw);
      doDotCommand(p, zc, &q, &ex);
      free(zc);
      if( q ){ arenaDelete(pA); break; }
    }else if( st && st->isExplain ){
      /* EXPLAIN: run the statement but produce no output */
      Out o;
      memset(&o,0,sizeof(o));
      o.xRow = outRowCb;
      if( execStmt(p->pDb, st, pA, &o, &e, &p->param) ){
        reportError(p, zStmtText, &e, iLine, zFile);
        rc = 1;
        if( p->bail ) break;
      }
    }else if( st ){
      Out o;
      memset(&o,0,sizeof(o));
      o.xRow = outRowCb;
      if( execStmt(p->pDb, st, pA, &o, &e, &p->param) ){
        reportError(p, zStmtText, &e, iLine, zFile);
        rc = 1;
        if( p->bail ) { arenaDelete(pA); break; }
      }else{
        flushOutput(p);
        if( p->changes ){
          printf("changes: %d   total_changes: %d\n", p->pDb->changes, p->pDb->totalChanges);
        }
      }
    }
    arenaDelete(pA);
    if( off<=prevOff ) break;
    if( off>=len ) break;
  }while(1);
  return rc;
}

