  const char *zFile = 0;
  int nSql = 0;
  char *azSql[64];
  int bBail = 0, bBatch = 0, bInteractive = 0;
  const char *zInit = 0;
  int bNoInit = 0;
  int bVersion = 0, bHelp = 0;
  char *zCmds[32];
  int nCmds = 0;
  int bOpts = 1;
  int iExit = 0;
  int bQuit = 0;
  int bTty = isatty(0);
  memset(&g,0,sizeof(g));
  arenaInit(&g.a);
  g.pA = &g.a;
  g.mode = MODE_LIST;
  g.headers = 0;
  g.zColSep = "|";
  g.zRowSep = "\n";
  g.zNull = "";
  g.out = stdout;
  g.bail = 0;
  g.pDb = 0;
  snprintf(g.zPrompt,sizeof(g.zPrompt),"SQLite in-memory> ");
  snprintf(g.zPrompt2,sizeof(g.zPrompt2),"%*s",17,"...");
  /* build continuation prompt */
  {
    int n = (int)strlen(g.zPrompt);
    char tmp[64];
    snprintf(tmp,sizeof(tmp),"...;>");
    snprintf(g.zPrompt2,sizeof(g.zPrompt2),"%*s%s", n-(int)strlen(tmp), "", tmp);
  }
  for(i=1;i<argc;i++){
    char *z = argv[i];
    if( bOpts && z[0]=='-' && z[1]!=0 ){
      if( strEq(z,"--") ){ bOpts = 0; continue; }
      if( strEq(z,"-help") || strEq(z,"--help") ){ bHelp = 1; continue; }
      if( strEq(z,"-version") || strEq(z,"--version") ){
        printf("3.54.0 2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b (64-bit)\n");
        return 0;
      }
      if( strEq(z,"-bail") ){ g.bail = 1; continue; }
      if( strEq(z,"-batch") ){ bBatch = 1; continue; }
      if( strEq(z,"-interactive") ){ bInteractive = 1; continue; }
      if( strEq(z,"-echo") ){ g.echo = 1; continue; }
      if( strEq(z,"-noinit") ){ bNoInit = 1; continue; }
      if( strEq(z,"-header") ){ g.headers = 1; continue; }
      if( strEq(z,"-noheader") || strEq(z,"-no-header") ){ g.headers = 0; continue; }
      if( strEq(z,"-init") ){ if( i+1<argc ) zInit = argv[++i]; continue; }
      if( strEq(z,"-cmd") ){ if( i+1<argc && nCmds<32 ) zCmds[nCmds++] = argv[++i]; continue; }
      if( strEq(z,"-csv") ){ g.mode = MODE_CSV; continue; }
      if( strEq(z,"-column") ){ g.mode = MODE_COLUMN; continue; }
      if( strEq(z,"-html") ){ g.mode = MODE_HTML; continue; }
      if( strEq(z,"-line") ){ g.mode = MODE_LINE; continue; }
      if( strEq(z,"-list") ){ g.mode = MODE_LIST; continue; }
      if( strEq(z,"-quote") ){ g.mode = MODE_QUOTE; continue; }
      if( strEq(z,"-tabs") ){ g.mode = MODE_TABS; continue; }
      if( strEq(z,"-ascii") ){ g.mode = MODE_ASCII; continue; }
      if( strEq(z,"-json") ){ g.mode = MODE_JSON; continue; }
      if( strEq(z,"-markdown") ){ g.mode = MODE_MARKDOWN; continue; }
      if( strEq(z,"-box") ){ g.mode = MODE_BOX; continue; }
      if( strEq(z,"-table") ){ g.mode = MODE_TABLE; continue; }
      if( strEq(z,"-separator") ){ if( i+1<argc ){ g.zColSep = argv[++i]; g.mode = MODE_LIST; } continue; }
      if( strEq(z,"-newline") ){ if( i+1<argc ) g.zRowSep = argv[++i]; continue; }
      if( strEq(z,"-nullvalue") ){ if( i+1<argc ) g.zNull = argv[++i]; continue; }
      if( strEq(z,"-stats") ){ g.stats = 1; continue; }
      if( strEq(z,"-readonly") ){ g.bSafe = 0; continue; }
      if( strEq(z,"-safe") ){ g.bSafe = 1; continue; }
      if( strEq(z,"-A") || strEq(z,"-archive") ){
        /* archive mode */
        return 0;
      }
      if( strEq(z,"-screenwidth") ){ if( i+1<argc ) g.screenWidth = atoi(argv[++i]); continue; }
      /* ignore unknown options */
      continue;
    }
    if( zFile==0 ){ zFile = z; continue; }
    if( nSql<64 ) azSql[nSql++] = z;
  }
  if( bHelp ){ usage(); return 0; }
  if( bVersion ){ return 0; }
  openDb(&g, zFile);
  /* run -init file */
  if( zInit ){
    FILE *f = fopen(zInit,"rb");
    if( f ){
      char *zBuf;
      long n;
      fseek(f,0,SEEK_END); n = ftell(f); fseek(f,0,SEEK_SET);
      zBuf = malloc(n+2);
      if( fread(zBuf,1,n,f)!=(size_t)n ) n = 0;
      zBuf[n] = 0;
      fclose(f);
      processBuf(&g, zBuf, zInit, &i);
      free(zBuf);
    }
  }
  /* run -cmd */
  for(i=0;i<nCmds;i++){
    processBuf(&g, zCmds[i], 0, &i);
  }
  /* run SQL args */
  for(i=0;i<nSql;i++){
    Error e;
    Arena *pA = arenaNew();
    Stmt *st = 0;
    int iEnd, iLine, iStart;
    memset(&e,0,sizeof(e));
    if( !parseOneStatement(azSql[i], 0, pA, &st, &e, &iEnd, &iLine, &iStart) ){
      arenaDelete(pA);
      continue;
    }
    if( e.hasPos ){
      fprintf(stderr,"Parse error in %s command line argument: %s\n",
              i==0?"1st":(i==1?"2nd":(i==2?"3rd":"nth")), e.msg);
      arenaDelete(pA);
      iExit = 1;
      if( g.bail ) break;
      continue;
    }
    if( st && st->zRaw && st->zRaw[0]=='.' ){
      int q = 0;
      char *zc = strDup(st->zRaw);
      doDotCommand(&g, zc, &q, &iExit);
      free(zc);
    }else if( st ){
      Out o;
      memset(&o,0,sizeof(o));
      o.xRow = outRowCb;
      if( execStmt(g.pDb, st, pA, &o, &e, &g.param) ){
        fprintf(stderr,"Error in %s command line argument: %s\n", i==0?"1st":"2nd", e.msg);
        iExit = 1;
        if( g.bail ) { arenaDelete(pA); break; }
      }else{
        flushOutput(&g);
      }
    }
    arenaDelete(pA);
  }
  if( nSql==0 || bInteractive || (bTty && nSql==0) ){
    /* read from stdin */
    char *zLine = 0;
    size_t cap = 0;
    char zAcc[65536];
    int nAcc = 0;
    int bInteractive = bTty;
    if( bInteractive && zFile==0 ){
      printf("SQLite version 3.54.0 2026-04-14 20:02:49\n");
      printf("Enter \".help\" for usage hints.\n");
      printf("Connected to a transient in-memory database.\n");
      printf("Use \".open FILENAME\" to reopen on a persistent database.\n");
    }else if( bInteractive ){
      printf("SQLite version 3.54.0 2026-04-14 20:02:49\n");
      printf("Enter \".help\" for usage hints.\n");
    }
    for(;;){
      int c;
      if( bInteractive ){
        fputs(nAcc>0 ? g.zPrompt2 : g.zPrompt, stdout);
        fflush(stdout);
      }
      zLine = 0; cap = 0;
      {
        size_t n = 0;
        int ch;
        while( (ch = fgetc(stdin))!=EOF && ch!='\n' ){
          if( n+2>cap ){ cap = cap?cap*2:256; zLine = realloc(zLine,cap); }
          zLine[n++] = (char)ch;
        }
        if( zLine==0 && ch==EOF ) break;
        if( zLine==0 ){ zLine = malloc(1); }
        zLine[n] = 0;
      }
      if( g.echo && zLine[0] ) printf("%s\n", zLine);
      /* accumulate until a statement completes */
      {
        int done = 0;
        int k;
        if( nAcc + (int)strlen(zLine) + 2 >= (int)sizeof(zAcc) ){
          nAcc = 0;
        }
        memcpy(zAcc+nAcc, zLine, strlen(zLine));
        nAcc += (int)strlen(zLine);
        zAcc[nAcc++] = '\n';
        zAcc[nAcc] = 0;
        /* check whether the accumulated buffer holds a complete statement */
        {
          Arena *pA = arenaNew();
          Stmt *st = 0;
          Error e;
          int iEnd = -1, iLine2 = 0, iStart = 0;
          memset(&e,0,sizeof(e));
          if( parseOneStatement(zAcc, 0, pA, &st, &e, &iEnd, &iLine2, &iStart) ){
            if( iEnd>0 && (zAcc[iEnd]==';' || zAcc[iEnd]==0 || iEnd>=(int)strlen(zAcc)) ) done = 1;
            if( e.hasPos ) done = 1;
          }else{
            done = 1;
          }
          arenaDelete(pA);
          if( !done ){
            free(zLine);
            continue;
          }
        }
        (void)k;
      }
      processBuf(&g, zAcc, zFile, &i);
      nAcc = 0;
      free(zLine);
      if( bQuit ) break;
      if( feof(stdin) ) break;
    }
  }
  /* write out the database if modified */
  {
    Error e;
    memset(&e,0,sizeof(e));
    if( g.pDb && g.pDb->pMain && g.pDb->pMain->zFile && !g.pDb->inTxn ){
      if( dbWriteFile(g.pDb,&e) ){
        fprintf(stderr,"Error: %s\n", e.msg);
        iExit = 1;
      }
    }
  }
  fflush(stdout);
  return iExit;
}
