{"command": "cd /workspace/src && python3 - <<'PY'
p=open('parse.c').read()
core1 = r'''static Select *pxSelectCore1(Parse *p){
  Select *s = arenaAlloc(p->pA, sizeof(Select));
  memset(s, 0, sizeof(*s));
  s->startPos = p->startPos;
  if( pxIs(p, TK_SELECT) ){
    pxGet(p);
    if( pxIs(p, TK_DISTINCT) ){ s->isDistinct = 1; pxGet(p); }
    else if( pxIs(p, TK_ALL) ){ pxGet(p); }
    s->pEList = pxResultList(p);
    if( pxIs(p, TK_FROM) ){
      pxGet(p);
      s->pSrc = pxSrcList(p);
    }
    if( pxIs(p, TK_WHERE) ){
      pxGet(p);
      s->pWhere = pxExpr(p);
    }
    if( pxIs(p, TK_GROUP) ){
      pxGet(p);
      pxExpect(p, TK_BY);
      s->pGroupBy = pxExprList0(p, 0, 0);
      if( s->pGroupBy==0 ) s->pGroupBy = pxNewList(p);
      if( pxIs(p, TK_HAVING) ){
        pxGet(p);
        s->pHaving = pxExpr(p);
      }
    }
    if( pxIs(p, TK_WINDOW) ){
      pxGet(p);
      s->aWin = arenaAlloc(p->pA, 8*sizeof(struct WinDef));
      do{
        if( !pxIsIdOrKw(p) ){ pxSyntaxError(p); return s; }
        s->aWin[s->nWin].zName = pxIdText(p);
        pxGet(p);
        pxExpect(p, TK_AS);
        s->aWin[s->nWin].pWin = pxWindow(p);
        s->nWin++;
      }while( pxAccept(p, TK_COMMA) );
    }
  }else if( pxIs(p, TK_VALUES) ){
    pxGet(p);
    s->pEList = pxNewList(p);
    s->flags |= 0x1000;
    do{
      ExprList *row;
      pxExpect(p, TK_LP);
      row = pxExprList0(p, 0, 0);
      if( row==0 ) row = pxNewList(p);
      pxExpect(p, TK_RP);
      {
        Expr *e = pxNewExpr(p, TKX_VALUELIST);
        e->pList = row;
        pxListAppend(p, s->pEList, e, 0, 0);
      }
    }while( pxAccept(p, TK_COMMA) );
  }else{
    pxSyntaxError(p);
    return s;
  }
  return s;
}

static Select *pxSelectCore(Parse *p, int *pCompound){'''
p=p.replace("static Select *pxSelectCore(Parse *p, int *pCompound){\n  Select *head = 0, *tail = 0;", core1)
