    for(i=0;i<n;i++){
      for(a=0;a<nk;a++){
        Expr *e = po->apExpr[a];
        Value *kv = k2->ap[i]+a;
        if( kv->type!=VT_NULL ) continue;
        if( e->op==TKX_INT ){
          int c = (int)e->v.i-1;
          if( c>=0 && c<rb.nCol ) valCopy(p->pA,kv,rb.ap[i]+c);
        }else if( e->op==TKX_COLUMN && e->zTok2==0 ){
          int found = -1;
          for(b=0;b<rb.nCol;b++){
            if( azNames && azNames[b] && strEq(azNames[b],e->zTok) ){ found=b; break; }
