function.arguments:
{"command": "cd /workspace/src && python3 - <<'PY'
c=open('exec.c').read()
i=c.index("  /* ORDER BY */")
j=c.index("  /* LIMIT / OFFSET */")
new = r'''  /* ORDER BY */
  if( s->pOrderBy && s->pOrderBy->nExpr>0 ){
    RowBuf *k2 = &kb;
    ExprList *po = s->pOrderBy;
    int nk = po->nExpr;
    int n = rb.n;
    int *aiDesc = arenaAlloc(p->pA, nk*sizeof(int));
    int *aiIdx = arenaAlloc(p->pA, (n>0?n:1)*sizeof(int));
    int a, b;
    for(i=0;i<nk;i++) aiDesc[i] = po->aiSortOrder[i];
    for(i=0;i<n;i++){
      for(a=0;a<nk;a++){
        Expr *e = po->apExpr[a];
        Value *kv = k2->ap[i]+a;
        if( kv->type!=VT_NULL ) continue;
        if( e->op==TKX_INT ){
          int c = (int)e->v.i-1;
          if( c>=0 && c<rb.nCol ) valCopy(p->pA,kv,rb.ap[i]+c);
        }else if( e->op==TKX_COLUMN && e->zTok2==0 ){
          int found = -1;
          for(b=0;b<rb.nCol;b++){
            if( azNames && azNames[b] && strEq(azNames[b],e->zTok) ){ found=b; break; }
          }
          if( found>=0 ) valCopy(p->pA,kv,rb.ap[i]+found);
        }
      }
    }
    for(i=0;i<n;i++) aiIdx[i] = i;
    for(i=1;i<n;i++){
      int x = aiIdx[i];
      int jj = i-1;
      while( jj>=0 ){
        int c = 0, q;
        for(q=0;q<nk;q++){
          c = valCmp(k2->ap[aiIdx[jj]]+q, k2->ap[x]+q);
          if( aiDesc[q] ) c = -c;
          if( c==0 ) continue;
          break;
        }
        if( c>0 ) jj--; else break;
      }
      for(a=i;a>jj+1;a--) aiIdx[a] = aiIdx[a-1];
      aiIdx[jj+1] = x;
    }
    {
      RowBuf tmp;
      rowbufInit(&tmp,p->pA,rb.nCol);
      for(i=0;i<n;i++) rowbufAppend(&tmp,rb.ap[aiIdx[i]],0);
      rb = tmp;
    }
  }
'''
c=c[:i]+new+c[j:]
open('exec.c','w').write(c)
PY
cd /workspace && ./dev.sh 2>&1|grep -E "error"|head -3; cd build && ./sqlite3 < /tmp/big1.sql 2>&1 | sed -n '5,10p'"}

