actions.command:
cd /workspace/src && python3 - <<'PY'
c=open('exec.c').read()
# add mkTableScope helper after scopeAddTable
c=c.replace("""/* find a column in a scope */""","""static Scope *mkTableScope(Eval *p, Table *t){
  Scope *s = scopeNew(p, (Scope*)p->pScope);
  scopeAddTable(s, t->zName, t);
  return s;
}

/* find a column in a scope */""")
# views in buildScope
c=c.replace("""      t = cteFind(p, it->zTab);
      if( g_bDbg ) fprintf(stderr,"DBG src %s cte=%p nrow=%d ncol=%d\\n", it->zTab, (void*)t, t?t->nRow:-1, t?t->nCol:-1);
      if( t==0 ) t = dbFindTable(p->pDb, it->zTab, it->zDb, 0);
      if( t==0 ){
        errSetPos(p->pErr, s->startPos, "no such table: %s", it->zTab);
        return 1;
      }
      scopeAddTable(pScope, it->zAlias?it->zAlias:it->zTab, t);""","""      t = cteFind(p, it->zTab);
      if( t==0 ) t = dbFindTable(p->pDb, it->zTab, it->zDb, 0);
      if( t==0 ){
        /* try a view */
        Schema *pVS = dbFindSchema(p->pDb, it->zDb);
        View *pv;
        if( pVS==0 ) pVS = p->pDb->pMain;
        pv = schemaFindView(pVS, it->zTab);
        if( pv ){
          Arena *pA2 = arenaNew();
          Error e3;
          Stmt *st = reparse(pA2, pv->zSql, &e3);
          if( st && st->kind==ST_CREATE_VIEW ){
            Out o3;
            RowBuf *rb2 = arenaAlloc(p->pA, sizeof(RowBuf));
            Eval sub = *p;
            char **azCol;
            memset(&o3,0,sizeof(o3));
            rowbufInit(rb2, p->pA, 1);
            o3.xRow = rowToBufCb;
            o3.pArg = rb2;
            sub.pCur = 0;
            sub.iDepth = p->iDepth+1;
            sub.pA = pA2;
            if( selRun(&sub, st->cv.pSelect, &o3, pScope) ){
              arenaDelete(pA2);
              return 1;
            }
            {
              int k;
              nCol = rb2->nCol;
              azCol = arenaAlloc(p->pA, (nCol>0?nCol:1)*sizeof(char*));
              for(k=0;k<nCol;k++) azCol[k] = arenaStrdup(p->pA, (o3.azName&&o3.azName[k])?o3.azName[k]:"");
            }
            scopeAddRows(pScope, it->zAlias?it->zAlias:it->zTab, rb2, azCol, nCol, 0);
            arenaDelete(pA2);
            continue;
          }
          arenaDelete(pA2);
        }
        errSetPos(p->pErr, s->startPos, "no such table: %s", it->zTab);
        return 1;
      }
      scopeAddTable(pScope, it->zAlias?it->zAlias:it->zTab, t);""")
open('exec.c','w').write(c)
PY
grep -n "int nCol;" exec.c | head -3; cd /workspace && ./dev.sh 2>&1|grep -E "error"|head -5

