    *pOk = 1;
    return 1;
  }
  if( sscanf(z, "%d-%d-%d%n", &Y,&M,&D,&n)==3 ){
    jdValid = 1;
    if( n>=3 && (z[n]==' ' || z[n]=='T') ){
      int k = 0;
      n++;
      if( sscanf(z+n, "%d:%d%n", &h,&m,&n)==2 ){
        tValid = 1;
        if( n>=1 && z[n]==':' ){
          double ss;
          if( sscanf(z+n+1, "%lf%n", &ss,&k)==1 ){ s = ss; n += k; }
        }
