          int tz, k2 = 0;
          if( sscanf(z+n, "%d%n", &tz,&k2)==1 ){
            h -= tz/100;
            m -= tz%100;
            n += k2;
          }
        }
        if( z[n]=='Z' || z[n]=='z' ) n++;
      }
    }
  }else if( sscanf(z, "%d:%d%n", &h,&m,&n)==2 ){
    tValid = 1;
    jdValid = 1; Y=2000; M=1; D=1;
    if( n>=1 && z[n]==':' ){ double ss; int k=0; if( sscanf(z+n+1,"%lf%n",&ss,&k)==1 ){ s=ss; n+=k; } }
  }else{
    char *end;
    double d = strtod(z, &end);
    if( end>z ){
      while( *end==' ' ) end++;
      if( *end==0 ){ *pJd = d; *pOk = 1; return 1; }
    }
    return 0;
  }
  if( !jdValid ) return 0;
  {
    double jd = jdaysFromYMD(Y,M,D);
    if( tValid ) jd += (h*3600.0 + m*60.0 + s)/86400.0;
    *pJd = jd;
    *pOk = 1;
    return 1;
  }
}

