new = r'''/* iterate the join calling xFn for each row passing the ON constraints */
typedef struct JoinCtx {
  Select *s;
  Scope *pScope;
  Arena *pA;
  int (*xFn)(Eval*,CurRow*,void*);
  void *pArg;
  Value *flat;
  int width;
  int bAbort;
} JoinCtx;

static int joinRec(Eval *p, JoinCtx *pJ, int iSrc, CurRow *pCur){
  Scope *pScope = pJ->pScope;
  Select *s = pJ->s;
  SrcItem *it;
  int nRows;
  int bLeft;
  int nMatch = 0;
  int i;
  Table *t = 0;
  RowBuf *rb = 0;
  int iOff, iOffRid, nCol;
  if( iSrc>=pScope->nSrc ) return pJ->xFn(p, pCur, pJ->pArg);
  it = &s->pSrc->a[iSrc];
  t = pScope->a[iSrc].pTab;
  rb = pScope->a[iSrc].pRows;
  nRows = t ? t->nRow : (rb ? rb->n : 0);
  iOff = pScope->a[iSrc].iOff;
  iOffRid = pScope->a[iSrc].iOffRid;
  nCol = pScope->a[iSrc].nCol;
  bLeft = (it->joinType & (JT_LEFT|JT_FULL))!=0;
  for(i=0;i<nRows;i++){
    int j;
    int ok = 1;
    if( t ){
      Row *r = t->apRow[i];
      for(j=0;j<nCol;j++){ valInit(&pJ->flat[iOff+j]); valCopy(pJ->pA,&pJ->flat[iOff+j], r->aVal+j); }
      if( iOffRid>=0 ){ valInit(&pJ->flat[iOffRid]); valSetInt(pJ->pA,&pJ->flat[iOffRid], r->rowid); }
    }else if( rb ){
      for(j=0;j<nCol;j++){ valInit(&pJ->flat[iOff+j]); valCopy(pJ->pA,&pJ->flat[iOff+j], rb->ap[i]+j); }
    }
    if( it->pOn ){
      Value v;
      valInit(&v);
      evalExprIn(p, it->pOn, pScope, pCur, &v);
      if( !evalIsTrue(&v) ) ok = 0;
    }
    if( ok ){
      nMatch++;
      if( joinRec(p, pJ, iSrc+1, pCur) ) return 1;
    }
  }
  if( bLeft && nMatch==0 ){
    int j;
    for(j=0;j<nCol;j++){ valInit(&pJ->flat[iOff+j]); valSetNull(&pJ->flat[iOff+j]); }
    if( iOffRid>=0 ){ valInit(&pJ->flat[iOffRid]); valSetNull(&pJ->flat[iOffRid]); }
    if( joinRec(p, pJ, iSrc+1, pCur) ) return 1;
  }
  return 0;
}

static int iterateJoin(Eval *p, Scope *pScope, Select *s, int (*xFn)(Eval*,CurRow*,void*), void *pArg){
  JoinCtx j;
  CurRow cur;
  int i, width = 0;
  if( s->pSrc==0 || pScope->nSrc==0 ){
    cur.apFlat = 0;
    cur.aiRowid = 0;
    return xFn(p, &cur, pArg);
  }
  for(i=0;i<pScope->nSrc;i++) width += pScope->a[i].nCol + (pScope->a[i].bRowid?1:0);
  j.s = s;
  j.pScope = pScope;
  j.pA = p->pA;
  j.xFn = xFn;
  j.pArg = pArg;
  j.width = width;
  j.bAbort = 0;
  j.flat = arenaAlloc(p->pA, (width>0?width:1)*sizeof(Value));
  for(i=0;i<width;i++) valInit(&j.flat[i]);
  cur.apFlat = j.flat;
  cur.aiRowid = 0;
  return joinRec(p, &j, 0, &cur);
}

'''
c=c[:i]+new+c[j:]
open('exec.c','w').write(c)
PY
